INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '47b80fa0-9a26-42c9-b206-61ae34c527ca','Protection-grid correction','A frequency-dependent adjustment that accounts for how a measurement microphone''s protective grid or cap alters the high-frequency response by forming a small cavity and resonance in front of the diaphragm. Because published free-field and pressure corrections assume a specific grid state, the grid must be fitted as specified, and a separate correction applies if it is removed or changed.','The metal grille over a measurement mic protects the diaphragm. It also traps a little air and adds a small resonance. This slightly changes the high-frequency response. A grid correction accounts for that change. Using the wrong grid, or none, throws off the calibration.','It ensures accurate high-frequency measurements by including the acoustic effect of the protective grid in the microphone''s stated response.','A technician keeps the specified protection grid fitted during a free-field measurement, because removing it shifts the grid resonance and can change the response by several decibels near the top of the band.','Microphone Calibration',ARRAY['Pressure-field correction','Random-incidence correction','Free-field sensitivity','Primary calibration','Pressure sensitivity']::text[],ARRAY['Removing the grid for a measurement and forgetting that the published corrections no longer apply.','Mixing grids between capsule models, which changes the resonance and correction.','Assuming the grid has no acoustic effect because it looks acoustically open.']::text[],ARRAY['Preparing a measurement mic for high-frequency free-field work.','Explaining a response bump near the top octave from grid resonance.','Deciding whether to leave the grid on when using an electrostatic actuator.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Protection-grid correction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '47b80fa0-9a26-42c9-b206-61ae34c527ca','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='47b80fa0-9a26-42c9-b206-61ae34c527ca') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='47b80fa0-9a26-42c9-b206-61ae34c527ca');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '220022b9-b1f6-4854-9120-b66de49a0ef1','Pull-in voltage','The critical DC bias at which the electrostatic attraction between a movable electrode and a fixed backplate exceeds the mechanical restoring force, causing the electrode to snap shut across the remaining gap. This instability occurs when the electrode has moved about one third of the original gap, and it sets an upper limit on the polarization voltage of condenser and MEMS capsules.','A condenser mic pulls its plates together with electrostatic force. A spring in the diaphragm pushes back. If the charging voltage is too high, the pull wins. The diaphragm then slams onto the backplate and sticks. That voltage is the pull-in voltage. It limits how high the bias can go.','It defines the safe maximum bias voltage and the collapse point of an electrostatic transducer, guiding capsule and MEMS design.','For a gap d0 = 2 um, spring constant k = 10 N/m, plate area A = 1 mm^2 = 1e-6 m^2, the pull-in voltage is V_pi = sqrt(8*k*d0^3/(27*eps0*A)) = sqrt(8*10*8e-18/(27*8.85e-12*1e-6)) = about 1.6 V.','Electrostatic Instability',ARRAY['Polarization voltage','Sacrificial layer','Silicon-on-insulator','Pressure sensitivity','Pulse-density modulation microphone']::text[],ARRAY['Thinking the diaphragm becomes unstable only when it fully closes the gap; instability starts at about one third of the gap.','Assuming more bias is always better; approaching pull-in risks sudden collapse.','UNSAFE: Applying a bias near or above the pull-in voltage can permanently collapse and short the capsule through stiction; keep the polarization voltage well below V_pi.']::text[],ARRAY['Setting a safe bias margin for a MEMS microphone diaphragm.','Diagnosing a dead capsule that has collapsed onto its backplate.','Designing an electret gap that avoids electrostatic pull-in over temperature.']::text[],'advanced','V_pi = sqrt( 8 * k * d0^3 / (27 * eps0 * A) )','The pull-in voltage equals the square root of eight times the spring constant times the cube of the gap, divided by twenty-seven times the permittivity of free space times the electrode area.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pull-in voltage');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '220022b9-b1f6-4854-9120-b66de49a0ef1','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='220022b9-b1f6-4854-9120-b66de49a0ef1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='220022b9-b1f6-4854-9120-b66de49a0ef1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e66b4537-6a77-492f-89be-4c9855df0b4e','Pulse-density modulation','A one-bit coding scheme in which the analog amplitude is represented by the local density of high pulses in a fast binary stream, rather than by multi-bit sample values. It is the native output of a sigma-delta modulator: a louder or higher signal produces more ones per unit time, and the audio is recovered by low-pass filtering and decimation to multi-bit PCM.','Pulse-density modulation stores sound as a fast stream of ones and zeros. Louder parts pack in more ones. Quieter parts have more zeros. There are no multi-bit numbers, just the density of pulses. A filter later averages the stream back into normal audio samples.','It carries high-resolution audio over a single data line using a simple one-bit stream, easing the interface between a modulator and a decimation filter.','A digital MEMS microphone outputs a PDM stream at, for example, 3.072 MHz; the host codec low-pass filters and decimates it by 64 to produce 48 kHz PCM samples.','Digital Audio Coding',ARRAY['Sigma-delta modulator','Pulse-density modulation microphone','Pulse-code modulation','Silicon-on-insulator','Shot noise']::text[],ARRAY['Confusing pulse-density modulation with pulse-width modulation; PDM varies pulse count, not pulse duration.','Believing PDM is low quality because it is one bit; oversampling and noise shaping restore high resolution.','Forgetting that PDM must be low-pass filtered and decimated before it is usable audio.']::text[],ARRAY['Interfacing a MEMS microphone''s one-bit output to a processor.','Explaining why a MEMS mic needs a clock line as well as a data line.','Setting a decimation ratio to convert PDM to a target PCM sample rate.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pulse-density modulation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e66b4537-6a77-492f-89be-4c9855df0b4e','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e66b4537-6a77-492f-89be-4c9855df0b4e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e66b4537-6a77-492f-89be-4c9855df0b4e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '64c9422c-dd1d-4216-b00d-2e11828c4202','Pulse-density modulation microphone','A digital microphone, typically a silicon MEMS capsule, that integrates a sigma-delta modulator and outputs audio directly as a one-bit pulse-density-modulated stream clocked by the host. It needs an external clock and delivers a data line whose pulse density tracks the sound, letting two such microphones share a stereo data line by using opposite clock edges.','This is a tiny digital mic that outputs ones and zeros directly. It has a built-in converter that makes a pulse-density stream. The host chip sends it a clock and reads back the data. Two mics can share one line for stereo. Phones and laptops use these mics widely.','It provides a compact, all-digital microphone output that resists interference on the short board traces of phones, laptops, and voice devices.','A designer wires two PDM MEMS mics to one data line, selecting the left channel on the rising clock edge and the right channel on the falling edge, with a shared 2.4 MHz clock.','Digital Microphone',ARRAY['Pulse-density modulation','Sigma-delta modulator','Prepolarized condenser microphone','Silicon-on-insulator','Sacrificial layer']::text[],ARRAY['Expecting analog audio on the data pin; the output is a raw one-bit PDM stream needing decimation.','Leaving the clock stopped and wondering why there is no output; the mic needs a running clock.','Ignoring the low-power mode clock range, which lowers performance if used for high-quality capture.']::text[],ARRAY['Adding stereo MEMS mics to a laptop using a single shared data line.','Selecting clock frequency between standard and low-power modes.','Debugging a silent digital mic caused by a missing clock signal.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pulse-density modulation microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '64c9422c-dd1d-4216-b00d-2e11828c4202','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='64c9422c-dd1d-4216-b00d-2e11828c4202') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='64c9422c-dd1d-4216-b00d-2e11828c4202');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '176c9acf-e804-4879-8aa1-a91eb02cd568','Random-incidence correction','A frequency-dependent adjustment applied to a microphone''s response so that it reads correctly in a diffuse sound field, where sound arrives from all directions at once with random phase. It weights the microphone''s directional response over all angles, and measurement microphones intended for reverberant or diffuse fields are designed or corrected for flat random-incidence response.','In a reverberant room, sound comes from every direction. A mic responds differently to each angle. A random-incidence correction averages all those angles fairly. It makes the mic read correctly in this scattered sound. It differs from the correction used for a single on-axis source.','It ensures accurate sound measurements in diffuse or reverberant fields, such as reverberation rooms and many noise surveys.','For a diffuse-field noise measurement, the technician selects a random-incidence microphone (or applies the tabulated random-incidence corrector) instead of a free-field capsule aimed at a source.','Microphone Calibration',ARRAY['Pressure-field correction','Free-field sensitivity','Protection-grid correction','Sensitivity level','Secondary calibration']::text[],ARRAY['Using a free-field microphone in a diffuse field without applying the random-incidence correction.','Assuming all measurement mics are interchangeable regardless of field type.','Aiming a random-incidence mic at a source as if it were a free-field capsule.']::text[],ARRAY['Measuring sound power in a reverberation room.','Selecting the correct field-type microphone for a diffuse-field noise survey.','Applying tabulated corrections to convert between field types.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Random-incidence correction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '176c9acf-e804-4879-8aa1-a91eb02cd568','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='176c9acf-e804-4879-8aa1-a91eb02cd568') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='176c9acf-e804-4879-8aa1-a91eb02cd568');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '03a6d9a3-35df-4cc3-ae26-e239291d6a03','Reciprocity calibration','A primary, absolute calibration method that uses three reversible microphones measured in pairs, without any pre-calibrated reference. For each pair the electrical transfer impedance and the coupler''s or field''s acoustic transfer impedance give the product of the two sensitivities, and solving the three pair equations yields each microphone''s individual sensitivity.','Reciprocity calibration finds mic sensitivity with no reference mic. It uses three good condenser mics tested two at a time. Each pair gives the product of two sensitivities. With three pairs, you have three equations. Solving them gives each mic''s own sensitivity.','It delivers traceable primary sensitivities for laboratory standard microphones, anchoring the entire acoustic measurement chain.','With three capsules, solve M1 = sqrt( (Z_e12 * Z_e13) / (Z_e23) * (Z_a23) / (Z_a12 * Z_a13) ), where each Z_e is a measured electrical transfer impedance and each Z_a is a computed acoustic transfer impedance.','Microphone Calibration',ARRAY['Pressure reciprocity','Reciprocity parameter','Reciprocity transducer','Primary calibration','Secondary calibration']::text[],ARRAY['Trying it with only two microphones; three pairwise measurements are needed to separate the sensitivities.','Using a non-reversible microphone, which breaks the reciprocity assumption.','Neglecting coupler corrections such as heat conduction that bias the acoustic transfer impedance.']::text[],ARRAY['Assigning absolute sensitivities to a set of laboratory standard microphones.','Explaining why three capsules are required for a primary calibration.','Auditing a calibration lab''s traceability to primary standards.']::text[],'advanced','M_i * M_j = Z_e,ij / Z_a,ij ;  M1 = sqrt( (Z_e12 * Z_e13 * Z_a23) / (Z_e23 * Z_a12 * Z_a13) )','Each microphone pair''s sensitivity product equals its electrical transfer impedance divided by its acoustic transfer impedance; combining the three pair equations isolates one microphone''s sensitivity as the square root of a ratio of the measured transfer impedances.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reciprocity calibration');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '03a6d9a3-35df-4cc3-ae26-e239291d6a03','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='03a6d9a3-35df-4cc3-ae26-e239291d6a03') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='03a6d9a3-35df-4cc3-ae26-e239291d6a03');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '39acd539-83a8-4e0f-ae3f-06c4944e3ed0','Reciprocity parameter','A quantity that links a reversible transducer''s receiving sensitivity to its transmitting response, depending only on the acoustic medium and the geometry of the sound field, not on the transducer''s internal design. For a free-field spherical wave it takes the standard form J = 2d/(rho*f), which underpins free-field reciprocity calibration.','A reversible transducer can send and receive sound. The reciprocity parameter ties those two behaviors together. It depends only on the medium and the field shape. It does not depend on the mic''s build. For open-air spherical waves it has a simple formula.','It provides the universal link needed to derive an absolute receiving sensitivity from transmitting measurements in reciprocity calibration.','For a free-field spherical wave at distance d = 0.3 m, air density rho = 1.2 kg/m^3, frequency f = 1000 Hz, the parameter is J = 2*0.3/(1.2*1000) = 5e-4 in SI acoustic units.','Microphone Calibration',ARRAY['Reciprocity calibration','Reciprocity transducer','Pressure reciprocity','Primary calibration','Sensitivity level']::text[],ARRAY['Thinking the parameter depends on the transducer; it depends only on the medium and field geometry.','Using the free-field form in a closed coupler, which needs the pressure-field expression instead.','Dropping the factor of two or the distance term in the spherical-wave formula.']::text[],ARRAY['Deriving free-field sensitivity from transmitting measurements.','Explaining why reciprocity calibration needs no internal transducer model.','Choosing the correct parameter form for coupler versus free-field work.']::text[],'advanced','J = M / S = 2*d / (rho * f)','The reciprocity parameter is the ratio of receiving sensitivity to transmitting response; for a free-field spherical wave it equals two times the distance divided by the product of the medium density and the frequency.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reciprocity parameter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '39acd539-83a8-4e0f-ae3f-06c4944e3ed0','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='39acd539-83a8-4e0f-ae3f-06c4944e3ed0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='39acd539-83a8-4e0f-ae3f-06c4944e3ed0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '645ef810-185a-46f5-bc9a-c2d4397a9137','Reciprocity transducer','A transducer that is linear, passive, and reversible, so that its transmitting and receiving behaviors are tied together by the reciprocity theorem and it can serve interchangeably as a sound source and a sound receiver. Electrostatic condenser microphones satisfy this condition, which is why they are used as the reversible elements in primary reciprocity calibration.','A reciprocity transducer works equally well as a speaker or a mic. It is linear and adds no power of its own. So its sending and receiving are linked by math. Condenser capsules meet these rules. That is why they are used for reciprocity calibration.','It provides the reversible element required by reciprocity calibration, where the same device both emits and detects sound.','A calibration lab picks three electrostatic capsules as reciprocity transducers, driving each in turn as a source while another acts as the receiver in the coupler.','Microphone Calibration',ARRAY['Reciprocity calibration','Reciprocity parameter','Pressure reciprocity','Primary calibration','Prepolarized condenser microphone']::text[],ARRAY['Assuming any microphone is reciprocal; devices with active or nonlinear elements are not.','Confusing reversibility with simply being able to produce some sound output.','Forgetting that the linearity and passivity conditions must hold across the calibration band.']::text[],ARRAY['Selecting capsules suitable for a reciprocity calibration.','Explaining why dynamic moving-coil elements can also be reciprocal transducers.','Teaching the passive, linear, reversible criteria behind the method.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reciprocity transducer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '645ef810-185a-46f5-bc9a-c2d4397a9137','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='645ef810-185a-46f5-bc9a-c2d4397a9137') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='645ef810-185a-46f5-bc9a-c2d4397a9137');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5fc59e1b-b3dd-4f87-bd2f-15a570c6be24','Remote vibrometry','The non-contact measurement of a surface''s vibration from a distance, usually with a laser beam whose reflected light carries the surface velocity as a Doppler frequency shift. In an acoustic context it can act as an optical microphone, recovering sound by sensing the tiny vibrations that sound waves induce on a remote object or membrane.','Remote vibrometry measures how a surface shakes without touching it. A laser beam bounces off the surface. The reflected light shifts slightly with the surface''s motion. That shift reveals the vibration. Sound makes objects vibrate, so this can even recover sound from a distance.','It lets engineers measure vibration or sound where a physical sensor cannot be attached, such as hot, moving, light, or hard-to-reach surfaces.','A technician points a laser vibrometer at a loudspeaker cone or a distant window to read its vibration velocity without adding mass or wiring to the surface.','Optical Sensing',ARRAY['Scanning laser Doppler vibrometry','Resonant photoacoustic cell','Pressure sensitivity','Robust beamforming','Sparse microphone array']::text[],ARRAY['Assuming the laser measures displacement directly; a Doppler vibrometer measures velocity.','Expecting good results from a poorly reflecting surface without retroreflective treatment.','Ignoring that ambient vibration of the instrument itself can corrupt the reading.']::text[],ARRAY['Measuring a diaphragm''s motion without loading it with a sensor.','Recovering speech from the vibration of a remote surface.','Inspecting vibration on a hot or rotating part that cannot be touched.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Remote vibrometry');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5fc59e1b-b3dd-4f87-bd2f-15a570c6be24','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5fc59e1b-b3dd-4f87-bd2f-15a570c6be24') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5fc59e1b-b3dd-4f87-bd2f-15a570c6be24');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7d7ae8e7-6b23-4acd-9213-34f48f7a4d43','Resonant photoacoustic cell','An acoustic chamber tuned so that the sound generated by modulated light absorption in a gas builds up at one of the cavity''s resonance frequencies, greatly increasing the signal detected by an internal microphone. It is a core element of photoacoustic spectroscopy, where periodic heating by absorbed light creates pressure waves whose amplitude reveals the gas concentration.','Certain gases absorb pulsing light and heat up in time with it. That heating makes tiny pressure waves, a faint sound. A resonant photoacoustic cell is a chamber tuned to that sound''s frequency. The tuning makes the sound build up much louder. A mic inside then measures the gas.','It amplifies the weak photoacoustic signal by acoustic resonance, enabling sensitive detection of trace gases.','A gas analyzer modulates a laser at the cell''s acoustic resonance so the pressure signal builds up by the cell''s quality factor before the embedded microphone reads it.','Acoustic Sensing',ARRAY['Remote vibrometry','Pressure sensitivity','Sigma-delta modulator','Prepolarized condenser microphone','Sensitivity level']::text[],ARRAY['Assuming the cell works at any modulation rate; it must be driven at its acoustic resonance for the gain.','Ignoring that window absorption and wall noise add background signal.','Forgetting that temperature and gas composition shift the resonance frequency.']::text[],ARRAY['Building a trace-gas sensor using photoacoustic detection.','Tuning a laser modulation frequency to a cell resonance.','Explaining how sound amplifies a weak optical-absorption signal.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Resonant photoacoustic cell');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7d7ae8e7-6b23-4acd-9213-34f48f7a4d43','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7d7ae8e7-6b23-4acd-9213-34f48f7a4d43') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7d7ae8e7-6b23-4acd-9213-34f48f7a4d43');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2c82b3dc-4e1a-4a46-bbbe-eb0f42f36ab1','Robust beamforming','Microphone-array beamforming designed to keep good performance despite errors such as microphone gain and phase mismatch, position uncertainty, and imperfect knowledge of the desired signal''s direction. Common approaches add constraints or diagonal loading to adaptive beamformers so that small modeling errors do not cause the array to cancel the wanted source.','A mic array can steer its focus toward a talker. Real mics are never perfectly matched, and positions are never exact. A plain adaptive beamformer can misbehave under these errors. Robust beamforming adds safety margins to the math. It keeps the wanted voice from being cancelled by mistake.','It makes array processing dependable in real hardware, where calibration and geometry are never perfect.','An engineer adds diagonal loading to an MVDR (minimum variance distortionless response) beamformer so a small steering error near the desired direction no longer suppresses the talker.','Array Processing',ARRAY['Sparse microphone array','Pulse-density modulation microphone','Source impedance','Remote vibrometry','Sensitivity level']::text[],ARRAY['Assuming perfectly matched microphones, so an adaptive beamformer cancels the target under tiny errors.','Setting diagonal loading arbitrarily instead of tying it to expected error size.','Confusing robustness to steering error with simple noise reduction.']::text[],ARRAY['Designing a conference-room array that tolerates mic mismatch.','Stabilizing an adaptive beamformer that cancels the desired talker.','Choosing a loading level to trade sharpness for reliability.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Robust beamforming');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2c82b3dc-4e1a-4a46-bbbe-eb0f42f36ab1','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2c82b3dc-4e1a-4a46-bbbe-eb0f42f36ab1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2c82b3dc-4e1a-4a46-bbbe-eb0f42f36ab1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cebfd0ce-60c3-4f77-aa71-3a214ca969e1','Sacrificial layer','In MEMS surface micromachining, a temporary material layer deposited under a structural layer and later chemically etched away to leave a free-standing, movable structure such as a microphone diaphragm suspended over an air gap. Silicon dioxide or phosphosilicate glass is a common sacrificial material, removed by a selective etch that leaves the structural layer intact.','MEMS mics are built in stacked thin films on silicon. One layer is placed only to be removed later. It holds up the diaphragm layer during building. Then a chemical etch dissolves that layer away. This leaves the diaphragm free to move over an empty gap.','It creates the empty gap and released moving parts that a MEMS microphone needs, by acting as a temporary spacer during fabrication.','A MEMS process grows an oxide sacrificial layer, deposits the diaphragm on top, then uses a timed hydrofluoric-acid etch to remove the oxide and free the diaphragm.','MEMS Fabrication',ARRAY['Silicon-on-insulator','Pull-in voltage','Pulse-density modulation microphone','Prepolarized condenser microphone','Sensitivity level']::text[],ARRAY['Thinking the sacrificial layer stays in the finished device; it is deliberately removed.','Over-etching, which can undercut anchors and let the structure stick down (stiction).','Confusing the sacrificial layer with the permanent structural layer it supports.']::text[],ARRAY['Explaining how a MEMS diaphragm is released over its back cavity.','Diagnosing stiction failures from sacrificial-etch problems.','Comparing surface micromachining with bulk micromachining.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sacrificial layer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cebfd0ce-60c3-4f77-aa71-3a214ca969e1','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cebfd0ce-60c3-4f77-aa71-3a214ca969e1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cebfd0ce-60c3-4f77-aa71-3a214ca969e1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd9623549-b63a-4210-a39b-0a0c667c1191','Scanning laser Doppler vibrometry','A non-contact measurement technique that steers a laser Doppler vibrometer beam point by point across a surface to map its full vibration pattern, deriving velocity at each point from the Doppler shift of the reflected light. It is widely used to visualize the mode shapes and break-up behavior of microphone and loudspeaker diaphragms.','A laser vibrometer measures how one spot vibrates. A scanning version moves the beam across a whole surface. It records the motion at many points in turn. Software then builds a full map of the vibration. Engineers use it to see how diaphragms flex and resonate.','It reveals how an entire diaphragm or panel moves, exposing resonances and break-up modes that a single-point sensor would miss.','A technician runs a scanning vibrometer over a loudspeaker cone driven by a swept tone to map the frequencies where the cone breaks into uneven modal motion.','Optical Sensing',ARRAY['Remote vibrometry','Pressure sensitivity','Sparse microphone array','Robust beamforming','Sensitivity level']::text[],ARRAY['Expecting instantaneous full-field data; the beam scans points in sequence and needs a repeatable excitation.','Confusing measured velocity with displacement without integrating.','Overlooking surface reflectivity, which affects signal quality at each scan point.']::text[],ARRAY['Mapping the mode shapes of a loudspeaker cone.','Characterizing a MEMS or condenser diaphragm''s break-up frequencies.','Validating a finite-element vibration model against measured motion.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Scanning laser Doppler vibrometry');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd9623549-b63a-4210-a39b-0a0c667c1191','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d9623549-b63a-4210-a39b-0a0c667c1191') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d9623549-b63a-4210-a39b-0a0c667c1191');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7d07d5bc-27e7-469f-a383-e607d2a8a680','Secondary calibration','A calibration performed by comparing a microphone against a reference microphone whose sensitivity is already known from a primary calibration, rather than from first principles. Common methods include coupler comparison for pressure sensitivity and substitution in a free field, and the result inherits and adds to the uncertainty of the reference.','Secondary calibration compares a mic to a trusted reference mic. The reference was measured first by a primary method. You expose both to the same sound. Then you scale the test mic to match the reference. It is faster than a primary calibration but slightly less certain.','It provides practical, routine calibration of working and field microphones by transferring the accuracy of a primary standard.','In a coupler, a technician places the test mic and a reference mic in the same pressure field and computes the test sensitivity as the reference sensitivity times the ratio of their output voltages.','Microphone Calibration',ARRAY['Primary calibration','Reciprocity calibration','Pressure sensitivity','Sensitivity level','Random-incidence correction']::text[],ARRAY['Believing a comparison result can be more accurate than the reference it relies on.','Placing the two mics in slightly different fields, which biases the comparison.','Skipping regular recalibration of the reference microphone itself.']::text[],ARRAY['Routine annual calibration of field measurement microphones.','Transferring a laboratory reference sensitivity to working mics.','Cross-checking a suspect microphone against a known good one.']::text[],'intermediate','M_test = M_ref * (e_test / e_ref)','The test microphone''s sensitivity equals the reference microphone''s sensitivity multiplied by the ratio of the test output voltage to the reference output voltage in the same field.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Secondary calibration');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7d07d5bc-27e7-469f-a383-e607d2a8a680','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7d07d5bc-27e7-469f-a383-e607d2a8a680') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7d07d5bc-27e7-469f-a383-e607d2a8a680');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5c8e6548-b2f8-4f0b-b3dd-4d6f57f9aa7e','Sensitivity level','A microphone''s sensitivity expressed on a logarithmic decibel scale relative to a stated reference, typically 1 volt per pascal for the open-circuit voltage response. Because most microphones give far less than 1 V/Pa, the sensitivity level is a negative number, and it is used because it combines conveniently with sound-pressure and signal levels in decibels.','Sensitivity level restates a mic''s output in decibels. It compares the mic''s volts-per-pascal to a reference of one volt per pascal. Most mics give much less than that, so the number is negative. Decibels make it easy to add to other level figures. Datasheets use this form often.','It puts microphone sensitivity into decibels so it adds directly to sound and signal levels in gain and headroom calculations.','A capsule with sensitivity M = 12.5 mV/Pa has a sensitivity level L_M = 20*log10(0.0125/1) = -38.1 dB re 1 V/Pa.','Microphone Specification',ARRAY['Pressure sensitivity','Source impedance','Preamplifier voltage noise','Secondary calibration','Prepolarized condenser microphone']::text[],ARRAY['Reading a negative sensitivity level as a fault; nearly all microphones read negative against 1 V/Pa.','Forgetting the reference; a level is meaningless without ''re 1 V/Pa'' or the stated reference.','Using 10*log10 instead of 20*log10 for a voltage ratio.']::text[],ARRAY['Comparing two microphones'' sensitivities from their datasheets.','Estimating preamp gain needed for a target output level.','Converting a millivolt-per-pascal figure to decibels for a system budget.']::text[],'intermediate','L_M = 20 * log10( M / M_ref )','The sensitivity level equals twenty times the base-ten logarithm of the microphone sensitivity divided by the reference sensitivity.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sensitivity level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5c8e6548-b2f8-4f0b-b3dd-4d6f57f9aa7e','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5c8e6548-b2f8-4f0b-b3dd-4d6f57f9aa7e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5c8e6548-b2f8-4f0b-b3dd-4d6f57f9aa7e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0f134c23-127d-4f38-b0cb-b2b79e67f6e0','Shot noise','Electrical noise arising from the discrete, random arrival of individual charge carriers crossing a barrier such as a semiconductor junction, giving a white noise current whose mean-square value is proportional to the average current. It contributes to the input current noise of microphone preamplifiers and to the noise of photodetectors used in optical microphones.','Electric current is really a stream of separate charges. They cross a junction at random moments, not perfectly evenly. This randomness makes a faint hiss called shot noise. It grows with the average current flowing. It adds to the noise in preamps and light detectors.','It models a fundamental noise floor set by the graininess of charge flow, important for low-noise preamp and optical-sensor design.','For a junction leakage current I = 10 pA, the shot-noise current density is i_n = sqrt(2*q*I) = sqrt(2*1.6e-19*1e-11) = 1.8e-15 A/rtHz = 1.8 fA/rtHz.','Noise Mechanism',ARRAY['Preamplifier current noise','Preamplifier voltage noise','Source impedance','Sigma-delta modulator','Sensitivity level']::text[],ARRAY['Confusing shot noise with thermal noise; shot noise needs a DC current and a barrier, not just resistance.','Thinking shot noise depends on temperature; to first order it depends on current, not temperature.','Assuming it is negligible at very low currents where it can still limit sensitive front ends.']::text[],ARRAY['Estimating the current-noise floor of a JFET input preamp.','Analyzing photodiode noise in an optical microphone.','Comparing shot noise and thermal noise contributions in a front end.']::text[],'advanced','i_n = sqrt( 2 * q * I * BW )   (density: sqrt(2*q*I))','The shot-noise current equals the square root of twice the electron charge times the average current times the bandwidth; the density is the square root of twice the charge times the current.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Shot noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0f134c23-127d-4f38-b0cb-b2b79e67f6e0','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0f134c23-127d-4f38-b0cb-b2b79e67f6e0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0f134c23-127d-4f38-b0cb-b2b79e67f6e0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5ca9799b-b374-43ed-ba64-98bf3f6435e0','Shotgun interference tube','The slotted or ported tube mounted in front of a shotgun microphone capsule that sharpens directivity at high frequencies. Off-axis sound entering the side slots travels different path lengths and arrives partly out of phase at the capsule, causing destructive interference that attenuates sound from the sides while on-axis sound stays in phase.','A shotgun mic has a long slotted tube in front of the capsule. Sound from the side enters the slots at different points. These paths differ in length, so the waves partly cancel at the capsule. Sound from straight ahead does not cancel. The result is a narrow pickup from the front.','It narrows a microphone''s high-frequency pickup so it favors an on-axis source and rejects sound from the sides.','A boom operator aims a shotgun mic so the interference tube points at the actor''s mouth, using its narrow front lobe to reject nearby crew and reflections.','Directional Microphone',ARRAY['Pop-noise suppression','Random-incidence correction','Sparse microphone array','Robust beamforming','Pressure sensitivity']::text[],ARRAY['Believing the tube adds gain to the front; it works by attenuating off-axis sound, not boosting on-axis.','Expecting the same narrow directivity at low frequencies, where the tube is too short to help.','Covering or blocking the tube slots, which destroys the interference effect.']::text[],ARRAY['Booming dialog on a film set with a shotgun microphone.','Explaining why shotgun directivity worsens at low frequencies.','Choosing tube length for a required degree of directionality.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Shotgun interference tube');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5ca9799b-b374-43ed-ba64-98bf3f6435e0','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5ca9799b-b374-43ed-ba64-98bf3f6435e0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5ca9799b-b374-43ed-ba64-98bf3f6435e0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '18feecb5-4a89-4135-93ec-8f80d9ba0668','Sigma-delta modulator','An oversampling converter stage that quantizes a signal coarsely, often to one bit, while using feedback and integration to push most quantization noise out of the audio band to high frequencies. This noise shaping, combined with heavy oversampling and later digital filtering, yields high in-band resolution and is the engine behind pulse-density-modulated and MEMS digital microphones.','A sigma-delta modulator turns audio into a fast, coarse bitstream. It samples far above the audio rate. Feedback pushes its quantization noise up above the hearing range. A later filter removes that high noise. What remains is clean, high-resolution audio.','It achieves high audio resolution from a simple low-bit quantizer by trading sample rate for in-band accuracy through noise shaping.','For an ideal first-order modulator with a one-bit quantizer (N=1) and oversampling ratio OSR=64, the peak SNR is about 6.02*1 + 1.76 - 5.17 + 30*log10(64) = 56.8 dB.','Digital Audio Coding',ARRAY['Pulse-density modulation','Pulse-density modulation microphone','Silicon-on-insulator','Shot noise','Sensitivity level']::text[],ARRAY['Thinking a one-bit output means low quality; oversampling and noise shaping give high in-band resolution.','Ignoring modulator order; higher order shapes noise more steeply for a given OSR.','Confusing the modulator with the decimation filter that follows it.']::text[],ARRAY['Explaining the converter inside a digital MEMS microphone.','Choosing an oversampling ratio and order for a target SNR.','Understanding why a PDM stream needs later digital filtering.']::text[],'advanced','SNR_max = 6.02*N + 1.76 - 5.17 + 30*log10(OSR)   (ideal first-order)','For an ideal first-order modulator, the peak signal-to-noise ratio equals the quantizer''s ideal figure plus a noise-shaping term that grows by about thirty decibels for each tenfold rise in the oversampling ratio.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sigma-delta modulator');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '18feecb5-4a89-4135-93ec-8f80d9ba0668','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='18feecb5-4a89-4135-93ec-8f80d9ba0668') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='18feecb5-4a89-4135-93ec-8f80d9ba0668');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '53d9e7dc-51a6-436e-b8d8-ddb5f8641514','Silicon-on-insulator','A wafer structure with a thin single-crystal silicon device layer sitting on a buried oxide insulating layer over a silicon handle wafer. In MEMS microphones the buried oxide acts as a precise etch stop and spacer, letting fabricators define well-controlled diaphragm thickness and gaps in single-crystal silicon.','Silicon-on-insulator is a special layered wafer. A thin silicon top layer sits on a buried glass-like oxide. Under that is a thick silicon base. The buried layer sets an exact thickness and stops etching cleanly. MEMS makers use it to build precise diaphragms.','It gives fabricators tight control of layer thickness and a reliable etch stop, improving the precision of MEMS mechanical structures.','A MEMS process uses the buried oxide of an SOI wafer as an etch stop so the released diaphragm has exactly the device-layer thickness.','MEMS Fabrication',ARRAY['Sacrificial layer','Pull-in voltage','Pulse-density modulation microphone','Sigma-delta modulator','Prepolarized condenser microphone']::text[],ARRAY['Confusing the buried oxide with a surface sacrificial layer; they serve different roles.','Assuming SOI is only for electronics; it is also valued for precise MEMS structures.','Overlooking that the handle wafer is later thinned or etched to open the back cavity.']::text[],ARRAY['Explaining how a precise MEMS diaphragm thickness is achieved.','Comparing SOI-based and surface-micromachined microphone processes.','Understanding etch-stop choices in MEMS fabrication.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Silicon-on-insulator');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '53d9e7dc-51a6-436e-b8d8-ddb5f8641514','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='53d9e7dc-51a6-436e-b8d8-ddb5f8641514') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='53d9e7dc-51a6-436e-b8d8-ddb5f8641514');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bb45b025-f080-40a5-a6fc-2671fa0fb093','Source impedance','The internal output impedance a microphone presents to whatever it drives, setting how its signal divides between the source and the load and how much noise current it converts to voltage. Dynamic microphones show a low, mostly resistive source impedance of a few hundred ohms, while a raw condenser capsule is extremely high and capacitive, requiring a built-in impedance converter.','Source impedance is how hard it is to draw signal from a mic''s output. A dynamic mic has a low, steady value of a few hundred ohms. A bare condenser capsule has a huge, capacitive impedance. That is why condensers include a buffer. The preamp input should be much higher than this value.','It governs signal transfer to the preamp, loading losses, and how source-related noise appears, guiding correct interfacing.','With a dynamic mic source impedance Z_s = 200 ohm feeding a preamp input Z_L = 2 kohm, the transferred fraction is Z_L/(Z_s+Z_L) = 2000/2200 = 0.909, a loss of about 0.83 dB.','Microphone Specification',ARRAY['Preamplifier current noise','Preamplifier voltage noise','Sensitivity level','Prepolarized condenser microphone','Pressure sensitivity']::text[],ARRAY['Matching the load impedance to the source; audio uses bridging, with the load much higher than the source.','Ignoring the capacitive nature of a raw condenser source, which makes its impedance rise at low frequency.','Loading a mic with too low an input impedance, causing level loss and altered frequency response.']::text[],ARRAY['Interfacing a dynamic microphone to a preamp with the right input impedance.','Explaining why a condenser capsule needs an internal impedance converter.','Diagnosing level loss from a low-impedance input loading the mic.']::text[],'intermediate','V_L = V_s * Z_L / (Z_s + Z_L)','The voltage delivered to the load equals the source voltage times the load impedance divided by the sum of the source and load impedances.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Source impedance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bb45b025-f080-40a5-a6fc-2671fa0fb093','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bb45b025-f080-40a5-a6fc-2671fa0fb093') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bb45b025-f080-40a5-a6fc-2671fa0fb093');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'abf4fabc-f6a9-460a-ada7-6c82a59797e0','Sparse microphone array','A microphone array whose elements are placed non-uniformly or more widely than half-wavelength spacing, using far fewer microphones than a fully populated array of the same aperture. Designs such as random, nested, and co-prime arrays trade continuous full sampling for reduced element count while managing spatial aliasing and sidelobe behavior.','A microphone array uses many mics to locate or focus on sound. A sparse array uses fewer mics spread out unevenly. It keeps a wide overall span with less hardware. Clever spacing patterns limit false directions and side lobes. This saves cost and channels.','It reaches a large aperture and fine spatial resolution with fewer microphones, cutting hardware and channel count.','An engineer uses a co-prime spacing pattern to build an array that resolves sources like a much larger uniform array while using only a fraction of the microphones.','Array Processing',ARRAY['Robust beamforming','Pulse-density modulation microphone','Shotgun interference tube','Source impedance','Sensitivity level']::text[],ARRAY['Assuming wide spacing is free; it can raise grating lobes and spatial aliasing if not designed carefully.','Confusing fewer microphones with worse resolution; aperture, not count alone, sets resolution.','Ignoring that sparse geometries need matched processing to suppress the extra sidelobes.']::text[],ARRAY['Designing a low-cost array with a large aperture for source localization.','Choosing a co-prime or nested layout to limit spatial aliasing.','Trading microphone count against sidelobe performance.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sparse microphone array');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'abf4fabc-f6a9-460a-ada7-6c82a59797e0','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='abf4fabc-f6a9-460a-ada7-6c82a59797e0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='abf4fabc-f6a9-460a-ada7-6c82a59797e0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3a8c4f53-8236-4481-8167-e130e94f8c08','Spatial covariance matrix','In microphone-array processing, the spatial covariance matrix is the M-by-M matrix of cross-correlations between the M sensor signals, R = E{x x^H}, where x is the vector of complex sensor outputs at one frequency. Its entries capture the amplitude and phase relationships between channels and encode the directions and powers of the incident sound field.','A microphone array has many capsules. This matrix stores how each pair of capsules relates. It holds signal strength and timing links between channels. Beamformers use it to find where sound comes from.','It summarizes the second-order statistics of the array signals so a beamformer or direction finder can separate sources by their spatial signatures.','A technician estimates it by averaging x x^H over many time frames; for a 4-mic array it is a 4-by-4 matrix, and its eigenvectors reveal the signal and noise subspaces.','Array signal processing',ARRAY['Steering vector','Spatial whitening','Subband beamforming','Superdirectivity','Time-domain beamforming']::text[],ARRAY['Confusing the spatial covariance matrix with a time covariance of one channel.','Using too few snapshots, giving a rank-deficient, unreliable estimate.','Forgetting it is frequency-dependent in wideband arrays.']::text[],ARRAY['Building an adaptive beamformer for a conference microphone array.','Running MUSIC or MVDR direction-of-arrival estimation.','Diagnosing why a beamformer fails with too little averaging.']::text[],'advanced','R = E{ x x^H }','The spatial covariance matrix equals the expected value of the sensor snapshot vector times its own conjugate transpose.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spatial covariance matrix');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3a8c4f53-8236-4481-8167-e130e94f8c08','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3a8c4f53-8236-4481-8167-e130e94f8c08') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3a8c4f53-8236-4481-8167-e130e94f8c08');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ca19da4b-c798-44d4-a849-72cf391cc8df','Spatial whitening','Spatial whitening is a linear transform applied to array signals that makes the noise spatial covariance equal to the identity, typically by multiplying the snapshot vector by the inverse square root of the noise covariance. It de-correlates and normalizes the noise across channels so later detection or beamforming sees spatially white noise.','Array noise is often linked between capsules. Whitening removes those links. It makes the noise look equal and independent on every channel. This helps later steps find real sources.','It transforms colored, correlated sensor noise into uniform, uncorrelated noise so detectors and beamformers can use simpler, optimal decision rules.','A technician applies the inverse square root of the measured noise covariance to each snapshot before beamforming; after whitening, an MVDR beamformer reduces to a matched filter on the steering vector.','Array signal processing',ARRAY['Spatial covariance matrix','Steering vector','Superdirectivity','Subband beamforming']::text[],ARRAY['Whitening with a signal-plus-noise covariance instead of noise-only, which cancels the wanted signal.','Assuming whitening changes source direction; it changes noise statistics, not geometry.','Ignoring that the noise covariance must be well estimated and invertible.']::text[],ARRAY['Pre-processing before an optimal detector in a noisy array.','Deriving an MVDR beamformer as whitening plus matched filter.','Handling wind or diffuse noise correlated across capsules.']::text[],'advanced','y = R_n^(-1/2) x','The whitened signal equals the inverse matrix square root of the noise covariance times the sensor snapshot vector.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spatial whitening');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ca19da4b-c798-44d4-a849-72cf391cc8df','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ca19da4b-c798-44d4-a849-72cf391cc8df') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ca19da4b-c798-44d4-a849-72cf391cc8df');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'df4ec162-087e-4f0c-956b-f04130030af9','Speckle interferometry','Speckle interferometry is an optical, non-contact technique that measures tiny surface vibration or displacement by analyzing the interference ''speckle'' pattern formed when coherent laser light scatters from a rough surface. In microphone work it maps how a diaphragm moves without loading it with a physical sensor.','Laser light hits a rough surface and makes a grainy pattern. Tiny surface motion shifts that pattern. A camera tracks the shifts to measure movement. It needs no contact, so it does not weigh down the diaphragm.','It lets engineers visualize and quantify diaphragm or membrane motion across the whole surface without adding mass or touching it.','A lab uses electronic speckle-pattern interferometry to image a condenser diaphragm''s mode shapes at resonance, revealing where it flexes rather than moving as a rigid piston.','Optical measurement',ARRAY['Laser Doppler vibrometry','Optical interferometric sensing','Remote vibrometry','Scanning laser Doppler vibrometry']::text[],ARRAY['Thinking it measures sound pressure directly; it measures surface motion.','Confusing single-point laser Doppler vibrometry with full-field speckle interferometry.','Ignoring that stray vibration and air currents corrupt the speckle pattern.']::text[],ARRAY['Mapping diaphragm breakup modes in research.','Validating a finite-element model of a microphone membrane.','Checking MEMS diaphragm motion without electrical loading.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Speckle interferometry');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'df4ec162-087e-4f0c-956b-f04130030af9','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='df4ec162-087e-4f0c-956b-f04130030af9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='df4ec162-087e-4f0c-956b-f04130030af9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '94dbfa01-d358-4c25-92ee-f00950d13ed9','Spherical microphone array','A spherical microphone array places microphones on or in the surface of a rigid or open sphere so the sound field can be decomposed into spherical harmonics. This geometry supports 3-D beamforming and Ambisonic recording with nearly direction-independent behavior.','This array puts microphones over a ball shape. The round layout captures sound from every direction. Its signals split neatly into spherical harmonic parts. Engineers use it for 3-D sound capture and steering.','It captures a full 3-D sound field and lets beams steer in any direction with consistent shape, ideal for Ambisonics and room analysis.','A technician records with a rigid-sphere array (for example 32 capsules) and encodes to higher-order Ambisonics; the sphere radius sets the usable upper frequency before spatial aliasing.','Array geometry',ARRAY['Volumetric microphone array','Steering vector','Superdirectivity','Spatial covariance matrix','Tapering function']::text[],ARRAY['Assuming more capsules always help; spacing sets an aliasing limit.','Ignoring the rigid-sphere scattering that must be modeled in the math.','Confusing the array with a single multi-pattern microphone.']::text[],ARRAY['Higher-order Ambisonic music recording.','Sound-field visualization and source localization in a room.','Spatial audio capture for virtual reality.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spherical microphone array');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '94dbfa01-d358-4c25-92ee-f00950d13ed9','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='94dbfa01-d358-4c25-92ee-f00950d13ed9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='94dbfa01-d358-4c25-92ee-f00950d13ed9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cf3c3542-c25f-4ef5-b6c3-009b6c70e769','Static capacitance','The static capacitance of a condenser microphone is the capacitance of its capsule (the diaphragm-to-backplate capacitor) at rest with no sound present. It is set by electrode area, spacing, and dielectric, and with the load resistance it helps fix the low-frequency limit of the capsule.','A condenser mic capsule is a tiny capacitor. Static capacitance is its value when silent. Plate size and gap set this value. It works with the load resistor to shape low-frequency response.','It is a core capsule parameter that fixes electrical impedance and, with the load network, the low-frequency roll-off and noise behavior.','For plate area A and gap d, C = e0*er*A/d; a typical 1-inch measurement capsule has a static capacitance of roughly 50 to 60 pF (a 1/2-inch capsule is about 15 to 20 pF), which the preamp input resistance must work against.','Condenser capsule',ARRAY['Temperature coefficient','Static-pressure coefficient','Voltage-noise density','Working standard microphone']::text[],ARRAY['Confusing static capacitance with the tiny sound-driven capacitance change that makes the signal.','Ignoring that a very small capacitance needs a very high load resistance for good low-frequency response.','Forgetting stray cable capacitance adds to the capsule value at the preamp input.']::text[],ARRAY['Designing the preamp input resistance for a condenser capsule.','Explaining low-frequency roll-off of an externally polarized mic.','Matching a capsule to a tube or FET front end.']::text[],'intermediate','C = e0 er A / d','Static capacitance equals the permittivity of free space times the relative permittivity times the electrode area, divided by the gap spacing.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Static capacitance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cf3c3542-c25f-4ef5-b6c3-009b6c70e769','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cf3c3542-c25f-4ef5-b6c3-009b6c70e769') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cf3c3542-c25f-4ef5-b6c3-009b6c70e769');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8f81053d-6abb-4bc3-9232-97f3f5ed6825','Static-pressure coefficient','The static-pressure coefficient of a measurement microphone is the change in its sensitivity level per unit change in ambient (barometric) static pressure, in dB/kPa. It quantifies how altitude or weather-driven pressure shifts bias the microphone''s calibration.','Air pressure changes with weather and altitude. This coefficient says how much sensitivity drifts per pressure change. It is given in decibels per kilopascal. Labs use it to correct their readings.','It lets metrologists correct a microphone''s calibrated sensitivity for the actual barometric pressure at the time and place of measurement.','With a coefficient near -0.01 dB/kPa, a drop of about 15 kPa (roughly sea level to 1500 m) shifts sensitivity by about +0.15 dB, which the technician applies as a correction.','Environmental coefficient',ARRAY['Temperature coefficient','Static capacitance','Working standard microphone','Substitution calibration','Transfer standard microphone']::text[],ARRAY['Confusing static (barometric) pressure with the sound pressure being measured.','Ignoring the correction when calibrating with a pistonphone at altitude.','Assuming the coefficient is the same at all frequencies.']::text[],ARRAY['Correcting a pistonphone calibration for local barometric pressure.','Using a lab microphone at high altitude.','Meeting IEC 61094 tolerances for a working standard mic.']::text[],'advanced','K_p = dL_M / dp_s','The static-pressure coefficient equals the change in sensitivity level divided by the change in ambient static pressure.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Static-pressure coefficient');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8f81053d-6abb-4bc3-9232-97f3f5ed6825','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8f81053d-6abb-4bc3-9232-97f3f5ed6825') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8f81053d-6abb-4bc3-9232-97f3f5ed6825');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c534b7d1-d10c-40bc-9d44-9e2ee1a681a7','Steering vector','A steering vector (array manifold vector) is the M-by-1 complex vector describing the relative phase and amplitude each of the M microphones applies to a plane wave arriving from a given direction and frequency. It encodes the array''s response to a source at that angle.','Sound from one direction reaches each capsule at a slightly different time. The steering vector lists those phase shifts for all capsules. It depends on the angle and the frequency. Beamformers point using it.','It mathematically points the array at a chosen direction, forming the reference the beamformer aligns signals to.','For source direction u, element m at position r_m has steering entry exp(-j 2 pi f (r_m . u)/c); a delay-and-sum beam multiplies each channel by the conjugate of this vector and sums.','Array signal processing',ARRAY['Spatial covariance matrix','Time-domain beamforming','Superdirectivity','Tapering function','Time difference of arrival']::text[],ARRAY['Forgetting the steering vector is frequency-dependent.','Using geometric delays that do not match the real array positions.','Ignoring sensor gain and phase mismatch that corrupts the ideal manifold.']::text[],ARRAY['Setting the look direction of a delay-and-sum beamformer.','Building the MVDR direction constraint.','Scanning angles in MUSIC direction finding.']::text[],'advanced','a_m(theta) = exp( -j 2 pi f tau_m ),  tau_m = (r_m . u)/c','Each steering-vector entry is a unit phasor whose phase is minus two pi times frequency times the sensor''s propagation delay for that direction.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Steering vector');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c534b7d1-d10c-40bc-9d44-9e2ee1a681a7','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c534b7d1-d10c-40bc-9d44-9e2ee1a681a7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c534b7d1-d10c-40bc-9d44-9e2ee1a681a7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0b9de204-2737-4bd5-b577-90cae2f4b0a2','Subband beamforming','Subband beamforming splits each microphone signal into multiple frequency bands (via a filter bank or FFT) and applies a separate, frequency-appropriate set of beamformer weights in each band before recombining. It handles the fact that optimal array weights depend strongly on frequency.','A mic array works differently at low and high pitches. Subband beamforming breaks the sound into frequency bands. It steers each band with its own settings. Then it joins the bands back together.','It gives frequency-dependent control so one beamformer can stay directional and stable across a wide bandwidth.','A technician runs an FFT-based filter bank, computes weights per bin (for example wider beams at low frequency, narrower at high), then reconstructs; this is standard in speech-enhancement arrays.','Array signal processing',ARRAY['Time-domain beamforming','Spatial covariance matrix','Steering vector','Superdirectivity','Tapering function']::text[],ARRAY['Assuming one fixed weight set works for all frequencies.','Ignoring filter-bank delay and aliasing between bands.','Confusing subband (frequency-domain) with time-domain delay-and-sum.']::text[],ARRAY['Speech enhancement in a smart-speaker array.','Wideband source separation.','Keeping beamwidth roughly constant across frequency.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Subband beamforming');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0b9de204-2737-4bd5-b577-90cae2f4b0a2','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0b9de204-2737-4bd5-b577-90cae2f4b0a2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0b9de204-2737-4bd5-b577-90cae2f4b0a2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'db7fab3d-9f82-4a1e-adfb-261a89cb37a4','Substitution calibration','Substitution (comparison) calibration determines an unknown microphone''s sensitivity by placing it, then a reference microphone of known sensitivity, in the same sound field and comparing their outputs. It transfers the reference''s calibration to the test microphone without an absolute (primary) measurement.','You can calibrate a mic by comparing it to a known one. Put each in the same sound. Read both outputs. The known mic''s value gives the unknown mic''s sensitivity.','It provides a practical, traceable way to calibrate microphones by comparison with a reference, avoiding complex primary methods.','A technician exposes the reference and test mics to the same source (swapping them at the same point, or in a coupler) and computes the test sensitivity from the output-level difference plus the reference value.','Calibration method',ARRAY['Working standard microphone','Transfer standard microphone','Static-pressure coefficient','Temperature coefficient']::text[],ARRAY['Placing the two mics in slightly different sound fields, adding error.','Assuming substitution gives primary-level accuracy; it inherits the reference''s uncertainty.','Ignoring environmental corrections (pressure, temperature) during the comparison.']::text[],ARRAY['Comparison calibration in an acoustics lab.','Field calibration against a reference mic.','Verifying a mic before a critical measurement.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Substitution calibration');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'db7fab3d-9f82-4a1e-adfb-261a89cb37a4','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='db7fab3d-9f82-4a1e-adfb-261a89cb37a4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='db7fab3d-9f82-4a1e-adfb-261a89cb37a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7f647705-c8cf-4001-b4fd-e3d756bd314d','Superdirectivity','Superdirectivity is array behavior in which the directivity is higher than that of a same-size array with uniform (delay-and-sum) weighting, achieved by optimizing weights against a diffuse or isotropic noise field. It is most useful for arrays small compared with the wavelength, but it increases sensitivity to sensor noise and mismatch.','A small array can be made surprisingly directional. Superdirectivity does this with special weight settings. It fights diffuse background noise well. But it also raises self-noise and needs well-matched capsules.','It maximizes directivity for a small aperture, useful when the array must stay compact yet reject diffuse noise.','A technician uses an MVDR or differential design with the isotropic-noise coherence matrix; the directivity factor is DF = |w^H d|^2 / (w^H Gamma w), and pushing it up demands tightly matched, low-noise capsules.','Array performance',ARRAY['Tapering function','Steering vector','Spatial covariance matrix','Spherical microphone array','Subband beamforming']::text[],ARRAY['Assuming higher directivity is free; it raises white-noise gain and self-noise.','Ignoring the need for closely matched, low-noise sensors.','Confusing superdirectivity with simply adding more microphones.']::text[],ARRAY['Designing a compact endfire, shotgun-style array.','Differential microphone arrays in phones.','Trading directivity against noise robustness.']::text[],'advanced','DF = |w^H d|^2 / (w^H Gamma w)','The directivity factor equals the squared magnitude of the weighted array response in the look direction, divided by the weighted diffuse-noise response.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Superdirectivity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7f647705-c8cf-4001-b4fd-e3d756bd314d','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7f647705-c8cf-4001-b4fd-e3d756bd314d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7f647705-c8cf-4001-b4fd-e3d756bd314d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '87a47afa-caef-484e-8071-122587a82977','Surface micromachining','Surface micromachining is a MEMS fabrication method that builds a microphone''s moving diaphragm and fixed backplate by depositing and patterning thin structural layers on a silicon wafer, then etching away a sacrificial layer to release the diaphragm. It produces the tiny suspended membranes used in MEMS microphones.','MEMS mics are made on silicon chips. Surface micromachining stacks thin layers on the wafer. A sacrificial layer is etched away last. That frees a tiny diaphragm so it can move.','It creates the free-moving diaphragm and perforated backplate of a MEMS capsule using standard semiconductor steps, enabling mass production at chip scale.','A technician meets the result as a MEMS microphone die a few millimeters across; the release step explains why the diaphragm is delicate and why a back cavity and vent are built into the package.','MEMS fabrication',ARRAY['Wafer-level packaging','Wake-on-sound','Vent resistance','Venting time constant','Waterproof acoustic vent']::text[],ARRAY['Confusing surface micromachining (thin films on top) with bulk micromachining (etching through the wafer).','Assuming MEMS diaphragms are rugged; the released membrane is fragile.','Thinking the whole device is the diaphragm rather than a small suspended layer.']::text[],ARRAY['Explaining how a smartphone MEMS mic is built.','Comparing MEMS and electret capsule construction.','Understanding MEMS diaphragm fragility in handling.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Surface micromachining');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '87a47afa-caef-484e-8071-122587a82977','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='87a47afa-caef-484e-8071-122587a82977') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='87a47afa-caef-484e-8071-122587a82977');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e72297c2-7550-4837-8159-dfc0629bfb83','Tapering function','A tapering function (shading or window) is the set of amplitude weights applied across the elements of a microphone array to shape its beam pattern, chiefly to lower side-lobe levels at the cost of a wider main lobe. It is the spatial analog of a time-domain window.','Array capsules can be weighted, not just summed equally. A tapering function sets those weights. Tapering the edges lowers the side beams. The main beam then gets a little wider.','It controls the trade-off between main-lobe width and side-lobe level, reducing pickup from unwanted directions.','A technician applies a window (for example a Chebyshev or Hann taper): uniform weights give the narrowest beam but about -13 dB side lobes, while a taper can push side lobes below -30 dB with a slightly broader main lobe.','Array signal processing',ARRAY['Steering vector','Superdirectivity','Spherical microphone array','Subband beamforming','Time-domain beamforming']::text[],ARRAY['Expecting a narrower beam and lower side lobes at once; they trade off.','Confusing spatial tapering with time-domain windowing of the signal.','Forgetting heavy tapering lowers array gain against white noise.']::text[],ARRAY['Reducing side-lobe pickup in a line array of mics.','Shaping a beamformer for a noisy room.','Teaching the window and aperture analogy.']::text[],'intermediate','y = sum_{m=1..M} w_m x_m','The tapered array output is the sum over all microphones of each channel weighted by its taper coefficient.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Tapering function');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e72297c2-7550-4837-8159-dfc0629bfb83','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e72297c2-7550-4837-8159-dfc0629bfb83') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e72297c2-7550-4837-8159-dfc0629bfb83');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd475ca2c-8dcf-477a-a326-aeda635c5324','Temperature coefficient','The temperature coefficient of a measurement microphone is the change in its sensitivity level per degree of temperature change, in dB per degree Celsius. It captures how the capsule''s mechanical and electrical properties drift with temperature away from reference conditions.','A mic''s sensitivity shifts a little as it warms or cools. The temperature coefficient measures that drift per degree. It is given in decibels per degree Celsius. Labs correct their readings with it.','It allows correction of calibrated sensitivity for the actual temperature and sets a tolerance a standard microphone must meet.','With a coefficient near -0.01 dB/C, a 10 C rise changes sensitivity by about -0.1 dB; IEC 61094-4 requires a working standard microphone to stay within roughly +/-0.03 dB/C.','Environmental coefficient',ARRAY['Static-pressure coefficient','Static capacitance','Working standard microphone','Transfer standard microphone','Substitution calibration']::text[],ARRAY['Assuming sensitivity is temperature-independent.','Ignoring that the coefficient varies with frequency.','Confusing the mic''s temperature coefficient with the preamp''s drift.']::text[],ARRAY['Correcting outdoor measurements for temperature.','Meeting IEC 61094 tolerances.','Choosing a stable mic for a climate-chamber test.']::text[],'intermediate','K_T = dL_M / dT','The temperature coefficient equals the change in sensitivity level divided by the change in temperature.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Temperature coefficient');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd475ca2c-8dcf-477a-a326-aeda635c5324','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d475ca2c-8dcf-477a-a326-aeda635c5324') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d475ca2c-8dcf-477a-a326-aeda635c5324');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'df498d28-28e7-4ca4-ba92-9ba0926dffb3','Thermal noise','Thermal (Johnson-Nyquist) noise is the random voltage generated across any resistance by the thermal agitation of charge carriers, with mean-square voltage 4kTRdf that is independent of frequency (white). In a microphone it sets a noise floor from the capsule''s resistive elements and the preamp input resistance.','Warm resistors make a faint hiss on their own. This is thermal noise, from jiggling electrons. It grows with temperature, resistance, and bandwidth. It sets part of a mic''s noise floor.','It defines a fundamental, unavoidable noise floor that limits how quiet a microphone or preamp can be.','For R = 1 kilohm at T = 293 K over df = 20 kHz, V_n = sqrt(4 * 1.38e-23 * 293 * 1000 * 20000) is about 0.57 microvolts RMS; lowering R or bandwidth lowers this floor.','Noise',ARRAY['Voltage-noise density','Z-weighted self-noise','Static capacitance','Temperature coefficient']::text[],ARRAY['Thinking thermal noise depends on the resistor''s material or current; it depends on R, T, and bandwidth.','Confusing thermal noise with shot noise or 1/f noise.','Forgetting it is white, so wider bandwidth means more noise.']::text[],ARRAY['Estimating a preamp''s noise floor.','Explaining self-noise of a high-impedance capsule.','Choosing bias-resistor values for low noise.']::text[],'intermediate','V_n = sqrt( 4 k T R df )','The RMS thermal-noise voltage equals the square root of four times Boltzmann''s constant, temperature, resistance, and bandwidth.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Thermal noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'df498d28-28e7-4ca4-ba92-9ba0926dffb3','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='df498d28-28e7-4ca4-ba92-9ba0926dffb3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='df498d28-28e7-4ca4-ba92-9ba0926dffb3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '73682846-cb2b-4592-9714-79371ce76f9d','Time difference of arrival','Time difference of arrival (TDOA) is the difference in the times a single sound reaches two spatially separated microphones. Because it maps to a direction (or a hyperbola of possible source locations), it is a primary cue for microphone-array localization.','Sound reaches two mics at slightly different moments. That gap is the time difference of arrival. It tells you the direction to the source. Arrays use several such gaps to locate sound.','It converts geometry into a measurable time cue, letting an array estimate source direction or position.','For mics spaced d = 0.17 m with a source at angle theta, tau = d cos(theta)/c; broadside (theta = 90 deg) gives 0, and endfire gives 0.17/343 = about 0.5 ms, which GCC-PHAT cross-correlation estimates.','Localization',ARRAY['Steering vector','Time-domain beamforming','Spherical microphone array','Spatial covariance matrix']::text[],ARRAY['Confusing TDOA with the absolute travel time from source to array.','Ignoring that beyond the endfire limit no larger delay is physical.','Forgetting reverberation biases the correlation peak.']::text[],ARRAY['Locating a talker for camera steering.','Auto-mixing that follows the active mic.','Sound-source localization in robotics.']::text[],'intermediate','tau = d cos(theta) / c','The time difference of arrival equals the microphone spacing times the cosine of the arrival angle, divided by the speed of sound.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Time difference of arrival');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '73682846-cb2b-4592-9714-79371ce76f9d','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='73682846-cb2b-4592-9714-79371ce76f9d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='73682846-cb2b-4592-9714-79371ce76f9d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7ee495fb-a687-4706-abf4-6d76c2854573','Time-domain beamforming','Time-domain beamforming (delay-and-sum in the time domain) aligns each microphone signal by an appropriate time delay for a chosen look direction and adds them, reinforcing sound from that direction while partly cancelling other directions. It operates directly on the sampled waveforms rather than in frequency bins.','Point a mic array by delaying each channel the right amount. Then add the channels together. Sound from the aimed direction lines up and grows. Other sounds partly cancel out.','It steers and focuses an array on a direction using simple sample delays and summation, without transforming to the frequency domain.','A technician sets per-channel delays so the target wavefront aligns, then sums: y(t) = sum w_m x_m(t - tau_m); fractional-sample delays need interpolation for accuracy.','Array signal processing',ARRAY['Steering vector','Tapering function','Time difference of arrival','Subband beamforming','Superdirectivity']::text[],ARRAY['Using integer-sample delays only, causing steering errors at high frequency.','Assuming perfect cancellation off-axis; it is only partial.','Confusing time-domain delay-and-sum with frequency-domain (subband) beamforming.']::text[],ARRAY['A simple fixed beam for a lecture-hall array.','Broadband steering where phase must stay linear.','Teaching the basic array concept before adaptive methods.']::text[],'intermediate','y(t) = sum_{m=1..M} w_m x_m(t - tau_m)','The beam output is the sum over microphones of each delayed channel times its weight.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Time-domain beamforming');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7ee495fb-a687-4706-abf4-6d76c2854573','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7ee495fb-a687-4706-abf4-6d76c2854573') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7ee495fb-a687-4706-abf4-6d76c2854573');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f260cf12-edb8-42c2-96d4-411b5e1d8a6e','Tonader powering','Tonader powering (German Tonaderspeisung; also T-powering, A-B powering, or T12) is an older microphone-powering scheme that feeds about 12 V DC to a condenser microphone through a resistor in series with each of the two balanced audio conductors, so the supply current flows differentially along the signal pair. It differs from phantom power, which applies the DC equally to both conductors relative to the shield.','This is an old way to power some condenser mics. It sends about 12 volts along the two audio wires. The voltage sits across the pair, not to the shield. That is different from 48-volt phantom power.','It supplied operating voltage to early transistorized condenser microphones (notably some Sennheiser and Neumann models) over the same cable that carries audio.','A technician meets it on vintage MKH-series mics; the supply uses two roughly 180-ohm feed resistors at about 12 V, and a T-power source must be matched to a T-power microphone.','Microphone powering',ARRAY['Static capacitance','Working standard microphone','Voltage-noise density','Thermal noise']::text[],ARRAY['UNSAFE: Plugging a phantom-only, dynamic, or ribbon microphone into a T-power feed puts DC across the signal pair and can damage the microphone or its ribbon; confirm the powering type first.','Confusing T-powering (voltage across the two conductors) with phantom power (voltage on both conductors versus the shield).','Assuming any 12 V source works; the feed-resistor values and topology matter.']::text[],ARRAY['Powering a vintage Sennheiser MKH microphone.','Setting a mixer or adapter to T-power versus phantom.','Servicing legacy broadcast microphones.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Tonader powering');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f260cf12-edb8-42c2-96d4-411b5e1d8a6e','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f260cf12-edb8-42c2-96d4-411b5e1d8a6e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f260cf12-edb8-42c2-96d4-411b5e1d8a6e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '44cd7ef8-d2e2-4f05-999c-4955c2b6f323','Transfer standard microphone','A transfer standard microphone is a highly stable measurement microphone used to carry a calibration from a primary (laboratory) standard down to working standards or field instruments, usually by the comparison method. It is trusted for its long-term stability rather than being calibrated by primary reciprocity itself.','Labs pass calibration down a chain. A transfer standard mic carries the value between levels. It is very stable over time. It links the top primary mic to everyday working mics.','It maintains traceability by transferring a known sensitivity from primary standards down to working and field microphones.','A calibration lab compares a customer microphone against the transfer standard in the same sound field, transferring the sensitivity value while preserving traceability to national standards.','Measurement standard',ARRAY['Working standard microphone','Substitution calibration','Static-pressure coefficient','Temperature coefficient','Static capacitance']::text[],ARRAY['Confusing a transfer standard with the primary laboratory standard.','Assuming it needs no periodic recalibration.','Using an unstable field mic as if it were a transfer standard.']::text[],ARRAY['Maintaining calibration traceability in an accredited lab.','Comparison calibration of field microphones.','Auditing a metrology chain.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Transfer standard microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '44cd7ef8-d2e2-4f05-999c-4955c2b6f323','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='44cd7ef8-d2e2-4f05-999c-4955c2b6f323') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='44cd7ef8-d2e2-4f05-999c-4955c2b6f323');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '57c96924-2770-4cb8-b573-7ed5a3c795d2','Vent resistance','Vent resistance is the acoustic resistance of the small vent or leak connecting a microphone''s back cavity to ambient pressure, equalizing static pressure while limiting airflow at audio frequencies. Together with the back-cavity compliance it sets the microphone''s low-frequency cutoff.','Every pressure mic needs a tiny leak to the outside air. That leak has acoustic resistance, called vent resistance. It lets slow pressure changes pass. It blocks low audio tones from leaking away.','It equalizes slow barometric changes across the diaphragm while keeping low audio frequencies from being lost through the leak.','With the back-cavity compliance C_a, the vent resistance R_a sets a high-pass corner near f = 1/(2 pi R_a C_a); designers tune the vent to place that corner below the audio band.','Capsule acoustics',ARRAY['Venting time constant','Waterproof acoustic vent','Static-pressure coefficient','Surface micromachining','Static capacitance']::text[],ARRAY['Thinking the vent is a manufacturing flaw rather than a needed pressure equalizer.','Blocking the vent and shifting or losing the low-frequency response.','Confusing vent resistance (acoustic) with electrical resistance.']::text[],ARRAY['Explaining a mic''s low-frequency roll-off.','Diagnosing a plugged vent after moisture ingress.','Designing a MEMS back cavity and vent.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Vent resistance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '57c96924-2770-4cb8-b573-7ed5a3c795d2','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='57c96924-2770-4cb8-b573-7ed5a3c795d2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='57c96924-2770-4cb8-b573-7ed5a3c795d2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7e4b1a46-a9aa-4d37-99d8-8fdca0a1607a','Venting time constant','The venting (pressure-equalization) time constant is the characteristic time R_a*C_a over which a microphone''s back cavity equalizes to ambient static pressure through its vent. Its reciprocal, divided by 2 pi, sets the low-frequency corner below which the microphone stops responding to pressure.','The back cavity slowly leaks toward outside pressure. The venting time constant is how fast that happens. A long time constant means a lower bass limit. It comes from vent resistance and cavity size.','It defines how quickly static pressure equalizes and therefore where the microphone''s low-frequency response rolls off.','A time constant tau = R_a C_a of 0.16 s gives a low-frequency corner f = 1/(2 pi tau) of about 1 Hz; shrinking the vent lengthens tau and lowers the corner.','Capsule acoustics',ARRAY['Vent resistance','Waterproof acoustic vent','Static-pressure coefficient','Surface micromachining']::text[],ARRAY['Confusing the venting time constant with the electrical RC of the preamp.','Assuming it sets the high-frequency limit; it sets the low-frequency limit.','Ignoring temperature and humidity effects on the vent.']::text[],ARRAY['Predicting a MEMS mic''s low-frequency corner.','Explaining slow recovery after a pressure pop.','Tuning infrasound measurement microphones.']::text[],'advanced','tau = R_a C_a,  f_c = 1/(2 pi tau)','The venting time constant equals acoustic resistance times acoustic compliance; the low-frequency corner is one over two pi times that time constant.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Venting time constant');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7e4b1a46-a9aa-4d37-99d8-8fdca0a1607a','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7e4b1a46-a9aa-4d37-99d8-8fdca0a1607a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7e4b1a46-a9aa-4d37-99d8-8fdca0a1607a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'daa7229a-9b99-43f7-bfa8-de49165b6d10','Voltage-noise density','Voltage-noise density is the amount of noise voltage per unit bandwidth at a circuit node, expressed in volts per root hertz. For a resistance it equals sqrt(4kTR); it lets designers predict total noise by integrating over the bandwidth of interest.','Noise is often quoted per slice of bandwidth. Voltage-noise density gives volts for each root hertz. It lets you scale noise to any bandwidth. A resistor''s value is the square root of 4kTR.','It expresses noise in a bandwidth-independent way so total noise can be computed for any bandwidth and compared between parts.','For R = 1 kilohm at 293 K, e_n = sqrt(4 * 1.38e-23 * 293 * 1000) is about 4.0 nV/rtHz; over a 20 kHz band the total is 4.0 nV/rtHz times sqrt(20000), about 0.57 microvolts RMS.','Noise',ARRAY['Thermal noise','Z-weighted self-noise','Static capacitance','Temperature coefficient']::text[],ARRAY['Forgetting to multiply by the square root of bandwidth to get total noise voltage.','Confusing V/rtHz with V/Hz.','Adding noise sources linearly instead of in quadrature (root-sum-square).']::text[],ARRAY['Comparing preamp op-amp noise specs.','Estimating a mic front-end noise floor.','Designing low-noise bias networks.']::text[],'intermediate','e_n = sqrt( 4 k T R )   [V/rtHz]','The thermal voltage-noise density equals the square root of four times Boltzmann''s constant, temperature, and resistance.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Voltage-noise density');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'daa7229a-9b99-43f7-bfa8-de49165b6d10','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='daa7229a-9b99-43f7-bfa8-de49165b6d10') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='daa7229a-9b99-43f7-bfa8-de49165b6d10');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6ab59561-2fd6-4795-a313-b0cf40b855c6','Volumetric microphone array','A volumetric (3-D) microphone array distributes microphones through a three-dimensional volume rather than on a line or single plane, giving resolution and steering capability in all three spatial dimensions. Spherical and randomly filled cube arrays are common examples.','Most simple arrays lie on a line or flat plane. A volumetric array spreads mics through a 3-D space. This gives it aim in every direction. It can tell up from down as well as left from right.','It provides full 3-D directional resolution, removing the front-back or up-down ambiguities of line and planar arrays.','A technician uses a volumetric layout (for example a rigid sphere or a 3-D cluster) when sources may come from any elevation; the extra dimension improves localization but needs more capsules and calibration.','Array geometry',ARRAY['Spherical microphone array','Steering vector','Superdirectivity','Tapering function','Spatial covariance matrix']::text[],ARRAY['Assuming a planar array resolves elevation; it generally cannot without ambiguity.','Ignoring the higher channel count and calibration burden.','Confusing volumetric coverage with simply more microphones on a line.']::text[],ARRAY['3-D source localization in a room.','Immersive sound-field capture.','Acoustic imaging where sources vary in height.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Volumetric microphone array');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6ab59561-2fd6-4795-a313-b0cf40b855c6','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6ab59561-2fd6-4795-a313-b0cf40b855c6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6ab59561-2fd6-4795-a313-b0cf40b855c6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '48fad9ce-353d-4203-adbe-e25ae68cc78a','Wafer-level packaging','Wafer-level packaging (WLP) is a MEMS and semiconductor packaging approach in which the protective package and interconnects are formed while the devices are still on the wafer, before dicing into individual chips. For MEMS microphones it helps seal the delicate diaphragm and define the acoustic cavity at chip scale.','Chips are usually packaged one at a time after cutting. Wafer-level packaging seals them while still on the wafer. This protects the fragile diaphragm early. It also makes the parts smaller and cheaper.','It protects the released MEMS structure and helps set the acoustic cavity while enabling very small, low-cost, high-volume microphone packages.','A technician meets WLP as the reason a MEMS mic is a tiny surface-mount part with a defined port and cavity; the packaging, not just the die, shapes its acoustic response.','MEMS packaging',ARRAY['Surface micromachining','Wake-on-sound','Waterproof acoustic vent','Vent resistance','Venting time constant']::text[],ARRAY['Thinking the package is only mechanical protection; it also shapes the acoustics.','Confusing wafer-level packaging with normal after-dicing packaging.','Ignoring the sound port and cavity that the package defines.']::text[],ARRAY['Explaining MEMS mic miniaturization.','Understanding why port position affects response.','Comparing top-port and bottom-port MEMS mics.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Wafer-level packaging');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '48fad9ce-353d-4203-adbe-e25ae68cc78a','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='48fad9ce-353d-4203-adbe-e25ae68cc78a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='48fad9ce-353d-4203-adbe-e25ae68cc78a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2d68a47d-31d9-41b3-909d-b32ba2c9c858','Wake-on-sound','Wake-on-sound (acoustic activity detection) is a low-power mode in which a MEMS microphone and its companion chip monitor for sound above a set threshold while the main processor sleeps, issuing an interrupt to wake the system when sound is detected. It saves battery in always-listening devices.','An always-listening device cannot keep everything powered. Wake-on-sound lets the mic watch for noise using very little power. When sound passes a threshold, it wakes the main chip. This saves battery.','It lets battery devices stay responsive to sound while keeping the power-hungry processor asleep until needed.','A technician configures a digital MEMS mic''s activity-detect threshold and interrupt so a wearable stays in microwatt standby, then wakes for voice; only the small always-on block draws current.','MEMS feature',ARRAY['Surface micromachining','Wafer-level packaging','Waterproof acoustic vent','Voltage-noise density']::text[],ARRAY['Confusing wake-on-sound (any sound over a threshold) with full voice recognition.','Setting the threshold too low, causing constant false wakes.','Assuming it needs the main codec powered; the point is ultra-low-power standby.']::text[],ARRAY['Battery-powered voice assistants and wearables.','Always-listening keyword front ends.','Power budgeting an IoT audio device.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Wake-on-sound');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2d68a47d-31d9-41b3-909d-b32ba2c9c858','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2d68a47d-31d9-41b3-909d-b32ba2c9c858') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2d68a47d-31d9-41b3-909d-b32ba2c9c858');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd06b0fef-d88d-4d39-8924-d1d9288e00cb','Waterproof acoustic vent','A waterproof acoustic vent is a membrane (often expanded PTFE) placed over a microphone or speaker port that blocks liquid water and dust while remaining acoustically transparent enough to pass sound and equalize pressure. It lets a sealed device earn an IP rating without deafening the microphone.','Sealed phones and wearables still need sound to get in. A waterproof vent covers the port with a special membrane. It stops water and dust. But it still lets sound and pressure through.','It protects a microphone port against water and dust ingress while passing sound, enabling waterproof (IP-rated) devices.','A technician sees these as small PTFE vent patches over mic ports; they add a small, frequency-dependent insertion loss the acoustic design must budget for.','Protective component',ARRAY['Vent resistance','Venting time constant','Wafer-level packaging','Surface micromachining']::text[],ARRAY['Assuming the vent is acoustically invisible; it adds some insertion loss.','Damaging or contaminating the membrane, which raises loss or lets water in.','Confusing the waterproof vent with the internal pressure-equalization vent of the capsule.']::text[],ARRAY['Waterproofing a smartphone or smartwatch microphone.','Meeting an IP67 rating.','Diagnosing muffled audio from a clogged vent membrane.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Waterproof acoustic vent');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd06b0fef-d88d-4d39-8924-d1d9288e00cb','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d06b0fef-d88d-4d39-8924-d1d9288e00cb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d06b0fef-d88d-4d39-8924-d1d9288e00cb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '244d1820-33fd-45b9-a33b-21aac808b366','Working standard microphone','A working standard microphone is a robust, stable measurement microphone used for everyday laboratory and field measurements, calibrated by comparison against higher-tier (laboratory or transfer) standards rather than by primary methods. IEC 61094-4 specifies its construction and tolerances.','Labs do not use their best primary mic for daily work. They use a working standard microphone instead. It is rugged and stable enough for routine tests. It is calibrated against the higher standards.','It provides a dependable, everyday measurement microphone whose calibration is traceable to primary standards through comparison.','A technician uses a working standard (for example an IEC 61094-4 half-inch mic) for sound-level and frequency-response tests, recalibrating it periodically against a transfer or laboratory standard.','Measurement standard',ARRAY['Transfer standard microphone','Substitution calibration','Static-pressure coefficient','Temperature coefficient','Static capacitance']::text[],ARRAY['Confusing a working standard with a primary laboratory standard.','Skipping periodic recalibration against a higher standard.','Assuming any studio mic can serve as a working standard.']::text[],ARRAY['Routine sound-level meter checks.','Field acoustic measurements.','Production-line audio testing.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Working standard microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '244d1820-33fd-45b9-a33b-21aac808b366','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='244d1820-33fd-45b9-a33b-21aac808b366') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='244d1820-33fd-45b9-a33b-21aac808b366');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '29dea88c-c93e-4dd0-8c21-742579fc3ecc','Z-weighted self-noise','Z-weighted self-noise is a microphone''s inherent (equivalent input) noise level measured with the ''Z'' (zero) frequency weighting defined in IEC 61672-1, which is essentially flat from 10 Hz to 20 kHz. Because Z weighting applies no roll-off, it usually yields a higher number than the A-weighted self-noise of the same microphone.','Every mic makes some noise on its own. Z-weighting measures it with a flat filter. It does not cut lows or highs like A-weighting does. So the Z number is usually larger than the A number.','It reports a microphone''s self-noise without perceptual shaping, giving a bandwidth-honest figure useful for engineering comparison.','A technician comparing specs knows a mic quoted at, say, 7 dB(A) self-noise reads several dB higher when Z-weighted, because low- and high-frequency noise are no longer attenuated.','Noise specification',ARRAY['Thermal noise','Voltage-noise density','Static capacitance','Temperature coefficient']::text[],ARRAY['Comparing a Z-weighted figure directly with an A-weighted one; they are not equal.','Assuming Z means ''no measurement bandwidth''; it is flat over a defined band.','Confusing Z (zero/flat) weighting with C weighting.']::text[],ARRAY['Reading a measurement-mic self-noise spec.','Comparing mics across A- and Z-weighted numbers.','Assessing low-frequency noise that A-weighting would hide.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Z-weighted self-noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '29dea88c-c93e-4dd0-8c21-742579fc3ecc','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='29dea88c-c93e-4dd0-8c21-742579fc3ecc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='29dea88c-c93e-4dd0-8c21-742579fc3ecc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7749bd58-9583-482b-8fae-a4ded53abb0e','3:1 placement guideline','A multi-microphone rule of thumb stating that the spacing between two microphones should be at least three times the distance from each microphone to its own sound source. Meeting this ratio makes the second source arrive at least about 9.5 dB lower in the first microphone, which keeps audible comb filtering from leakage acceptably low when the two signals are mixed.','This is a spacing rule for using two microphones at once. Keep the gap between mics at least three times the mic-to-singer distance. That makes bleed from the other source much quieter. It stops the hollow, filtered sound of two mics fighting.','It exists to reduce comb-filter coloration caused when the same sound reaches two mixed microphones at slightly different times.','Miking two singers 0.3 m from each mic, keep the mics at least 0.9 m apart; 20*log10(0.9/0.3) = 9.5 dB of leakage rejection.','Placement technique',ARRAY['Acoustic leakage','Bidirectional response','Cardioid family','Boundary microphones']::text[],ARRAY['Confusing the 3:1 ratio with the mic-to-source distance instead of the mic-to-mic spacing.','Applying it to coincident stereo pairs, where the mics are meant to be together.','Believing it removes leakage entirely rather than just lowering its level.']::text[],ARRAY['Placing two vocal mics on a duet without hollow comb-filter coloration.','Spacing lectern and panel mics in a conference room.','Setting tom mics on a drum kit to limit bleed between them.']::text[],'intermediate','dL = 20 * log10(d2 / d1)','The leakage level difference in decibels equals twenty times the base-ten logarithm of the mic-to-mic distance divided by the mic-to-source distance.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='3:1 placement guideline');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7749bd58-9583-482b-8fae-a4ded53abb0e','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7749bd58-9583-482b-8fae-a4ded53abb0e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7749bd58-9583-482b-8fae-a4ded53abb0e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b55e9092-c8c4-4e9d-be03-b14d35ee413f','Acceptance angle','The angular width, measured about a microphone''s main axis, over which sound is captured within a stated on-axis sensitivity tolerance. For a coincident or near-coincident stereo array it is the frontal source angle (the stereo recording angle) that is mapped across the full width of the reproduced stereo image.','This is how wide a microphone''s useful pickup zone is. Sources inside the angle are captured at nearly full level. For a stereo pair it is the arc that fills the space between the speakers. Sources outside it get pushed to one side or fade.','It tells the engineer how much of a scene a mic or stereo array will capture cleanly and where the image edges fall.','An ORTF pair with about a 95 degree acceptance angle maps a stage that wide across the full left-to-right stereo image.','Polar response',ARRAY['Angular response','Azimuth response','Cardioid family','Bidirectional response']::text[],ARRAY['Treating acceptance angle as a fixed number rather than tied to a tolerance and pattern.','Ignoring that it narrows at high frequencies as the pattern tightens.','Confusing a single mic''s coverage angle with a stereo array''s recording angle.']::text[],ARRAY['Choosing a stereo array to match the width of an orchestra.','Aiming a cardioid so key sources sit inside its even-response zone.','Predicting how far off-axis a source can move before it dulls.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acceptance angle');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b55e9092-c8c4-4e9d-be03-b14d35ee413f','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b55e9092-c8c4-4e9d-be03-b14d35ee413f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b55e9092-c8c4-4e9d-be03-b14d35ee413f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '60c9eea6-a948-46bb-a2f7-71d6c1ef6194','Acoustic labyrinth','A folded internal acoustic path, often packed with damping material, placed behind a microphone diaphragm to act as a controlled acoustic resistance and time delay for rear-arriving sound. It absorbs and delays the rear signal so unwanted resonances are damped and the desired directional pattern and low-frequency response are shaped.','This is a maze-like air path built behind a microphone diaphragm. Sound entering the back is slowed and soaked up inside it. That damps ringing and helps set the pickup pattern. Designers use it to control how the mic hears sound from behind.','It provides a tuned rear acoustic termination that damps capsule resonances and helps form a smooth directional response.','A technician recognizes that an Electro-Voice Variable-D mic uses an internal acoustic labyrinth to reduce proximity effect close to a talker.','Construction',ARRAY['Acoustic vent','Cavity resonance','Capsule resonance','Cardioid formation']::text[],ARRAY['Confusing a microphone labyrinth with a loudspeaker transmission-line enclosure.','Blocking rear ports and labyrinth openings, which changes the polar pattern.','Assuming the labyrinth only affects looks rather than acoustic behavior.']::text[],ARRAY['Explaining why a directional mic has damped rear openings.','Diagnosing pattern change after a rear vent is taped over.','Comparing proximity effect between vented and sealed-back designs.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic labyrinth');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '60c9eea6-a948-46bb-a2f7-71d6c1ef6194','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='60c9eea6-a948-46bb-a2f7-71d6c1ef6194') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='60c9eea6-a948-46bb-a2f7-71d6c1ef6194');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '55076858-bd65-43b7-b43f-2774cdead996','Acoustic labyrinths','The general class of folded, damped acoustic paths used as tuned resistance-and-delay networks in transducer design. In microphones they terminate rear sound to shape directivity and damp resonances, and the same principle appears in loudspeaker transmission-line enclosures.','This is the whole family of maze-like damped air paths used in audio gear. Each one slows and absorbs sound in a controlled way. Microphones use them to tame the back signal. Speakers use bigger versions to handle bass behind the cone.','It names the broad design approach of using folded, damped air paths to control resonance and directionality in transducers.','A technician groups a microphone''s rear delay path and a speaker''s transmission line together as acoustic labyrinths that trade length for damping and delay.','Construction',ARRAY['Acoustic labyrinth','Acoustic vent','Cavity resonance','Cardioid formation']::text[],ARRAY['Assuming all acoustic labyrinths are identical rather than tuned per application.','Overlooking that damping material is essential to their function.','Treating them as purely low-frequency devices in microphones.']::text[],ARRAY['Comparing labyrinth designs across microphone and loudspeaker products.','Teaching the shared principle behind rear-path damping.','Selecting a mic whose rear network suits close talking.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic labyrinths');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '55076858-bd65-43b7-b43f-2774cdead996','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='55076858-bd65-43b7-b43f-2774cdead996') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='55076858-bd65-43b7-b43f-2774cdead996');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '17773235-9827-4275-9a3c-df1fe1f5999f','Acoustic leakage','Sound from sources other than the intended one that enters a microphone, also called bleed or spill. It reduces isolation between channels and, when leaked and direct signals are mixed, can cause comb filtering and a loss of control over the mix.','This is unwanted sound sneaking into the wrong microphone. A drum mic, for example, also hears the singer nearby. Too much of it makes mixing harder. It can also add a hollow, filtered tone.','Understanding leakage lets an engineer keep each source controllable and avoid coloration when many mics are open at once.','A technician tightens a snare mic''s cardioid null toward the hi-hat and follows the 3:1 guideline to cut audible leakage.','Placement technique',ARRAY['3:1 placement guideline','Cardioid family','Bidirectional response','Acceptance angle']::text[],ARRAY['Thinking a directional mic blocks leakage completely instead of just reducing it.','Ignoring that many open mics raise the leakage and comb-filtering risk.','Boosting a leaky channel and worsening the coloration in the mix.']::text[],ARRAY['Miking a drum kit so cymbals do not dominate the tom mics.','Recording a live band in one room with limited isolation.','Placing lavalier mics on nearby actors on a set.']::text[],'beginner',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic leakage');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '17773235-9827-4275-9a3c-df1fe1f5999f','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='17773235-9827-4275-9a3c-df1fe1f5999f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='17773235-9827-4275-9a3c-df1fe1f5999f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '893f1ccf-317d-497c-be3d-931033b11f56','Acoustic overload point','The sound pressure level at which a microphone''s output reaches a defined total harmonic distortion threshold, most commonly 10 percent THD, marking the practical maximum SPL it can handle. Typical MEMS values are around 126 dB SPL for analogue devices and about 120 dB SPL for digital ones, where the digital limit is set by the coded output range.','This is the loudest sound a microphone can take before it distorts badly. It is set where distortion reaches ten percent. Above this level the sound gets crunchy and unusable. Small MEMS mics reach it near 120 to 126 decibels.','It defines the top of a microphone''s clean operating range so an engineer can match the mic to loud sources.','For a kick drum peaking near 130 dB SPL, a technician picks a capsule with an acoustic overload point above that, or engages a pad.','Specification',ARRAY['Acoustic-overload recovery','Bias voltage','Bottom-port microphone','Capacitive sensing']::text[],ARRAY['Confusing acoustic overload point with self-noise at the quiet end of the range.','Ignoring that the number assumes a specific THD percentage, usually 10 percent.','Assuming a large diaphragm always means a higher overload point.']::text[],ARRAY['Selecting a mic for close-miking a loud guitar amplifier.','Reading a datasheet to compare maximum SPL between capsules.','Deciding whether to switch in a pad on a snare mic.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic overload point');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '893f1ccf-317d-497c-be3d-931033b11f56','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='893f1ccf-317d-497c-be3d-931033b11f56') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='893f1ccf-317d-497c-be3d-931033b11f56');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ec86ef2a-4e45-427c-bcb9-230415ebf8f9','Acoustic port','An opening in a microphone housing that admits sound to reach the diaphragm or the rear of the capsule. Its position, size, and any acoustic resistance behind it help determine sensitivity, directionality, and frequency response; MEMS microphones are classed as top-port or bottom-port by where this inlet sits.','This is the hole that lets sound into a microphone. Its size and place change how the mic hears. A back port helps make the mic directional. On tiny MEMS mics it can face up or down.','It provides the controlled sound inlet that sets how and from which directions a microphone picks up energy.','A technician routes a PCB sound channel to a bottom-port MEMS mic so its acoustic port lines up with the case opening.','Construction',ARRAY['Acoustic vent','Bottom-port microphone','Acoustic labyrinth','Cardioid formation']::text[],ARRAY['Blocking or sealing an acoustic port and killing sensitivity or pattern.','Confusing the front sound port with a rear directional port.','Assuming port size does not affect frequency response.']::text[],ARRAY['Designing a phone housing so the port aligns with the MEMS inlet.','Explaining why a directional mic has both front and rear ports.','Diagnosing muffled sound from a clogged microphone port.']::text[],'beginner',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic port');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ec86ef2a-4e45-427c-bcb9-230415ebf8f9','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ec86ef2a-4e45-427c-bcb9-230415ebf8f9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ec86ef2a-4e45-427c-bcb9-230415ebf8f9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a1828e9c-d879-4422-b311-4d1fbd2444c1','Acoustic transducer','A device that converts energy between acoustic and another domain, most often electrical. A microphone is an acoustic-to-electrical transducer, while a loudspeaker converts in the reverse direction; the term covers the general energy-conversion role rather than any single technology.','This is any device that turns sound into another form of energy, or back. A microphone turns sound into an electrical signal. A speaker does the opposite. Both are acoustic transducers.','The concept groups microphones, loudspeakers, and similar devices by the energy conversion they perform.','A technician labels a measurement microphone as the acoustic transducer that feeds sound-pressure data into an analyzer.','Fundamentals',ARRAY['Capacitive sensing','Ceramic microphone','Bias voltage','Acoustic port']::text[],ARRAY['Assuming transducer means only microphones and not loudspeakers.','Thinking the term names a specific technology rather than a role.','Overlooking that the conversion can run in either direction.']::text[],ARRAY['Introducing microphones and speakers as complementary transducers.','Classifying a device in a signal chain by its conversion role.','Discussing efficiency of energy conversion in a capsule.']::text[],'beginner',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic transducer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a1828e9c-d879-4422-b311-4d1fbd2444c1','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a1828e9c-d879-4422-b311-4d1fbd2444c1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a1828e9c-d879-4422-b311-4d1fbd2444c1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '93615873-9675-4886-bd14-1c74250d0250','Acoustic vent','A small, usually resistance-controlled opening in a microphone capsule that admits rear sound or equalizes slow static pressure changes across the diaphragm. Directional capsules use it to create the pressure-gradient action that forms the polar pattern, and it also prevents barometric pressure from bowing the diaphragm.','This is a tiny controlled leak in a microphone capsule. It lets some sound reach the back of the diaphragm. That is how directional mics sense direction. It also stops weather pressure changes from pushing the diaphragm out of place.','It provides the rear acoustic access and slow pressure relief needed for directional response and stable operation.','A technician avoids covering a capsule''s rear vent, knowing it would turn a directional mic toward omnidirectional behavior.','Construction',ARRAY['Acoustic port','Cardioid formation','Bidirectional response','Acoustic labyrinth']::text[],ARRAY['Sealing the rear vent and unintentionally changing the polar pattern.','Confusing the pressure-equalization vent with the main sound inlet.','Assuming vents only relieve pressure and do not shape directivity.']::text[],ARRAY['Explaining why a cardioid capsule has a controlled rear opening.','Troubleshooting pattern shift after a repair blocks a vent.','Describing why capsules survive altitude and weather changes.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic vent');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '93615873-9675-4886-bd14-1c74250d0250','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='93615873-9675-4886-bd14-1c74250d0250') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='93615873-9675-4886-bd14-1c74250d0250');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'da317ed7-7809-4e25-a6f0-6797cb0fd391','Acoustic-overload recovery','How quickly a microphone or its electronics return to normal, low-distortion operation after a sound transient drives them past the acoustic overload point. Good recovery means the output settles immediately without lingering distortion, offset, or muting once the loud event passes.','This is how fast a mic bounces back after a very loud sound. A sharp drum hit can push it into overload for an instant. A good mic clears up right away. A poor one stays distorted or dips for a moment.','It matters because brief peaks should not smear the audio that follows once the microphone is briefly overdriven.','Testing a mic on snare rimshots, a technician listens for clean recovery rather than a dull smear after each hit.','Specification',ARRAY['Acoustic overload point','Capacitive sensing','Bias voltage','Capacitive loading']::text[],ARRAY['Confusing overload recovery with the steady maximum SPL rating itself.','Blaming the microphone when a preamp is the part clipping.','Ignoring recovery behavior on percussive, transient-heavy sources.']::text[],ARRAY['Evaluating a mic for close percussion with sharp transients.','Comparing capsules on sudden loud vocal bursts.','Diagnosing a brief dropout after each loud drum hit.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic-overload recovery');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'da317ed7-7809-4e25-a6f0-6797cb0fd391','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='da317ed7-7809-4e25-a6f0-6797cb0fd391') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='da317ed7-7809-4e25-a6f0-6797cb0fd391');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cce67b16-edea-4796-9860-a0e11b3d7c8f','Air gap','The small spacing between the movable diaphragm and the fixed backplate in a condenser microphone capsule, typically only tens of micrometres. Because capacitance rises as this gap shrinks, the air-gap dimension sets the capsule''s baseline capacitance and strongly influences its sensitivity.','This is the tiny gap between the two plates of a condenser capsule. It is only a fraction of a millimeter wide. Sound moves the front plate, changing the gap. A smaller gap gives more output.','The air gap sets the capsule capacitance and how much the voltage changes as sound moves the diaphragm.','A technician handles a bare capsule carefully because dust or a touch in the tens-of-micrometre air gap can short or detune it.','Construction',ARRAY['Capacitive sensing','Bias voltage','Capsule resonance','Capacitive loading']::text[],ARRAY['Assuming a wider air gap gives more output rather than less.','Confusing the condenser air gap with a dynamic mic''s magnetic gap.','Believing the gap is large when it is only microns wide.']::text[],ARRAY['Explaining why humidity and dust harm condenser capsules.','Relating capsule capacitance to its air-gap dimension.','Handling a capsule during a careful cleaning.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Air gap');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cce67b16-edea-4796-9860-a0e11b3d7c8f','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cce67b16-edea-4796-9860-a0e11b3d7c8f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cce67b16-edea-4796-9860-a0e11b3d7c8f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'edf844a1-18b4-47d7-ab96-aee377b57320','Ambisonic microphones','Microphones, usually built from a coincident cluster of four capsules in a tetrahedron, that capture a full-sphere sound field. Their raw A-format capsule signals are matrixed into B-format channels (an omnidirectional W plus figure-of-eight X, Y and Z components), from which surround, binaural, or virtual-reality mixes can be decoded. Ambisonics is a generic method; SoundField was an early trademarked implementation.','These mics record sound from every direction at once. Four small capsules face outward like a pyramid. A computer blends their signals into one full-sphere signal. It can then make surround or headphone sound.','They let one compact array record a whole three-dimensional sound field for flexible surround and immersive playback.','A technician records ambience with a tetrahedral mic, converts A-format to B-format, then decodes it for a 360-degree video soundtrack.','Array technique',ARRAY['Blumlein configuration','Bidirectional response','Acceptance angle','Angular response']::text[],ARRAY['Skipping the A-format to B-format conversion step before decoding.','Treating Ambisonics as a brand rather than a general method.','Assuming raw capsule outputs are directly listenable surround.']::text[],ARRAY['Capturing immersive ambience for a virtual-reality film.','Recording a spatial room impulse for game audio.','Producing a surround mix decoded from one array.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ambisonic microphones');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'edf844a1-18b4-47d7-ab96-aee377b57320','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='edf844a1-18b4-47d7-ab96-aee377b57320') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='edf844a1-18b4-47d7-ab96-aee377b57320');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '10746de2-0db6-4604-8356-f1a51ccd512b','Angular response','The way a microphone''s sensitivity changes with the direction of arriving sound, expressed as output level versus angle. Plotted around the microphone it forms the polar pattern, and it usually varies with frequency, tightening at higher frequencies.','This describes how a mic''s loudness changes as sound comes from different angles. Sound from the front may be strong. Sound from the side or back may be weaker. Drawn as a circle, this makes the polar pattern.','It tells the engineer how directional a mic is and where its strong and weak pickup directions lie.','A technician reads a mic''s angular response to point its weakest angle toward a stage monitor to fight feedback.','Polar response',ARRAY['Azimuth response','Acceptance angle','Cardioid family','Bidirectional response']::text[],ARRAY['Assuming angular response is the same at every frequency.','Confusing angular response with frequency response on-axis.','Reading only the front lobe and ignoring rear sensitivity.']::text[],ARRAY['Aiming a cardioid null at a floor monitor to stop feedback.','Comparing polar plots when choosing a stage vocal mic.','Explaining why off-axis sound sounds duller than on-axis.']::text[],'beginner',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Angular response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '10746de2-0db6-4604-8356-f1a51ccd512b','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='10746de2-0db6-4604-8356-f1a51ccd512b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='10746de2-0db6-4604-8356-f1a51ccd512b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '471b5080-652e-4626-bda9-db001e6a42c3','Application-specific integrated circuit','A custom integrated circuit built for one particular function rather than general-purpose use. In a MEMS microphone the ASIC generates the capsule bias by charge pump, buffers and amplifies the tiny capacitive signal, and in digital versions performs the analogue-to-digital conversion. ASIC is a generic engineering term, not a brand.','This is a chip designed to do one specific job. Inside a tiny MEMS mic, it powers the sensor and boosts its weak signal. Digital mics also use it to make the digital output. It is custom, not a general chip.','It provides the tailored on-chip electronics that bias, buffer, and often digitize a microphone''s signal in a tiny package.','A technician reads that a digital MEMS mic''s ASIC outputs a PDM bitstream, so no external preamp or converter is needed.','Electronics',ARRAY['Bottom-port microphone','Bias voltage','Capacitive sensing','Back-electret microphone']::text[],ARRAY['Thinking ASIC is a brand name rather than a design category.','Assuming every mic ASIC includes a digital converter.','Overlooking that the ASIC, not the MEMS element, sets output type.']::text[],ARRAY['Explaining how a MEMS mic works without a separate preamp.','Comparing analogue and digital MEMS microphone outputs.','Describing the charge pump that biases a MEMS element.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Application-specific integrated circuit');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '471b5080-652e-4626-bda9-db001e6a42c3','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='471b5080-652e-4626-bda9-db001e6a42c3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='471b5080-652e-4626-bda9-db001e6a42c3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c5be1edc-1d40-4401-90cc-cb1aaba4d68a','Azimuth response','A microphone''s sensitivity as a function of horizontal angle around it, that is, the polar response measured in the horizontal plane. It is the part of the full three-dimensional directivity most often plotted, since many sources and reflections lie in that plane.','This is how a mic''s loudness changes as sound moves around it sideways. It maps pickup in the flat, horizontal circle. Most polar charts show this view. It ignores sound arriving from directly above or below.','It describes horizontal-plane directivity, which is what matters most for typical stage and studio placement.','A technician uses a cardioid''s azimuth response to rotate the mic so its horizontal null faces a noisy air vent.','Polar response',ARRAY['Angular response','Acceptance angle','Cardioid family','Bidirectional response']::text[],ARRAY['Assuming azimuth response fully describes a three-dimensional pattern.','Ignoring vertical-plane behavior for overhead sources.','Confusing azimuth response with tape-head azimuth alignment.']::text[],ARRAY['Rotating a mic so its side null faces horizontal noise.','Reading horizontal polar plots for a panel discussion setup.','Comparing directivity of stage mics in the seated plane.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Azimuth response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c5be1edc-1d40-4401-90cc-cb1aaba4d68a','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c5be1edc-1d40-4401-90cc-cb1aaba4d68a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c5be1edc-1d40-4401-90cc-cb1aaba4d68a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd7b6a860-9141-4c91-8703-0287f4b2da32','Back-electret microphone','An electret condenser microphone in which the permanently charged electret layer is applied to the fixed backplate instead of the diaphragm. Keeping the charge off the moving membrane allows a lighter, thinner diaphragm and generally better sensitivity and high-frequency response than earlier front-electret designs. Like all electret capsules it still needs power for its built-in impedance-converter FET.','This is an electret mic with the stored charge on the fixed back plate. That lets the moving front plate be very light. A lighter diaphragm sounds cleaner and reaches higher notes. It still needs power for its tiny built-in amplifier.','It improves electret sound quality by moving the fixed charge off the diaphragm so the membrane can be lighter.','A technician chooses a back-electret lavalier for its low mass and smooth top end, powering its FET from a bias supply.','Transducer type',ARRAY['Bias voltage','Capacitive sensing','Balanced microphone lines','Air gap']::text[],ARRAY['Thinking an electret needs no power because its charge is permanent.','Confusing back-electret with front-electret diaphragm designs.','Assuming all electrets have poor high-frequency performance.']::text[],ARRAY['Selecting a compact lavalier for broadcast use.','Explaining why an electret still needs plug-in or phantom power.','Comparing electret and true-condenser mics on a budget shoot.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Back-electret microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd7b6a860-9141-4c91-8703-0287f4b2da32','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d7b6a860-9141-4c91-8703-0287f4b2da32') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d7b6a860-9141-4c91-8703-0287f4b2da32');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '92f17cf9-ac0a-45ba-9ed6-6ed10450d1b2','Balanced microphone lines','Microphone interconnections that carry the signal differentially on two conductors of equal impedance, surrounded by a shield, most often on XLR connectors. Because interference couples equally into both conductors, the receiving differential input cancels it as common-mode noise, and the same wiring can also deliver phantom power equally on both signal pins.','These mic cables carry sound on two matched wires inside a shield. Noise hits both wires the same way. The input subtracts the two and cancels that noise. The same two wires can also carry phantom power to the mic.','Balanced lines let microphone signals run long distances quietly and carry phantom power on the same conductors.','A technician runs a 50 m balanced XLR mic line past dimmers with little hum, since the differential input rejects the common-mode interference.','Interconnect',ARRAY['Bias voltage','Back-electret microphone','Acoustic transducer','Capacitive loading']::text[],ARRAY['UNSAFE: Patching an unbalanced ribbon or wiring a shorted line while phantom power is live, which can damage the microphone.','UNSAFE: Hot-plugging XLR connectors with phantom on, causing loud thumps that can harm speakers and hearing.','Assuming any three-pin XLR cable is wired balanced when a conductor may be broken.','Believing balanced wiring boosts level rather than only rejecting noise.']::text[],ARRAY['Running long stage snake lines through an electrically noisy venue.','Delivering phantom power to a condenser over the mic cable.','Troubleshooting hum traced to a broken shield or unbalanced adapter.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Balanced microphone lines');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '92f17cf9-ac0a-45ba-9ed6-6ed10450d1b2','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='92f17cf9-ac0a-45ba-9ed6-6ed10450d1b2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='92f17cf9-ac0a-45ba-9ed6-6ed10450d1b2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8b9c5b6a-efb2-4fce-a603-a39a4648e792','Beam squint','A directivity defect in which a microphone array''s axis of maximum sensitivity tilts away from its intended geometric axis, often changing with frequency. It appears in interference-tube shotgun microphones and in multi-element line arrays, where the main lobe can point slightly off the physical aiming line at high frequencies.','This is when a directional mic''s strongest angle drifts off its aim line. The mic points one way, but its best pickup leans to the side. It often gets worse at high frequencies. Long shotgun and line-array mics can show it.','Recognizing beam squint helps an engineer aim narrow mics accurately despite frequency-dependent lobe shifts.','A technician re-aims a long shotgun mic slightly, checking high-frequency clarity, to correct a squint pulling the beam off the actor.','Directivity',ARRAY['Angular response','Acceptance angle','Azimuth response','Cardioid family']::text[],ARRAY['Assuming a narrow mic always points exactly along its body axis.','Ignoring that squint varies with frequency, not just aim.','Confusing beam squint with simple mis-aiming of the mic.']::text[],ARRAY['Aiming a long shotgun mic for dialogue on a film set.','Analyzing high-frequency lobe tilt in a line-array mic.','Explaining uneven pickup from a highly directional capsule.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Beam squint');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8b9c5b6a-efb2-4fce-a603-a39a4648e792','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8b9c5b6a-efb2-4fce-a603-a39a4648e792') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8b9c5b6a-efb2-4fce-a603-a39a4648e792');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f5d7e1ee-0b5b-48bf-ac02-51c41b110870','Bias voltage','The steady DC polarizing voltage applied across a true condenser capsule so that sound-driven capacitance changes produce an output voltage. Capsules are commonly polarized around 60 V, often derived internally from 48 V phantom power, whereas electret capsules replace this external bias with a permanent stored charge. Output level rises roughly in proportion to the bias voltage.','This is the fixed voltage placed across a condenser capsule. It lets tiny motion of the diaphragm make a signal. More bias gives more output. Electret mics skip it because their charge is built in.','The bias polarizes the capsule so its capacitance changes are turned into a usable audio voltage.','A technician knows a condenser''s internal circuit steps 48 V phantom up to roughly 60 V bias for the capsule; higher bias yields more sensitivity.','Electronics',ARRAY['Capacitive sensing','Back-electret microphone','Balanced microphone lines','Air gap']::text[],ARRAY['UNSAFE: Feeding 48 V phantom to a passive ribbon mic, whose bias needs differ and which can be damaged by faults or shorts.','UNSAFE: Touching a charged capsule or bias circuit, which can hold voltage and disturb the delicate element.','Assuming electret capsules use an external bias voltage.','Confusing capsule bias voltage with the 48 V phantom supply itself.']::text[],ARRAY['Explaining why a condenser needs powering but an electret stores charge.','Diagnosing low output traced to a failing bias supply.','Deciding whether phantom power is safe for a given mic type.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bias voltage');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f5d7e1ee-0b5b-48bf-ac02-51c41b110870','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f5d7e1ee-0b5b-48bf-ac02-51c41b110870') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f5d7e1ee-0b5b-48bf-ac02-51c41b110870');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6b613765-c528-47ae-a575-4b6b0e9b341b','Bidirectional response','A polar pattern, also called figure-of-eight, with equal maximum sensitivity to the front and rear and complete nulls at the sides. It arises from a pure pressure-gradient capsule whose sensitivity follows the cosine of the arrival angle, so sound at 90 degrees is rejected.','This pattern hears the front and back equally well. It ignores sound from the two sides. Its shape looks like a figure eight. Ribbon mics naturally have this pattern.','It provides strong side rejection and is a building block for coincident stereo and mid-side recording.','A technician turns a figure-eight so its side null, where response is zero, faces a noisy source; at 45 degrees the level is 20*log10(cos45) = -3 dB.','Polar response',ARRAY['Blumlein configuration','Cardioid family','Angular response','Acoustic vent']::text[],ARRAY['Forgetting the rear lobe is fully sensitive, not rejected.','Assuming the nulls are broad when they are sharp at 90 degrees.','Ignoring that the rear lobe is opposite in polarity to the front.']::text[],ARRAY['Placing the side null of a figure-eight toward a loud instrument.','Building a Blumlein or mid-side pair for stereo.','Using a ribbon''s rear lobe to capture room ambience.']::text[],'intermediate','E(theta) = cos(theta)','The relative sensitivity equals the cosine of the angle between the sound''s arrival direction and the microphone''s front axis.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bidirectional response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6b613765-c528-47ae-a575-4b6b0e9b341b','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6b613765-c528-47ae-a575-4b6b0e9b341b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6b613765-c528-47ae-a575-4b6b0e9b341b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '77c11718-eca1-42c1-ae71-c421b3ec9241','Blumlein configuration','A coincident stereo microphone technique using two bidirectional capsules mounted one above the other and crossed at 90 degrees, aimed symmetrically at the source. Named after Alan Blumlein, whose 1931 patent set out stereophonic methods, it captures accurate stereo imaging through level differences alone while its side and rear lobes gather room sound.','This is a stereo setup using two figure-eight mics. They sit together, crossed at ninety degrees. Each faces halfway toward the source. The pair gives a natural, precise stereo image plus room sound.','It delivers sharp, well-localized coincident stereo with a strong sense of the recording space.','A technician crosses two figure-eight mics at 90 degrees over a small ensemble to capture a realistic Blumlein stereo image.','Stereo technique',ARRAY['Bidirectional response','Ambisonic microphones','Acceptance angle','Cardioid family']::text[],ARRAY['Using cardioids instead of the required bidirectional capsules.','Failing to keep the two capsules truly coincident and crossed at 90 degrees.','Forgetting the rear lobes pick up strong room reflections.']::text[],ARRAY['Recording a string quartet with a coincident stereo pair.','Capturing a lively room''s ambience along with the source.','Teaching the origin of stereo through Blumlein''s patent.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Blumlein configuration');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '77c11718-eca1-42c1-ae71-c421b3ec9241','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='77c11718-eca1-42c1-ae71-c421b3ec9241') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='77c11718-eca1-42c1-ae71-c421b3ec9241');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '95a4fcd5-5ea8-477d-8e8a-7d4bdee2cc82','Bottom-port microphone','A surface-mount MEMS or electret microphone whose sound inlet is on the bottom face, the same side as the solder pads, so sound reaches the element through a hole in the circuit board. It contrasts with a top-port design, where the inlet is on the lid, and the choice affects PCB layout and acoustic sealing.','This is a tiny mic with its sound hole on the bottom. Sound reaches it through a hole in the circuit board. A top-port mic instead opens on its top lid. The choice changes how the board is designed.','The bottom-port layout lets product designers route sound through the PCB, which can improve sealing and space use.','A technician aligns a gasket between a bottom-port MEMS mic and the board hole so no sound leaks around the acoustic path.','Construction',ARRAY['Acoustic port','Application-specific integrated circuit','Acoustic vent','Capacitive sensing']::text[],ARRAY['Forgetting a bottom-port mic needs a matching hole in the PCB.','Mixing up top-port and bottom-port sound-path requirements.','Skipping the gasket seal and letting sound leak around the port.']::text[],ARRAY['Laying out a smartphone board for a bottom-port MEMS mic.','Choosing port style to suit a device''s mechanical design.','Diagnosing weak pickup from a misaligned board port.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bottom-port microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '95a4fcd5-5ea8-477d-8e8a-7d4bdee2cc82','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='95a4fcd5-5ea8-477d-8e8a-7d4bdee2cc82') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='95a4fcd5-5ea8-477d-8e8a-7d4bdee2cc82');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4da361b5-1e1b-46b9-bcf1-26e8a4a838d2','Boundary microphones','Microphones designed to lie on a large flat surface with the capsule in the pressure zone just above it, so direct and surface-reflected sound arrive together instead of causing comb filtering. Placing the diaphragm at the boundary also gives a pressure doubling of about 6 dB. The Pressure Zone Microphone (PZM) is a trademarked Crown design of this generic type.','These mics sit flat on a surface like a floor or table. The capsule stays very close to that surface. This avoids the hollow sound of a mic hovering above it. It also gains about 6 decibels from the surface.','They capture clear sound near a surface without the comb filtering that a spaced mic near a reflection would suffer.','A technician tapes a boundary mic to a conference table or stage floor to pick up talkers evenly with no phase cancellation from the surface.','Microphone type',ARRAY['Acoustic leakage','3:1 placement guideline','Acceptance angle','Acoustic transducer']::text[],ARRAY['Mounting it on a surface too small to support low frequencies.','Treating PZM as a generic term when it is a Crown trademark.','Lifting the mic off the boundary and reintroducing comb filtering.']::text[],ARRAY['Picking up a conference table full of talkers.','Miking a stage floor for theater or a piano lid.','Capturing room ambience from a wall boundary.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Boundary microphones');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4da361b5-1e1b-46b9-bcf1-26e8a4a838d2','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4da361b5-1e1b-46b9-bcf1-26e8a4a838d2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4da361b5-1e1b-46b9-bcf1-26e8a4a838d2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '538bec77-6dbc-42e1-832f-d25bb46f249b','Capacitive loading','The effect of shunt capacitance, such as long cable runs or stray circuit capacitance, added across a signal node. On the high-impedance output of a condenser capsule or a high-impedance line it forms a low-pass filter with the source resistance, rolling off high frequencies and reducing signal, which is why capsules are buffered by a nearby impedance converter.','This is extra capacitance added by cables or wiring on a signal. On a high-impedance line it acts like a filter. It quietly cuts the high frequencies and weakens the signal. That is why condenser mics buffer the capsule right away.','Understanding capacitive loading explains why fragile high-impedance signals must be buffered before running down a cable.','A technician avoids long cable on a passive high-impedance mic, since the added capacitance would dull the highs before the buffer stage.','Electronics',ARRAY['Capacitive sensing','Air gap','Balanced microphone lines','Bias voltage']::text[],ARRAY['Running a high-impedance signal far and blaming the mic for lost highs.','Ignoring cable capacitance when placing a buffer or preamp.','Assuming a balanced low-impedance output is as loading-sensitive.']::text[],ARRAY['Explaining why condenser capsules use an on-board buffer.','Diagnosing dull highs on a long high-impedance run.','Choosing low-capacitance cable for sensitive lines.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Capacitive loading');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '538bec77-6dbc-42e1-832f-d25bb46f249b','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='538bec77-6dbc-42e1-832f-d25bb46f249b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='538bec77-6dbc-42e1-832f-d25bb46f249b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4f7e6a3e-754d-4935-adc6-377c7917a1e0','Capacitive sensing','The transduction principle of a condenser microphone, in which sound moves a thin diaphragm relative to a fixed backplate and changes the capacitance between them. With the capsule charge held constant, the varying capacitance produces a varying output voltage, because voltage equals charge divided by capacitance.','This is how a condenser mic turns sound into a signal. Two plates form a capacitor. Sound moves one plate, changing the capacitance. With a fixed charge, that changes the voltage we read.','It is the working method behind condenser and electret microphones, converting diaphragm motion into an electrical signal.','For a plate area of 3.1e-4 m^2 and a 20 micrometre gap, C = 8.85e-12 * 3.1e-4 / 20e-6 = 137 pF; motion changes C, and V = Q/C changes with it.','Transduction',ARRAY['Air gap','Bias voltage','Capacitive loading','Back-electret microphone']::text[],ARRAY['Thinking a condenser generates its own signal without stored charge.','Assuming voltage rises when capacitance rises, when it falls at fixed charge.','Confusing capacitive sensing with a dynamic coil-and-magnet method.']::text[],ARRAY['Explaining why condenser mics need power to hold their charge.','Relating diaphragm motion to capacitance and output voltage.','Comparing condenser and dynamic transduction methods.']::text[],'intermediate','C = epsilon0 * epsilon_r * A / d ;  V = Q / C','Capacitance equals the permittivity of the gap times the plate area divided by the plate spacing; with a fixed charge, the output voltage equals that charge divided by the capacitance.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Capacitive sensing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4f7e6a3e-754d-4935-adc6-377c7917a1e0','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4f7e6a3e-754d-4935-adc6-377c7917a1e0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4f7e6a3e-754d-4935-adc6-377c7917a1e0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '197e75ef-75aa-430c-853c-612f4fe1ff0a','Capsule resonance','The main mechanical-acoustical resonant frequency of a microphone''s diaphragm-and-cavity system, where the moving mass and stiffness peak in response. Condenser capsules are usually tuned so this fundamental sits high, near or above 10 kHz, and is damped, giving a smooth response with a gentle presence rise rather than a sharp peak.','This is the natural ringing frequency of a mic''s diaphragm system. Every diaphragm has a frequency it vibrates most easily. Designers place it high and damp it. That keeps the sound smooth instead of peaky.','Its placement and damping shape a microphone''s high-frequency response and character.','A technician hears a mic''s airy presence lift and recognizes it as a damped capsule resonance tuned high in the audio band.','Construction',ARRAY['Cavity resonance','Air gap','Acoustic labyrinth','Capacitive sensing']::text[],ARRAY['Assuming a well-designed capsule has no resonance at all.','Confusing capsule resonance with an enclosed cavity resonance.','Expecting a sharp peak when good designs damp the resonance.']::text[],ARRAY['Explaining a mic''s high-frequency presence bump.','Comparing bright and neutral capsules by resonance tuning.','Understanding why diaphragm mass affects top-end response.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Capsule resonance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '197e75ef-75aa-430c-853c-612f4fe1ff0a','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='197e75ef-75aa-430c-853c-612f4fe1ff0a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='197e75ef-75aa-430c-853c-612f4fe1ff0a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7f8448d4-8103-428d-be0e-a7945637e658','Cardioid family','The set of first-order directional patterns produced by mixing an omnidirectional pressure component with a bidirectional pressure-gradient component. Their common form is A plus B times the cosine of the angle, with A and B summing to one; adjusting the balance yields subcardioid, cardioid, supercardioid, and hypercardioid patterns with different rear rejection.','This is the group of related directional patterns. Each blends a round pattern with a figure eight. Changing the blend gives cardioid, supercardioid, and hypercardioid. They differ in how much rear sound they reject.','The family lets engineers pick a directivity that best rejects unwanted sound from a chosen direction.','A technician switches from cardioid to hypercardioid to place a deeper rear-side null on a monitor; a true cardioid, 0.5+0.5cos(theta), rejects fully at 180 degrees.','Polar response',ARRAY['Cardioid formation','Bidirectional response','Angular response','Acceptance angle']::text[],ARRAY['Believing supercardioid and hypercardioid have no rear pickup.','Assuming a cardioid rejects the sides as strongly as a figure eight.','Forgetting that tighter front patterns bring back a rear lobe.']::text[],ARRAY['Choosing a pattern to reject a specific monitor position.','Comparing rear lobes of supercardioid and hypercardioid mics.','Selecting directivity for a noisy stage vocal.']::text[],'intermediate','E(theta) = A + B * cos(theta),  A + B = 1','The relative sensitivity equals an omnidirectional part plus a gradient part times the cosine of the arrival angle, with the two parts adding to one.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cardioid family');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7f8448d4-8103-428d-be0e-a7945637e658','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7f8448d4-8103-428d-be0e-a7945637e658') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7f8448d4-8103-428d-be0e-a7945637e658');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a9df7499-fca0-4c45-9b12-686a33f92815','Cardioid formation','The way a cardioid pattern is created, either by summing an omnidirectional pressure signal with a bidirectional gradient signal of equal strength, or in a single capsule by admitting rear sound through a delaying acoustic path so that back-arriving sound cancels at the diaphragm. Both routes yield the heart-shaped response that fully rejects sound from directly behind.','This is how a heart-shaped pattern is made. One way adds a round pattern to a figure eight equally. The other lets rear sound in through a delay path so it cancels. Either way the mic ignores sound from directly behind.','It explains the two standard methods designers use to build a rear-rejecting cardioid microphone.','A technician keeps a single-diaphragm cardioid''s rear delay port clear, knowing a blockage stops the cancellation that forms the pattern.','Polar response',ARRAY['Cardioid family','Bidirectional response','Acoustic vent','Acoustic labyrinth']::text[],ARRAY['Thinking a cardioid comes only from combining two separate capsules.','Blocking the rear delay port and losing the rear null.','Assuming the rear rejection holds equally at every frequency.']::text[],ARRAY['Explaining why a cardioid has a rear acoustic opening.','Diagnosing lost directionality after a rear port is covered.','Teaching the sum-of-patterns model of a cardioid.']::text[],'intermediate','E(theta) = 0.5 + 0.5 * cos(theta)','The cardioid''s relative sensitivity equals one half plus one half times the cosine of the arrival angle, giving full output ahead and zero behind.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cardioid formation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a9df7499-fca0-4c45-9b12-686a33f92815','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a9df7499-fca0-4c45-9b12-686a33f92815') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a9df7499-fca0-4c45-9b12-686a33f92815');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a4c1e1be-cb4c-44e5-bdab-fc920013c752','Cavity resonance','A resonance of an enclosed volume of air coupled through a small opening, behaving like a Helmholtz resonator, that can color a microphone''s response near its resonant frequency. Such cavities occur behind the diaphragm, in coupling chambers, or in a mic''s grille and housing, and their frequency depends on the opening area, the neck length, and the trapped air volume.','This is a resonance from a pocket of trapped air with a small opening. It acts like blowing across a bottle. Near its special frequency it boosts or colors the sound. Mic cavities and grilles can create these bumps.','Knowing cavity resonance helps explain and control unwanted peaks a microphone''s internal volumes can add.','For a 10 cm^3 cavity with a 1 cm^2, 5 mm neck: f = (343/6.28)*sqrt(1e-4/(1e-5*5e-3)) = about 2.4 kHz of coloration.','Acoustics',ARRAY['Capsule resonance','Acoustic port','Acoustic vent','Acoustic labyrinth']::text[],ARRAY['Confusing an air-cavity resonance with the diaphragm''s own resonance.','Ignoring that a grille or housing cavity can add a response peak.','Assuming a larger cavity always resonates at a higher frequency.']::text[],ARRAY['Explaining a response bump traced to a mic''s grille cavity.','Analyzing coloration from a coupling chamber in a capsule.','Designing a housing to avoid an audible cavity peak.']::text[],'advanced','f = (c / (2*pi)) * sqrt(A / (V * L))','The Helmholtz resonant frequency equals the speed of sound divided by two pi, times the square root of the neck opening area divided by the product of the cavity volume and the neck length.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cavity resonance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a4c1e1be-cb4c-44e5-bdab-fc920013c752','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a4c1e1be-cb4c-44e5-bdab-fc920013c752') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a4c1e1be-cb4c-44e5-bdab-fc920013c752');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9c4d29c9-b11e-455f-9698-29deda474c19','Ceramic microphone','A microphone that uses a piezoelectric ceramic element, such as barium titanate or lead zirconate titanate, which generates a voltage when sound flexes it. These capsules are rugged, high in output impedance, and modest in fidelity, so they historically served communications, toys, and contact-pickup roles rather than high-quality recording.','This mic uses a piezo ceramic that makes voltage when it bends. Sound flexes the ceramic and creates a signal. It is tough and cheap but not very hi-fi. It was common in old communication gear and toys.','It offers a simple, durable, self-generating transducer where low cost and ruggedness matter more than sound quality.','A technician expects a ceramic contact pickup to be rugged and high-impedance, so it needs a high-impedance input to keep its low end.','Transducer type',ARRAY['Acoustic transducer','Capacitive sensing','Capacitive loading','Bias voltage']::text[],ARRAY['Confusing a piezoelectric ceramic mic with a condenser capsule.','Loading its high-impedance output with a low-impedance input and losing bass.','Expecting studio-grade fidelity from a ceramic element.']::text[],ARRAY['Identifying an old communications or intercom microphone.','Using a ceramic contact pickup on an instrument.','Explaining why vintage ceramic mics sound thin and colored.']::text[],'beginner',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ceramic microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9c4d29c9-b11e-455f-9698-29deda474c19','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9c4d29c9-b11e-455f-9698-29deda474c19') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9c4d29c9-b11e-455f-9698-29deda474c19');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '503913e4-64d0-4e0f-a6f9-3fbf7b343bf5','Coherence matrix','In microphone-array and dual-channel measurement work, a coherence matrix holds, at each frequency, the magnitude-squared coherence between every pair of sensor channels, formed from their auto- and cross-spectral densities. Each element lies between 0 (no linear relation) and 1 (a perfect linear relation) at that frequency.','A coherence matrix compares signals from many microphones. Each number shows how alike two mic signals are at one frequency. A value of one means they match perfectly. A value of zero means they share nothing.','It quantifies how correlated array or measurement channels are, which guides beamformer design and separates coherent signal from incoherent noise.','With cross-spectrum magnitude |S12|=0.8 and autospectra S11=S22=1, the coherence is 0.8^2/(1*1)=0.64, so 64 percent of the power is linearly shared at that frequency.','Array processing',ARRAY['Cross-spectral matrix','Complex weighting','Delay estimation','Directivity order','Diffuse-field response']::text[],ARRAY['Reading coherence as a single time correlation instead of a value per frequency.','Expecting coherence above 1, when it is bounded between 0 and 1.','Trusting coherence from too few averages, which biases it upward.']::text[],ARRAY['Deciding which array channels carry a common source.','Setting beamformer behavior from measured channel coherence.','Judging data quality in dual-channel FFT measurements.']::text[],'advanced','gamma^2_ij(f) = |S_ij(f)|^2 / (S_ii(f) * S_jj(f))','The squared coherence of two channels equals the squared magnitude of their cross-spectrum divided by the product of their two auto-spectra.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Coherence matrix');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '503913e4-64d0-4e0f-a6f9-3fbf7b343bf5','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='503913e4-64d0-4e0f-a6f9-3fbf7b343bf5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='503913e4-64d0-4e0f-a6f9-3fbf7b343bf5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '54885556-26c0-4092-a6d0-5e2984cb7c50','Coincident stereo arrays','A coincident stereo array places two directional microphone capsules at essentially the same point in space, angled apart, so the two channels differ only in level and not in arrival time. Classic examples are the XY pair, the Blumlein crossed figure-eights, and mid-side.','Coincident stereo puts two directional mics at almost the same spot. They point in different directions. Stereo comes only from loudness differences, not timing. XY and Blumlein are common examples.','It captures a stereo image that stays strongly mono-compatible because both channels share arrival time and differ only in level.','An engineer mounts two cardioids one above the other, capsules nearly touching, splayed about 90 to 135 degrees, to record an ensemble that also folds cleanly to mono.','Stereo technique',ARRAY['Blumlein pair','Mid-side technique','XY technique','ORTF technique','Differential-pressure microphone']::text[],ARRAY['Confusing coincident (level-difference) methods with spaced (time-difference) methods.','Assuming a wider capsule angle only widens the image without weakening the center.','Adding capsule spacing and then getting comb filtering when summed to mono.']::text[],ARRAY['Recording a choir with a mono-safe stereo pair.','Setting drum overheads that collapse to mono cleanly.','Broadcast work where mono compatibility is required.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Coincident stereo arrays');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '54885556-26c0-4092-a6d0-5e2984cb7c50','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='54885556-26c0-4092-a6d0-5e2984cb7c50') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='54885556-26c0-4092-a6d0-5e2984cb7c50');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3fe4fe9c-64d1-4538-a0ce-2dc9f201c5f0','Complex weighting','In array processing, complex weighting multiplies each microphone signal by a complex coefficient carrying both a magnitude and a phase before the signals are summed. The weight vector applied as y = w^H x sets the array''s beam direction, sidelobe levels, and nulls.','Each microphone in an array gets its own multiplier. The multiplier changes both level and phase, which is timing. Adding the adjusted signals aims the array. This shapes where it listens and where it ignores.','It lets a fixed set of microphones electronically point, sharpen, or null directions without any physical movement.','For a two-mic array, weights w=[0.5, 0.5*exp(j*phi)] delay one channel by phase phi and sum the pair, steering the beam off the broadside axis.','Array processing',ARRAY['Delay estimation','Cross-spectral matrix','Coherence matrix','Directivity order','Directivity pattern']::text[],ARRAY['Using real gains only and losing the phase steering that a complex weight provides.','Ignoring that the ideal weights change with frequency.','Forgetting that aggressive weights can raise the array''s white-noise gain.']::text[],ARRAY['Designing a delay-and-sum beamformer.','Placing a null on a fixed noise source.','Steering a conferencing array toward a talker.']::text[],'advanced','y(f) = w^H * x(f)','The array output equals the conjugate-transpose of the complex weight vector multiplied by the vector of microphone signals.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Complex weighting');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3fe4fe9c-64d1-4538-a0ce-2dc9f201c5f0','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3fe4fe9c-64d1-4538-a0ce-2dc9f201c5f0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3fe4fe9c-64d1-4538-a0ce-2dc9f201c5f0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '02707489-dcd4-42de-92de-ff30eaad4740','Condenser capsule','A condenser (capacitor) capsule transduces sound with a thin conductive diaphragm that forms one plate of a capacitor facing a fixed backplate. Sound moving the diaphragm changes the plate spacing and therefore the capacitance, which, with a fixed charge on the plates, produces the output voltage.','A condenser capsule works like a tiny charged capacitor. A light diaphragm is one plate and a fixed backplate is the other. Sound moves the diaphragm and changes the gap. That changing gap makes the electrical signal.','It converts sound into an electrical signal using very low moving mass, giving wide and flat frequency response.','With plate area A=2e-4 m^2 and gap d=20 micrometres, the capacitance is C=epsilon_0*A/d=8.85e-12*2e-4/2e-5, about 8.9e-11 F (roughly 89 pF).','Condenser transducer',ARRAY['Condenser polarization','Electret capsule','Electrostatic transduction','Diaphragm resonance','Dual diaphragm']::text[],ARRAY['Expecting the capsule to drive a load directly, when it needs a high-impedance buffer.','Confusing a capacitance change with a resistance change.','Assuming a larger capsule always sounds better.']::text[],ARRAY['Selecting a studio vocal condenser.','Explaining why condensers require power.','Servicing a contaminated capsule.']::text[],'intermediate','C = epsilon_0 * A / d','The plate capacitance equals the permittivity of free space times the plate area divided by the plate gap.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Condenser capsule');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '02707489-dcd4-42de-92de-ff30eaad4740','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='02707489-dcd4-42de-92de-ff30eaad4740') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='02707489-dcd4-42de-92de-ff30eaad4740');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7165c00c-2a2a-4afb-a89b-0181d97537e8','Condenser polarization','Condenser polarization is the fixed electric charge, or bias, placed on a condenser capsule so that diaphragm motion produces a voltage. It is supplied either by an external polarizing voltage (about 200 V for many measurement microphones, roughly 48 to 60 V inside studio mics) or stored permanently in an electret.','A condenser capsule needs a stored electric charge to work. This stored charge is called polarization. Some mics get it from a supply voltage. Electret mics keep the charge built in for life.','It sets up the electric field so that a sound-driven change in capacitance becomes a proportional output voltage.','For a fixed-charge capsule the open-circuit output is Delta_V = V0*(Delta_d/d0); a 60 V bias, 20 micrometre gap, and 2 nanometre diaphragm motion give Delta_V=60*(2e-9/2e-5)=6 mV.','Condenser transducer',ARRAY['Condenser capsule','Electret capsule','Electrostatic transduction','Dual diaphragm','Diaphragm resonance']::text[],ARRAY['Confusing the internal polarizing voltage with 48 V phantom power, which instead runs the electronics.','Thinking electret mics need no power, when their buffer still does.','Assuming more bias always means more output, ignoring arc-over limits.']::text[],ARRAY['Setting the polarization option on a measurement-mic preamp.','Explaining electret versus externally polarized capsules.','Understanding sensitivity change with bias voltage.']::text[],'advanced','Delta_V = V0 * Delta_d / d0','The output voltage equals the polarizing voltage times the diaphragm displacement divided by the nominal plate gap.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Condenser polarization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7165c00c-2a2a-4afb-a89b-0181d97537e8','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7165c00c-2a2a-4afb-a89b-0181d97537e8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7165c00c-2a2a-4afb-a89b-0181d97537e8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7c23df39-ea71-4377-9216-f61c05b03356','Critical distance and microphone placement','Critical distance, or reverberation radius, is the distance from a source at which the direct sound level equals the reverberant (diffuse) sound level in a room. A microphone placed closer than this favors direct sound, while one placed farther favors room reverberation.','In a room, direct sound fades with distance but reverberation stays fairly even. The distance where they are equal is the critical distance. Put the mic closer for a dry, clear sound. Put it farther for more room.','It guides how close to place a microphone in order to control the balance between direct sound and room reverberation.','For a source directivity Q=2 and room constant R=50 m^2, D_c=0.141*sqrt(2*50)=0.141*10=1.41 m; a close mic is placed well inside this for a dry sound.','Placement and acoustics',ARRAY['Distance factor','Diffuse-field response','Directivity pattern','Coincident stereo arrays','Environmental sensitivity']::text[],ARRAY['Thinking critical distance depends on loudness, when it depends on source Q and room absorption.','Assuming the reverberant level falls with distance the way direct sound does.','Leaving out source directivity Q in the estimate.']::text[],ARRAY['Deciding between close and distant miking in a live room.','Explaining why a distant mic sounds washed out.','Choosing overhead height in a reverberant hall.']::text[],'intermediate','D_c = 0.141 * sqrt(Q * R)','The critical distance in metres equals 0.141 times the square root of the source directivity factor times the room constant.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Critical distance and microphone placement');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7c23df39-ea71-4377-9216-f61c05b03356','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7c23df39-ea71-4377-9216-f61c05b03356') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7c23df39-ea71-4377-9216-f61c05b03356');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '785b3f04-b72a-4fe0-a5c8-5faf1d1931af','Cross-spectral matrix','The cross-spectral matrix (CSM), or cross-spectral density matrix, gathers at each frequency the auto- and cross-spectral densities among all channels of a microphone array. Element S_ij is the expected value of channel i''s spectrum times the complex conjugate of channel j''s, and the diagonal holds each channel''s power spectrum.','The cross-spectral matrix gathers spectra from every pair of microphones. The diagonal is each mic''s own power at each frequency. The off-diagonal shows how the pairs relate. Beamformers use it heavily.','It is the core statistic on which array beamformers and source-localization methods operate.','For a four-mic array the CSM at 1 kHz is a 4-by-4 complex matrix; the phases of its off-diagonal terms encode the source''s direction of arrival.','Array processing',ARRAY['Coherence matrix','Complex weighting','Delay estimation','Directivity order','Diffuse-field response']::text[],ARRAY['Treating the CSM as a time-domain covariance without any frequency dependence.','Estimating it from too few snapshots, giving a rank-deficient matrix.','Forgetting it is Hermitian rather than plainly symmetric.']::text[],ARRAY['Beamforming with a microphone array.','Producing acoustic source-localization maps.','Building an MVDR (Capon) beamformer.']::text[],'advanced','S_ij(f) = E{ X_i(f) * conj(X_j(f)) }','Each matrix element is the expected value of one channel''s spectrum times the complex conjugate of another channel''s spectrum at that frequency.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cross-spectral matrix');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '785b3f04-b72a-4fe0-a5c8-5faf1d1931af','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='785b3f04-b72a-4fe0-a5c8-5faf1d1931af') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='785b3f04-b72a-4fe0-a5c8-5faf1d1931af');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '60fa864e-67d0-4a70-a17e-c91a6c800493','Delay estimation','Delay estimation finds the time difference of arrival (TDOA) of a sound between two or more microphones, usually by locating the lag that maximizes their cross-correlation, often the generalized cross-correlation with phase transform (GCC-PHAT). The estimated delay is used to locate a source or align channels.','Sound reaches spaced microphones at slightly different times. Delay estimation finds that time gap. It usually looks for the shift that best lines up the two signals. The gap reveals where the sound came from.','It provides the arrival-time differences needed to locate or track a talker and to steer array beams.','With spacing d=0.2 m and arrival angle theta=60 degrees, the TDOA is tau=d*cos(theta)/c=0.2*0.5/343, about 2.9e-4 s (0.29 ms).','Array processing',ARRAY['Cross-spectral matrix','Coherence matrix','Complex weighting','Coincident stereo arrays','Directivity order']::text[],ARRAY['Using plain cross-correlation in reverberation, where GCC-PHAT is more robust.','Ignoring spatial aliasing when spacing exceeds half a wavelength.','Confusing a time difference of arrival with an absolute distance.']::text[],ARRAY['Locating a talker for a camera-tracking system.','Aligning distributed microphones.','Steering a beamformer toward a source.']::text[],'advanced','tau = d * cos(theta) / c','The time difference of arrival equals the microphone spacing times the cosine of the arrival angle divided by the speed of sound.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Delay estimation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '60fa864e-67d0-4a70-a17e-c91a6c800493','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='60fa864e-67d0-4a70-a17e-c91a6c800493') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='60fa864e-67d0-4a70-a17e-c91a6c800493');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '03ed93c8-d92b-4179-8ccf-26f80d8d8f15','Diaphragm resonance','Diaphragm (fundamental) resonance is the frequency at which a microphone''s diaphragm-and-suspension system vibrates most freely, set by its effective stiffness and moving mass. Its placement shapes the frequency response: condenser diaphragms are usually tuned high and damped, while many dynamics deliberately place a damped resonance within the audio band.','Every mic diaphragm has a natural bounce frequency. It depends on how stiff and how heavy the diaphragm is. Where this sits changes the mic''s tone. Designers place and damp it carefully.','It sets a key limit and a tone-shaping point in a microphone''s frequency response.','A diaphragm with stiffness k=200 N/m and mass m=5e-8 kg resonates at f0=(1/(2*pi))*sqrt(200/5e-8), about 10.1 kHz.','Transducer physics',ARRAY['Diaphragm size versus behavior','Condenser capsule','Dynamic-microphone induction','Directional behavior','Diffuse-field response']::text[],ARRAY['Assuming resonance is always a flaw, when dynamics often use it on purpose.','Thinking a higher resonance frequency automatically sounds better.','Ignoring damping, which controls how tall the resonant peak is.']::text[],ARRAY['Explaining a dynamic mic''s presence peak.','Comparing condenser and dynamic high-frequency behavior.','Reading a datasheet response curve.']::text[],'advanced','f0 = (1/(2*pi)) * sqrt(k/m)','The resonance frequency equals one over two pi times the square root of stiffness divided by moving mass.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Diaphragm resonance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '03ed93c8-d92b-4179-8ccf-26f80d8d8f15','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='03ed93c8-d92b-4179-8ccf-26f80d8d8f15') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='03ed93c8-d92b-4179-8ccf-26f80d8d8f15');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '804fc90d-2d88-4de5-8c40-e665cb89612e','Diaphragm size versus behavior','A microphone''s diaphragm diameter influences its self-noise, sensitivity, and directionality. Larger diaphragms generally give lower self-noise and higher output but become directional and uneven off-axis once their size approaches the sound wavelength, while small diaphragms stay more uniform and omnidirectional at high frequency.','Diaphragm size is a trade-off. Big diaphragms are quieter and more sensitive. But big diaphragms get directional and colored at high frequencies. Small diaphragms stay even and consistent off-axis.','It explains why engineers pick large- or small-diaphragm microphones for different jobs.','For a radius a=12 mm at 10 kHz, ka=2*pi*0.012*10000/343, about 2.2, well above 1, so the large diaphragm is directional and beamy up top.','Transducer physics',ARRAY['Diaphragm resonance','Directional behavior','Condenser capsule','Diffuse-field response','Elevation response']::text[],ARRAY['Believing large-diaphragm mics are always the better choice.','Expecting a large diaphragm to stay omnidirectional at high frequency.','Ignoring off-axis coloration when using large-diaphragm mics as room mics.']::text[],ARRAY['Choosing small- versus large-diaphragm mics for overheads.','Explaining off-axis high-frequency loss.','Predicting self-noise from capsule size.']::text[],'intermediate','ka = 2 * pi * a * f / c','The size parameter equals two pi times the diaphragm radius times frequency divided by the speed of sound.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Diaphragm size versus behavior');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '804fc90d-2d88-4de5-8c40-e665cb89612e','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='804fc90d-2d88-4de5-8c40-e665cb89612e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='804fc90d-2d88-4de5-8c40-e665cb89612e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b374a108-ed51-4c27-ab13-2b0c9d11d6cd','Differential-pressure microphone','A differential-pressure (pressure-gradient) microphone exposes both faces of its diaphragm to the sound field, so the diaphragm responds to the pressure difference across it rather than to absolute pressure. This gives an inherently directional response, ideally figure-eight, along with proximity effect at close distances.','This mic lets sound reach both faces of its diaphragm. The diaphragm moves from the pressure difference between the two sides. So it picks up front and back but rejects the sides. It also boosts bass up close.','It creates directional pickup and is the basis of figure-eight mics and, when combined with pressure operation, the cardioid family.','A ribbon mic is a differential-pressure type; its sensitivity follows cos(theta), so a source at 90 degrees (the side) is rejected while front and rear are equal.','Directional principle',ARRAY['Directivity pattern','Directional behavior','Dynamic-microphone induction','Diaphragm resonance','Coincident stereo arrays']::text[],ARRAY['UNSAFE: Feeding 48 V phantom power to a ribbon through a shorted or miswired cable can drive current through the delicate ribbon and destroy it.','Confusing pressure-gradient (directional) operation with pressure (omni) operation.','Forgetting the strong proximity bass boost when close-miking.']::text[],ARRAY['Recording brass with a figure-eight ribbon.','Building a Blumlein pair.','Explaining why a bidirectional mic rejects the sides.']::text[],'intermediate','r(theta) = cos(theta)','The ideal figure-eight sensitivity equals the cosine of the angle from the front axis.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Differential-pressure microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b374a108-ed51-4c27-ab13-2b0c9d11d6cd','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b374a108-ed51-4c27-ab13-2b0c9d11d6cd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b374a108-ed51-4c27-ab13-2b0c9d11d6cd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '009ee224-921c-48b6-bafa-9d3222a58f92','Diffuse-field microphone','A diffuse-field (random-incidence) microphone is a measurement microphone corrected to read flat when sound arrives equally from all directions, as in a reverberant field. Its response is equalized to compensate for the average, over all angles, of the pressure build-up and directional effects at its diaphragm.','This measurement mic is tuned for rooms full of reflected sound. There, sound hits it from every direction at once. The mic is corrected to read such a field flatly. It is used in reverberant test spaces.','It gives accurate readings where sound arrives from all directions, such as reverberation rooms and other diffuse fields.','A technician selects a diffuse-field microphone, or applies its diffuse-field correction, for reverberation-room sound-power tests rather than using a free-field microphone.','Measurement microphone',ARRAY['Diffuse-field response','Condenser capsule','Directional behavior','Directivity pattern','Environmental sensitivity']::text[],ARRAY['Using a free-field microphone or its correction in a diffuse field, causing high-frequency error.','Assuming any microphone reads correctly regardless of the sound field.','Ignoring how the protective grid changes the high-frequency response.']::text[],ARRAY['Sound-power measurement in a reverberation room.','Building-acoustics field measurements.','Choosing the correct IEC microphone type for the field.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Diffuse-field microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '009ee224-921c-48b6-bafa-9d3222a58f92','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='009ee224-921c-48b6-bafa-9d3222a58f92') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='009ee224-921c-48b6-bafa-9d3222a58f92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ce9d76ab-84c1-48a3-ab3e-9482611e69ce','Diffuse-field response','Diffuse-field (random-incidence) response is a microphone''s frequency response to sound arriving from all directions with equal probability and random phase, as opposed to its on-axis free-field response. It differs from the free-field curve because the microphone''s directional effects average out across all angles.','This is how a mic responds when sound comes from all directions at once. It differs from the response measured straight on-axis. Directional mics show less high end in a diffuse field. It matters in real, reflective rooms.','It predicts how a microphone behaves in reverberant, real-world fields rather than only straight on-axis.','A directional mic''s random-incidence datasheet curve shows less treble than its on-axis curve, so a distant mic in a live room sounds duller.','Response and measurement',ARRAY['Diffuse-field microphone','Directivity pattern','Directional behavior','Critical distance and microphone placement','Elevation response']::text[],ARRAY['Assuming the on-axis response applies at every angle.','Ignoring the diffuse-field curve when placing distant mics.','Confusing diffuse-field response with the off-axis response at one single angle.']::text[],ARRAY['Predicting distant-mic tone in a reverberant hall.','Reading random-incidence datasheet curves.','Choosing a microphone for room ambience.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Diffuse-field response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ce9d76ab-84c1-48a3-ab3e-9482611e69ce','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ce9d76ab-84c1-48a3-ab3e-9482611e69ce') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ce9d76ab-84c1-48a3-ab3e-9482611e69ce');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1671dda3-afa9-4e67-adfe-acc082af1f83','Digital microphone interface','A digital microphone interface carries a microphone''s output as a digital audio stream. In the AES42 standard it also supplies digital phantom power and a remote-control and synchronization channel over the same balanced XLR-type line, and the microphone contains its own analog-to-digital converter.','A digital microphone turns sound into data inside the mic itself. A digital interface carries that data to the recorder. The main standard is AES42. It also powers the mic and can control it over one cable.','It moves the analog-to-digital conversion into the microphone, removing a separate preamp and analog cable run.','An engineer connects an AES42 microphone to a matching interface, such as an RME DMC-842, which supplies 10 V digital phantom power and clocks and controls the mic remotely.','Digital interface',ARRAY['Condenser capsule','Dual diaphragm','Electret capsule','Directional behavior','Environmental sensitivity']::text[],ARRAY['Confusing AES42 digital phantom power (about 10 V) with analog 48 V phantom, which are not interchangeable.','Assuming any digital signal on an XLR is AES42.','Forgetting that AES42 microphones need clock synchronization.']::text[],ARRAY['Deploying digital microphones in a broadcast plant.','Interfacing an AES42 mic into a MADI system.','Adjusting microphone settings remotely.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Digital microphone interface');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1671dda3-afa9-4e67-adfe-acc082af1f83','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1671dda3-afa9-4e67-adfe-acc082af1f83') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1671dda3-afa9-4e67-adfe-acc082af1f83');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b53237b8-fd7c-4e68-a07e-a2eaf73288db','Directional behavior','Directional behavior describes how a microphone''s sensitivity changes with the angle of the arriving sound, that is, its polar pattern and how that pattern shifts with frequency. It ranges from omnidirectional (equal in all directions) through cardioid and hypercardioid to bidirectional.','Directional behavior is how a mic''s pickup changes with direction. Some mics hear all around equally. Others favor the front and reject the back or sides. This behavior also changes with frequency.','It determines which sounds a microphone favors or rejects based on where they arrive from.','Choosing a hypercardioid tames a room and nearby instruments, but the technician must remember its rear lobe still picks up sound from behind.','Directional principle',ARRAY['Directivity pattern','Directivity order','Elevation response','Diffuse-field response','Distance factor']::text[],ARRAY['Assuming a directional mic fully rejects the rear, when most have a rear lobe.','Ignoring that patterns narrow and grow uneven at high frequency.','Treating the printed pattern as valid at every frequency.']::text[],ARRAY['Picking a pattern to reduce feedback on stage.','Isolating one instrument from bleed.','Explaining off-axis coloration.']::text[],'beginner',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Directional behavior');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b53237b8-fd7c-4e68-a07e-a2eaf73288db','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b53237b8-fd7c-4e68-a07e-a2eaf73288db') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b53237b8-fd7c-4e68-a07e-a2eaf73288db');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '56c3d06a-d70d-4161-8bc5-b1dc10a5f6e6','Directivity order','Directivity order classifies a directional response by the highest power of cos(theta), equivalently the spherical-harmonic order, in its pattern. First-order microphones combine a pressure term and a pressure-gradient term as A + B*cos(theta), giving omni, cardioid, and figure-eight, while higher-order designs add cos-squared terms and beyond for sharper directivity.','Directivity order rates how sharp a mic''s aim is. First-order mics use one cosine term. They give patterns like cardioid and figure-eight. Higher-order arrays combine capsules for a much tighter beam.','It provides a framework for describing and designing patterns from simple first-order shapes to sharper higher-order responses.','A first-order cardioid follows r(theta)=0.5+0.5*cos(theta); adding a cos-squared term makes a second-order pattern with a narrower front lobe and more reach.','Directional theory',ARRAY['Directivity pattern','Directional behavior','Differential-pressure microphone','Distance factor','Complex weighting']::text[],ARRAY['Confusing the order with the specific named pattern.','Assuming higher order has no cost, when self-noise and size grow.','Expecting a first-order mic to reach shotgun-like directivity.']::text[],ARRAY['Specifying a shotgun or higher-order array.','Explaining the algebra of the cardioid family.','Comparing pattern sharpness across designs.']::text[],'advanced','r(theta) = A + B * cos(theta)   (first order)','A first-order pattern equals a fixed omni part plus a gradient part times the cosine of the arrival angle.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Directivity order');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '56c3d06a-d70d-4161-8bc5-b1dc10a5f6e6','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='56c3d06a-d70d-4161-8bc5-b1dc10a5f6e6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='56c3d06a-d70d-4161-8bc5-b1dc10a5f6e6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '29e4da97-4d14-471e-a5fd-e053165789a7','Directivity pattern','A directivity (polar) pattern is a plot of a microphone''s relative sensitivity against the angle of the arriving sound, usually drawn as a polar diagram at several frequencies. Standard first-order patterns are omnidirectional, cardioid, supercardioid, hypercardioid, and bidirectional.','A directivity pattern is a map of a mic''s pickup by direction. It is drawn as a round polar plot. It shows which angles are loud and which are rejected. Different mics have different shapes.','It tells the user at a glance which directions a microphone favors and which it rejects.','For a cardioid, A=0.5 gives r(theta)=0.5+0.5*cos(theta), so r(180 deg)=0 (full rear rejection) and r(90 deg)=0.5 (about 6 dB down at the sides).','Directional principle',ARRAY['Directional behavior','Directivity order','Elevation response','Distance factor','Diffuse-field response']::text[],ARRAY['Reading a single-frequency plot as valid across the whole band.','Confusing the null angles of supercardioid and hypercardioid.','Thinking a cardioid has a rear lobe, when it does not (super- and hypercardioids do).']::text[],ARRAY['Choosing a pattern from a datasheet polar plot.','Aiming a supercardioid null at a stage monitor.','Teaching the cardioid family.']::text[],'beginner','r(theta) = A + (1 - A) * cos(theta)','A first-order pattern equals the omni fraction plus one minus that fraction times the cosine of the arrival angle.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Directivity pattern');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '29e4da97-4d14-471e-a5fd-e053165789a7','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='29e4da97-4d14-471e-a5fd-e053165789a7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='29e4da97-4d14-471e-a5fd-e053165789a7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '81fda13b-5ee8-4bc2-ac39-b73eb6f221c5','Distance factor','The distance factor (distance-sensitivity factor, DSF) is how much farther a directional microphone can sit from a source than an omnidirectional one while keeping the same ratio of direct to reverberant sound. It equals the square root of the microphone''s directivity factor.','A directional mic can sit farther from a source than an omni and still sound as dry. The distance factor is that reach ratio. A cardioid can be about 1.7 times farther. A hypercardioid about 2 times.','It quantifies the working-distance advantage that a directional pattern gives in reverberant conditions.','A cardioid has a directivity factor of 3, so DSF=sqrt(3), about 1.73; if an omni works at 1 m, the cardioid holds the same direct-to-reverberant balance at about 1.73 m.','Directional theory',ARRAY['Critical distance and microphone placement','Directivity pattern','Directional behavior','Diffuse-field response','Directivity order']::text[],ARRAY['Thinking the distance factor increases loudness, when it preserves the direct-to-diffuse ratio, not level.','Confusing the distance factor with the directivity factor itself.','Assuming it holds at frequencies where the pattern degrades.']::text[],ARRAY['Placing a cardioid farther back in a live room.','Comparing the reach of a cardioid and a hypercardioid.','Explaining gain-before-feedback benefits of directional mics.']::text[],'intermediate','DSF = sqrt(DF)','The distance factor equals the square root of the directivity factor.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Distance factor');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '81fda13b-5ee8-4bc2-ac39-b73eb6f221c5','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='81fda13b-5ee8-4bc2-ac39-b73eb6f221c5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='81fda13b-5ee8-4bc2-ac39-b73eb6f221c5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '858d85ba-7a4f-4db6-a10d-858cb558e7ef','Dual diaphragm','A dual-diaphragm capsule uses two diaphragms mounted back-to-back on either side of a shared backplate. Varying the relative polarizing voltage on the two diaphragms blends their two opposing cardioid pickups to create selectable polar patterns from omni through cardioid to figure-eight.','This capsule has two diaphragms sharing one backplate. Each acts like a cardioid facing the opposite way. Changing the voltage balance between them mixes the two. That lets one mic switch between many pickup patterns.','It gives a single microphone electrically selectable polar patterns without swapping capsules.','On a multipattern condenser, the pattern switch changes the rear diaphragm''s bias: same-polarity equal gives omni, rear off gives cardioid, and opposite-polarity equal gives figure-eight.','Condenser transducer',ARRAY['Condenser capsule','Condenser polarization','Directivity pattern','Directional behavior','Electrostatic transduction']::text[],ARRAY['Thinking pattern selection is purely acoustic, when it is set by diaphragm bias.','Assuming both diaphragms are equally active for every pattern.','Confusing a dual-diaphragm capsule with a dual-capsule stereo microphone.']::text[],ARRAY['Setting a multipattern studio mic to figure-eight for mid-side.','Explaining remote pattern control.','Servicing a two-diaphragm capsule.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dual diaphragm');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '858d85ba-7a4f-4db6-a10d-858cb558e7ef','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='858d85ba-7a4f-4db6-a10d-858cb558e7ef') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='858d85ba-7a4f-4db6-a10d-858cb558e7ef');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '91d21008-2535-4972-8753-8ff58cf68218','Dynamic-microphone induction','In a dynamic (moving-coil) microphone, sound moves a diaphragm carrying a coil within a magnetic gap, and the coil''s motion induces a voltage by electromagnetic induction, proportional to the coil''s velocity. This makes the moving-coil capsule a velocity-type electrodynamic transducer that needs no external power.','A dynamic mic has a coil glued to its diaphragm. The coil sits in a magnet''s gap. When sound moves the coil, it generates a voltage. Faster motion makes a bigger signal, and no power is needed.','It converts sound into electricity ruggedly and without any supplied power.','With flux density B=1 T, coil wire length l=2 m, and velocity v=0.01 m/s, the output is e=B*l*v=1*2*0.01=0.02 V (20 mV).','Dynamic transducer',ARRAY['Electrodynamic transduction','Electromagnetic induction','Diaphragm resonance','Differential-pressure microphone','Electromechanical transducer']::text[],ARRAY['Thinking dynamic mics need phantom power, when they do not.','Confusing velocity-type moving-coil operation with a condenser''s displacement operation.','Assuming a bigger magnet alone always gives more output.']::text[],ARRAY['Choosing a rugged stage vocal microphone.','Explaining why dynamics tolerate very high SPL.','Contrasting dynamic and condenser powering.']::text[],'intermediate','e = B * l * v','The induced voltage equals the magnetic flux density times the conductor length in the field times the coil velocity.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dynamic-microphone induction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '91d21008-2535-4972-8753-8ff58cf68218','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='91d21008-2535-4972-8753-8ff58cf68218') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='91d21008-2535-4972-8753-8ff58cf68218');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b5425bf8-f1a7-4b08-ad52-1321cb2def6f','Electret capsule','An electret capsule is a condenser capsule whose polarizing charge is permanently stored in an electret material, a dielectric holding a frozen-in charge, placed either on the diaphragm (foil electret) or on the backplate (back electret). No external polarizing voltage is needed, though a built-in FET impedance converter still requires a small power supply.','An electret capsule is a condenser with its charge built in for life. A special material holds the charge permanently. So it needs no polarizing voltage. But it still needs a little power for its tiny internal amplifier.','It provides condenser performance without a high polarizing-voltage supply, enabling small and low-cost microphones.','A lavalier or measurement electret runs its internal FET from a 1.5 V cell or plug-in power, while the capsule''s stored charge itself never needs refreshing.','Condenser transducer',ARRAY['Condenser capsule','Condenser polarization','Electrostatic transduction','Diaphragm resonance','Digital microphone interface']::text[],ARRAY['Thinking electret mics need no power at all, when the FET buffer does.','Assuming electrets are always low quality, when back-electret measurement mics are precision devices.','Confusing the FET''s supply with the capsule''s polarization.']::text[],ARRAY['Using a lavalier electret on camera.','Choosing a back-electret measurement microphone.','Powering an electret from plug-in power.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Electret capsule');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b5425bf8-f1a7-4b08-ad52-1321cb2def6f','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b5425bf8-f1a7-4b08-ad52-1321cb2def6f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b5425bf8-f1a7-4b08-ad52-1321cb2def6f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd5f85711-39f3-4bd5-a9cd-d147e0e1835c','Electrical clipping point','The electrical clipping point is the output level at which a powered microphone''s internal electronics, its impedance converter or amplifier, can no longer swing cleanly, so the signal distorts. It sets the maximum clean output determined by the electronics and is distinct from acoustic overload of the capsule.','A powered mic''s electronics can only put out so much before distorting. That limit is the electrical clipping point. Past it, the signal turns to distortion. It is separate from the capsule''s own overload limit.','It defines the top of a microphone''s clean output range as set by its electronics rather than its capsule.','If a mic clips its output at about +12 dBu, a technician engages the mic''s 10 dB pad on loud sources so the electronics stay below that point.','Levels and limits',ARRAY['Condenser capsule','Environmental sensitivity','Electret capsule','Diaphragm resonance','Directional behavior']::text[],ARRAY['Confusing electrical clipping in the mic with acoustic overload of the capsule.','Thinking more preamp gain fixes a mic that is already clipping internally.','Ignoring the mic pad, which lowers the signal reaching the mic electronics.']::text[],ARRAY['Miking a loud guitar cabinet.','Deciding when to switch in the mic pad.','Reading a max-SPL and output specification.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Electrical clipping point');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd5f85711-39f3-4bd5-a9cd-d147e0e1835c','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d5f85711-39f3-4bd5-a9cd-d147e0e1835c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d5f85711-39f3-4bd5-a9cd-d147e0e1835c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4a057dc6-7870-43d9-8640-2e139487f574','Electrodynamic transduction','Electrodynamic transduction converts between mechanical (acoustical) and electrical energy through a conductor moving in a magnetic field: the moving conductor generates a voltage proportional to its velocity (microphone), and a current through it produces force (loudspeaker). Moving-coil and ribbon microphones both work this way.','Electrodynamic transduction uses a wire moving in a magnet. Moving the wire makes a voltage. Sending current through it makes a force. Moving-coil and ribbon mics work this way.','It is the working principle behind dynamic microphones and moving-coil loudspeakers.','A ribbon of length l=0.05 m in a field B=0.5 T moving at v=0.02 m/s produces e=B*l*v=0.5*0.05*0.02=5e-4 V (0.5 mV), which is why ribbons output low levels.','Transducer principle',ARRAY['Dynamic-microphone induction','Electromagnetic induction','Electromechanical transducer','Differential-pressure microphone','Electrostatic transduction']::text[],ARRAY['Confusing electrodynamic (velocity, no bias) with electrostatic (condenser) transduction.','Thinking ribbons and moving-coils use different principles, when both are electrodynamic.','UNSAFE: Patching phantom power to a ribbon through a faulty or shorted cable can force current through the ribbon and burn it out.']::text[],ARRAY['Explaining why ribbons output such low levels.','Comparing dynamic and condenser transduction.','Understanding reciprocity in a moving-coil driver.']::text[],'intermediate','e = B * l * v','The generated voltage equals the flux density times the conductor length in the field times its velocity.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Electrodynamic transduction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4a057dc6-7870-43d9-8640-2e139487f574','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4a057dc6-7870-43d9-8640-2e139487f574') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4a057dc6-7870-43d9-8640-2e139487f574');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c4fd231a-587b-4170-8753-743499b94a1e','Electromagnetic induction','Electromagnetic induction is described by Faraday''s law: a changing magnetic flux through a circuit induces an electromotive force (EMF) equal to the negative rate of change of that flux. It is the physical basis of dynamic (moving-coil and ribbon) microphones and other magnetic transducers.','A changing magnetic field through a coil creates a voltage. This is Faraday''s law of induction. The faster the field changes, the bigger the voltage. Dynamic microphones rely on this effect.','It is the fundamental law explaining how moving-conductor microphones generate their signal.','If the flux through a coil changes by 1e-3 Wb over 1e-3 s, the induced EMF has magnitude dPhi/dt=1e-3/1e-3=1 V for a single turn.','Physics principle',ARRAY['Electrodynamic transduction','Dynamic-microphone induction','Electromechanical transducer','Electrostatic transduction','Differential-pressure microphone']::text[],ARRAY['Thinking a steady, unchanging magnetic field induces a voltage, when only a changing one does.','Confusing induction with electrostatic, charge-based transduction.','Dropping the minus sign that encodes Lenz''s law direction.']::text[],ARRAY['Deriving a dynamic mic''s output.','Teaching transducer physics.','Explaining why static magnets alone make no signal.']::text[],'intermediate','EMF = -N * dPhi/dt','The induced voltage equals minus the number of turns times the rate of change of magnetic flux.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Electromagnetic induction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c4fd231a-587b-4170-8753-743499b94a1e','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c4fd231a-587b-4170-8753-743499b94a1e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c4fd231a-587b-4170-8753-743499b94a1e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '56d2f2fa-06f2-45a4-9bbe-6865b10ac801','Electromechanical transducer','An electromechanical transducer converts between electrical and mechanical energy in either direction. In audio, microphones turn mechanical (acoustical) motion into electrical signals while loudspeakers do the reverse, and the coupling may be electrodynamic, electrostatic, piezoelectric, or magnetic.','An electromechanical transducer swaps between motion and electricity. A microphone turns motion into a signal. A loudspeaker turns a signal back into motion. Both do the same job in reverse. The link can use a magnet, a charge, or a crystal.','It is the general class to which both microphones and loudspeakers belong.','Recognizing a mic and a speaker as reciprocal electromechanical transducers explains why a dynamic mic can act as a weak tiny speaker and the reverse.','Transducer principle',ARRAY['Electrodynamic transduction','Electrostatic transduction','Electromagnetic induction','Dynamic-microphone induction','Condenser capsule']::text[],ARRAY['Thinking transduction only works in one direction.','Assuming all microphones use the same transduction type.','Confusing the energy-conversion principle with the housing or the polar pattern.']::text[],ARRAY['Classifying transducer types in training.','Explaining reciprocity calibration.','Comparing microphone and loudspeaker operation.']::text[],'beginner',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Electromechanical transducer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '56d2f2fa-06f2-45a4-9bbe-6865b10ac801','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='56d2f2fa-06f2-45a4-9bbe-6865b10ac801') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='56d2f2fa-06f2-45a4-9bbe-6865b10ac801');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f0cbe337-bd5f-45a2-a787-29ddfabb4772','Electrostatic transduction','Electrostatic transduction uses a charged capacitor whose plate spacing varies with sound; with the charge held fixed, the changing capacitance produces a voltage. Condenser and electret microphones (and electrostatic loudspeakers) use this principle, which requires a polarizing charge and a high-impedance load.','Electrostatic transduction uses a charged capacitor. Sound changes the gap between its plates. With the charge fixed, that gap change makes a voltage. Condenser and electret mics work this way.','It is the working principle of condenser and electret microphones, giving low moving mass and wide response.','For a fixed-charge capsule the output is Delta_V=V0*Delta_d/d0; a 200 V measurement-mic bias, 20 micrometre gap, and 1 nanometre motion give Delta_V=200*(1e-9/2e-5)=10 mV.','Transducer principle',ARRAY['Condenser capsule','Condenser polarization','Electret capsule','Dual diaphragm','Electromechanical transducer']::text[],ARRAY['Confusing electrostatic (charge) with electrodynamic (magnetic) transduction.','Thinking the capsule can drive a low-impedance load directly.','Forgetting it needs a polarizing charge, whether external or from an electret.']::text[],ARRAY['Explaining condenser microphone operation.','Comparing condenser and dynamic principles.','Teaching why condensers need a buffer amplifier.']::text[],'intermediate','Delta_V = V0 * Delta_d / d0','The output voltage equals the polarizing voltage times the plate displacement divided by the nominal gap.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Electrostatic transduction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f0cbe337-bd5f-45a2-a787-29ddfabb4772','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f0cbe337-bd5f-45a2-a787-29ddfabb4772') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f0cbe337-bd5f-45a2-a787-29ddfabb4772');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '389c3390-2361-44bc-a647-bfc78a8f94de','Elevation response','Elevation response describes how a microphone''s sensitivity varies with the vertical (elevation) angle of the arriving sound, complementing its horizontal polar pattern. A body-of-revolution capsule is symmetric about its axis, but side-address and multi-capsule microphones can respond differently in the vertical plane.','A mic''s pickup can change with the up-and-down angle too, not just side to side. That is its elevation response. Round single-capsule mics behave the same all around their axis. Odd-shaped or array mics can differ vertically.','It captures how a microphone responds to sound arriving from above or below its main axis.','When boom-miking dialogue from above, the technician keeps the mic on-axis in elevation so the actor''s voice keeps its full high-frequency response.','Directional principle',ARRAY['Directivity pattern','Directional behavior','Diffuse-field response','Diaphragm size versus behavior','Distance factor']::text[],ARRAY['Assuming every microphone is perfectly symmetric in elevation.','Ignoring vertical off-axis coloration when boom-miking.','Confusing elevation response with simple horizontal polar plots.']::text[],ARRAY['Boom-miking film dialogue.','Aiming overheads by height and tilt.','Evaluating an array''s vertical directivity.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Elevation response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '389c3390-2361-44bc-a647-bfc78a8f94de','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='389c3390-2361-44bc-a647-bfc78a8f94de') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='389c3390-2361-44bc-a647-bfc78a8f94de');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '55accc3a-858b-423b-b8c3-cd955a86052c','Environmental sensitivity','Environmental sensitivity is a microphone''s susceptibility to non-acoustic influences such as temperature, humidity, wind, mechanical vibration, and electromagnetic or RF interference, which can shift its output, add noise, or damage it. Datasheets state operating ranges and effects such as the temperature coefficient of sensitivity.','Microphones react to more than sound. Heat, damp, wind, shaking, and radio interference all affect them. This is environmental sensitivity. Good practice and accessories keep these effects small.','It flags the non-sound factors a technician must manage to keep a microphone accurate and reliable.','Outdoors, a technician fits a windscreen and shockmount and lets a cold condenser warm up gradually to avoid condensation shorting the capsule.','Reliability',ARRAY['Diffuse-field response','Condenser capsule','Directional behavior','Digital microphone interface','Electret capsule']::text[],ARRAY['UNSAFE: Skipping wireless RF coordination and licensing, so mics drop out or interfere with licensed radio services.','Bringing a cold condenser straight into a warm, humid room and getting condensation crackle.','Forgetting a windscreen, so wind noise overloads the low end.']::text[],ARRAY['Outdoor location recording in wind and cold.','Coordinating wireless frequencies at a busy venue.','Protecting mics from stage vibration.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Environmental sensitivity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '55accc3a-858b-423b-b8c3-cd955a86052c','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='55accc3a-858b-423b-b8c3-cd955a86052c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='55accc3a-858b-423b-b8c3-cd955a86052c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8eb1bfbf-6fbc-48a3-a671-43e703c57a05','Equalization port','An equalization port is a small acoustic vent in a microphone capsule. A static pressure-equalization vent lets slow, static pressure changes even out across the diaphragm without touching audio-band response, while in a directional capsule a tuned rear acoustic port or labyrinth introduces the controlled delay that forms the polar pattern.','A tiny vent lets slow air-pressure changes even out across the diaphragm. Weather and altitude change static pressure. Without the vent, the diaphragm would sit off-center. In directional mics, a tuned rear port also shapes the pickup pattern.','It keeps static pressure balanced across the diaphragm and, in directional capsules, sets the acoustic delay that forms the polar pattern.','A technician avoids blocking a measurement mic''s tiny pressure-equalization vent, since sealing it would let temperature or altitude changes bias the diaphragm off center.','Capsule design',ARRAY['Condenser capsule','Directivity pattern','Differential-pressure microphone','Diaphragm resonance','Environmental sensitivity']::text[],ARRAY['Blocking or sealing the vent and then getting drift or an offset diaphragm.','Confusing the static pressure vent with the directional rear acoustic port.','Thinking the port equalizes audio-band frequency response like a tone control.']::text[],ARRAY['Handling a measurement microphone''s pressure vent.','Explaining how a cardioid''s rear port creates its pattern.','Diagnosing low-frequency drift or offset.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Equalization port');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8eb1bfbf-6fbc-48a3-a671-43e703c57a05','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8eb1bfbf-6fbc-48a3-a671-43e703c57a05') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8eb1bfbf-6fbc-48a3-a671-43e703c57a05');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c488428a-3185-49a3-bd33-6d113e64487e','Expanded uncertainty','Expanded uncertainty (U) defines an interval about a measurement result expected to contain a large fraction of the values that could reasonably be attributed to the measurand. Under the GUM (JCGM 100) it equals the combined standard uncertainty multiplied by a coverage factor, with a factor of about 2 giving roughly 95 percent coverage for a normal distribution.','Every measurement has doubt. Expanded uncertainty gives a range around the result. That range likely holds the true value. A coverage factor of two gives about 95 percent confidence.','It reports a measurement result with a stated confidence interval, as required for calibration and metrology.','If a mic-calibration combined standard uncertainty is uc=0.1 dB, then with k=2 the expanded uncertainty is U=2*0.1=0.2 dB, reported as the result plus or minus 0.2 dB (about 95 percent).','Metrology',ARRAY['Diffuse-field microphone','Environmental sensitivity','Condenser polarization','Directivity pattern','Coherence matrix']::text[],ARRAY['Reporting the combined standard uncertainty without stating the coverage factor k.','Assuming k=2 always means exactly 95 percent regardless of degrees of freedom.','Confusing expanded uncertainty with instrument tolerance or measurement error.']::text[],ARRAY['Reporting microphone calibration results.','Stating measurement confidence on a test certificate.','Comparing uncertainties between laboratories.']::text[],'advanced','U = k * uc','The expanded uncertainty equals the coverage factor times the combined standard uncertainty.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Expanded uncertainty');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c488428a-3185-49a3-bd33-6d113e64487e','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c488428a-3185-49a3-bd33-6d113e64487e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c488428a-3185-49a3-bd33-6d113e64487e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b138841b-7781-40d5-b693-b222113103f7','Figure-eight pattern','A bidirectional microphone polar pattern that is equally sensitive to sound arriving at the front (0 degrees) and the rear (180 degrees) but with opposite electrical polarity, and fully rejects sound arriving at the sides. Its directional sensitivity follows the cosine of the angle from the main axis.','This microphone hears sound from the front and the back the same. It ignores sound coming from either side. The two lobes look like the number eight. Ribbon and many condenser mics can use this pattern.','It lets a microphone capture two facing sources or reject sound from the sides, which is useful for interviews, blending, and stereo work.','An engineer aims the side null at a loud stage monitor so it is rejected; at 90 degrees the cosine term is zero, giving deep attenuation.','Polar Pattern',ARRAY['Figure-eight response','First-order gradient microphone','Front-to-back ratio','Hypercardioid pattern','Frequency-dependent polar response']::text[],ARRAY['UNSAFE: Applying 48 V phantom power to a passive ribbon figure-eight mic through a faulty cable or patch can burn out or stretch the ribbon.','Forgetting the rear lobe is out of polarity, which causes cancellation when summed with a front source.','Assuming the side nulls stay perfectly deep at all frequencies; they widen and shift with frequency.']::text[],ARRAY['Miking two singers who face each other across one bidirectional mic.','Setting a Blumlein stereo pair from two crossed figure-eight mics.','Rejecting a side wall reflection in a small room.']::text[],'beginner','S(theta) = cos(theta)','The relative sensitivity equals the cosine of the angle between the sound direction and the front axis.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Figure-eight pattern');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b138841b-7781-40d5-b693-b222113103f7','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b138841b-7781-40d5-b693-b222113103f7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b138841b-7781-40d5-b693-b222113103f7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ee949ca6-43db-40ac-a111-3253f190911d','Figure-eight response','The directional and frequency behavior of a pure pressure-gradient microphone, in which output varies as the cosine of the incidence angle and, being gradient based, rises with frequency and boosts low frequencies for near sources (proximity effect). It is the response that produces the bidirectional figure-eight pattern.','This describes how a pure gradient mic reacts to sound. Its output follows a cosine shape around the mic. Because it senses pressure difference, close sources gain extra bass. This bass rise is called proximity effect.','It explains why bidirectional and gradient microphones share a cosine directivity and a strong proximity bass boost, guiding placement and equalization choices.','A vocalist working close to a ribbon relies on figure-eight response for a warm, bass-heavy tone; backing off a few centimeters reduces the proximity boost.','Directional Response',ARRAY['Figure-eight pattern','First-order gradient microphone','Frequency-dependent polar response','Front-to-back ratio','Free-field response']::text[],ARRAY['UNSAFE: Sending phantom power to a passive ribbon that shows a figure-eight response can damage its delicate ribbon element.','Confusing the pattern shape with the underlying gradient frequency behavior that also causes proximity effect.','Expecting flat bass at all distances, when close placement lifts the low end.']::text[],ARRAY['Explaining why a ribbon gets boomy when a singer moves in close.','Analyzing why gradient mics need low-frequency compensation.','Comparing a gradient element against a pure pressure omni.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Figure-eight response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ee949ca6-43db-40ac-a111-3253f190911d','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ee949ca6-43db-40ac-a111-3253f190911d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ee949ca6-43db-40ac-a111-3253f190911d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5e8fff65-a4f8-4ff2-8d4b-408c9c4ad716','First-order gradient microphone','A microphone that responds to the first spatial derivative (gradient) of the sound-pressure field, so its output combines a pressure (omnidirectional) term and a pressure-gradient (figure-eight) term. All standard first-order patterns (omni, cardioid, supercardioid, hypercardioid, figure-eight) are weighted sums of these two terms.','This mic senses the change in air pressure across a short distance. Mixing this gradient part with a plain pressure part sets the pattern. Different mixes give cardioid, hypercardioid, or figure-eight. Almost all directional mics work this way.','It provides the physical basis for building directional microphones and for switching a single capsule among several first-order polar patterns.','An engineer selecting cardioid on a multipattern mic sets the weights to A=0.5 and B=0.5 in S(theta)=A+B cos(theta), giving a rear null at 180 degrees.','Microphone Design',ARRAY['Figure-eight pattern','Hypercardioid pattern','Higher-order microphone','Frequency-dependent polar response','Legendre polynomial']::text[],ARRAY['UNSAFE: Many first-order figure-eight capsules are passive ribbons; applying phantom power through a wiring fault can destroy the ribbon.','Believing the pattern is fixed, when it is set by the ratio of pressure to gradient terms.','Ignoring the proximity bass boost that the gradient term always adds up close.']::text[],ARRAY['Choosing a polar pattern on a switchable studio condenser.','Explaining how a single capsule yields several patterns.','Teaching why all first-order mics show proximity effect except pure omni.']::text[],'advanced','S(theta) = A + B*cos(theta),  A + B = 1','Relative sensitivity equals a pressure weight plus a gradient weight times the cosine of the angle, with the two weights summing to one.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='First-order gradient microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5e8fff65-a4f8-4ff2-8d4b-408c9c4ad716','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5e8fff65-a4f8-4ff2-8d4b-408c9c4ad716') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5e8fff65-a4f8-4ff2-8d4b-408c9c4ad716');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a9b71eb4-28cf-440b-8bc9-e3b3ad9e771f','Foil-electret microphone','An electret condenser microphone in which the permanently charged electret material is a thin polymer foil that also serves as the vibrating diaphragm. This diaphragm-electret design was the original electret capsule form, invented by Sessler and West at Bell Laboratories around 1962.','This is an electret mic whose diaphragm is the charged film itself. The film holds a permanent electric charge, so no polarizing voltage is needed. It was the first electret design. Cheaper phone and lapel mics still use it.','It removes the need for an external polarizing supply by storing charge in the diaphragm foil, enabling small, low-cost, battery-friendly microphones.','A technician recognizes a foil-electret lavalier by its need only for a small preamp bias, not a high polarizing voltage, and expects modest high-frequency extension.','Microphone Type',ARRAY['Front-electret microphone','Gold sputtering','Loaded sensitivity','Low-frequency microphone']::text[],ARRAY['Believing electret mics never need power; the built-in preamp still requires bias or plug-in power.','Assuming the charge lasts forever, when it can slowly leak over decades.','Confusing the foil (diaphragm) type with the higher-performing back-electret type.']::text[],ARRAY['Identifying the capsule inside a cheap lavalier or headset mic.','Explaining why an electret needs plug-in power for its preamp.','Comparing consumer electret capsules with studio condensers.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Foil-electret microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a9b71eb4-28cf-440b-8bc9-e3b3ad9e771f','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a9b71eb4-28cf-440b-8bc9-e3b3ad9e771f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a9b71eb4-28cf-440b-8bc9-e3b3ad9e771f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1853db93-d813-4bb6-a1e0-797ec15876c8','Free-field microphone','A measurement microphone whose frequency response is corrected so that, for sound arriving from a stated direction (usually 0 degrees, on axis), it reports the sound-pressure level that would exist in the undisturbed free field before the microphone was introduced. The correction offsets the pressure buildup at the diaphragm from the microphone''s own presence.','This measuring mic is tuned for sound coming straight at its front. Its body would normally raise the pressure at high frequencies. The design cancels that rise. So it reads the true level the room would have without the mic.','It provides accurate on-axis level measurements in anechoic or open conditions, where sound comes mainly from one direction, per IEC 61094 classifications.','A technician points a free-field microphone directly at a loudspeaker under test in an anechoic chamber and reads level without adding a high-frequency error.','Measurement Microphone',ARRAY['Free-field response','Half-inch measurement microphone','Frequency-dependent polar response','Pressure microphone','Magnitude sensitivity']::text[],ARRAY['Using a free-field microphone in a diffuse reverberant field, where a random-incidence type is correct.','Aiming it off axis and expecting the flat corrected response.','Confusing free-field type with pressure type used in couplers and on boundaries.']::text[],ARRAY['Measuring loudspeaker response in an anechoic chamber.','Outdoor on-axis sound level surveys.','Calibrating a microphone against a free-field standard.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Free-field microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1853db93-d813-4bb6-a1e0-797ec15876c8','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1853db93-d813-4bb6-a1e0-797ec15876c8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1853db93-d813-4bb6-a1e0-797ec15876c8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f14dc39a-efd8-4917-b83e-8b1727155b38','Free-field response','A microphone''s sensitivity as a function of frequency for a plane progressive sound wave arriving from a specified direction, usually 0 degrees, in a free (echo-free) sound field. It is the reference response used to specify and compare measurement and studio microphones.','This is how a mic''s output changes with frequency for on-axis sound. It is measured in a room with no echoes. Most datasheet response curves are free-field curves. They assume sound comes from the front.','It gives a standard, repeatable way to describe how evenly a microphone captures the audible band from its main direction.','An engineer reading a datasheet sees a free-field curve flat within plus or minus 2 dB from 20 Hz to 20 kHz and expects neutral on-axis capture.','Response Specification',ARRAY['Free-field microphone','Frequency-dependent polar response','Figure-eight response','Magnitude sensitivity','Half-inch measurement microphone']::text[],ARRAY['Assuming the free-field curve also describes off-axis sound, which follows the polar response.','Comparing a free-field curve to a pressure-response curve without noting the different field type.','Ignoring that the curve applies to 0 degrees incidence only.']::text[],ARRAY['Reading and comparing microphone datasheet response plots.','Verifying a measurement microphone against its calibration chart.','Choosing a mic with a flat on-axis response for critical recording.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Free-field response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f14dc39a-efd8-4917-b83e-8b1727155b38','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f14dc39a-efd8-4917-b83e-8b1727155b38') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f14dc39a-efd8-4917-b83e-8b1727155b38');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5ff2e3b2-34d5-49ee-812e-8284d35bb326','Frequency-dependent polar response','The tendency of a microphone''s polar (directional) pattern to change shape with frequency: most directional capsules become more omnidirectional at low frequencies and narrower or more irregular at high frequencies as the wavelength approaches the capsule size. Datasheets show this with several polar plots at different frequencies.','A mic''s pickup shape is not the same at every pitch. Low sounds are picked up more evenly around the mic. High sounds are captured in a narrower beam. Good datasheets show polar plots at several frequencies.','It warns technicians that a stated pattern is only nominal, so off-axis tone and rejection depend strongly on frequency and placement.','An engineer notices a cardioid rejects bass poorly off axis and repositions a bleeding drum, because the pattern is nearly omni below about 200 Hz.','Directivity',ARRAY['Figure-eight pattern','Hypercardioid pattern','First-order gradient microphone','Free-field response','Front-to-back ratio']::text[],ARRAY['Trusting a single polar plot as valid across the whole band.','Expecting the same off-axis rejection at 100 Hz as at 8 kHz.','Blaming the mic for off-axis coloration that is normal pattern change with frequency.']::text[],ARRAY['Reading multi-frequency polar plots when choosing a stage mic.','Troubleshooting bass leakage into a directional drum mic.','Explaining off-axis coloration of nearby instruments.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Frequency-dependent polar response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5ff2e3b2-34d5-49ee-812e-8284d35bb326','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5ff2e3b2-34d5-49ee-812e-8284d35bb326') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5ff2e3b2-34d5-49ee-812e-8284d35bb326');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '64955f8b-4510-4987-873f-5ccb7450b85a','Front-electret microphone','An electret condenser microphone in which the charged electret layer is on the front, moving diaphragm side of the capsule (as in the original foil-electret design), rather than on the fixed backplate. It contrasts with the back-electret design, which places the electret on the stationary backplate.','This electret mic keeps its charged layer on the moving diaphragm. That is the older, simpler design. The charged film adds mass, so it can limit high frequencies. Back-electret mics move the charge to the fixed plate instead.','It names the classic electret layout to distinguish it from the higher-performing back-electret construction used in better studio and instrument capsules.','A technician expects a front- or foil-electret consumer capsule to have more diaphragm mass and slightly softer highs than a comparable back-electret model.','Microphone Type',ARRAY['Foil-electret microphone','Gold sputtering','Loaded sensitivity','Low-frequency microphone','Magnitude sensitivity']::text[],ARRAY['Assuming front- and back-electret sound identical; diaphragm mass differs and affects highs.','Thinking front-electret means the mic points a certain way; it refers to charge placement.','Believing any electret is low quality, when back-electret capsules rival true condensers.']::text[],ARRAY['Comparing electret capsule constructions on a spec sheet.','Explaining why some electret mics sound duller up top.','Selecting between electret capsule types for an instrument mic.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Front-electret microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '64955f8b-4510-4987-873f-5ccb7450b85a','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='64955f8b-4510-4987-873f-5ccb7450b85a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='64955f8b-4510-4987-873f-5ccb7450b85a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fd3a67cd-8187-440d-b711-684f7caf951d','Front-to-back ratio','The ratio, expressed in decibels, of a directional microphone''s on-axis sensitivity (0 degrees) to its sensitivity at the rear (180 degrees). It quantifies how well the microphone rejects sound coming from directly behind it.','This number tells how much quieter the back is than the front. It is given in decibels. A big number means good rear rejection. A cardioid gives the largest number. Its null sits right at the back, at 180 degrees. Supercardioid and hypercardioid mics have a small rear lobe there. So they reject the back less than a cardioid does.','It helps predict rejection of a source or monitor placed behind the microphone, useful for stage and broadcast setups.','For a hypercardioid, rear sensitivity is about half of front, so the front-to-back ratio is 20*log10(1/0.5), about 6 dB.','Directivity Specification',ARRAY['Front-to-random ratio','Hypercardioid pattern','Figure-eight pattern','Half-power angle','Frequency-dependent polar response']::text[],ARRAY['Confusing front-to-back ratio with front-to-random ratio, which uses diffuse sound.','Assuming a supercardioid rejects 180 degrees better than a cardioid; the cardioid nulls at 180 degrees, while super/hypercardioid have a rear lobe there.','Expecting the rated ratio at all frequencies, when it varies with frequency.']::text[],ARRAY['Positioning a stage monitor behind a vocal mic for best rejection.','Comparing directional mics for feedback control.','Reading a microphone directivity specification.']::text[],'intermediate','FB_dB = 20*log10( S(0) / |S(180)| )','The front-to-back ratio in decibels equals twenty times the base-ten logarithm of front sensitivity divided by the magnitude of rear sensitivity.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Front-to-back ratio');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fd3a67cd-8187-440d-b711-684f7caf951d','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fd3a67cd-8187-440d-b711-684f7caf951d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fd3a67cd-8187-440d-b711-684f7caf951d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b35cd2ed-b307-4bf3-b5cf-67b17f113b1f','Front-to-random ratio','The ratio, in decibels, of a directional microphone''s on-axis output to its output for sound arriving equally from all directions (a random or diffuse field). It equals the reciprocal of the random energy efficiency and numerically matches the directivity index. The hypercardioid maximizes this ratio among first-order patterns.','This tells how much a mic favors front sound over scattered room sound. It is the reverse of random energy efficiency. A higher number means the mic hears more direct sound. The hypercardioid pattern gives the best value.','It predicts how much a directional microphone improves the direct-to-reverberant balance compared with an omnidirectional microphone.','A hypercardioid has random energy efficiency 0.25, so its front-to-random ratio (directivity index) is 10*log10(1/0.25) = 6.0 dB.','Directivity Specification',ARRAY['Front-to-back ratio','Hypercardioid pattern','Half-power angle','Frequency-dependent polar response','Figure-eight pattern']::text[],ARRAY['Mixing up front-to-random ratio (diffuse field) with front-to-back ratio (single rear direction).','Thinking the cardioid rejects reverberation best; the hypercardioid has the higher ratio.','Ignoring that the rating assumes an ideal frequency-independent pattern.']::text[],ARRAY['Choosing a mic to reduce room reverberation on a distant source.','Estimating reach and reverberant rejection for a lectern mic.','Comparing directivity index across polar patterns.']::text[],'advanced','DI = 10*log10( 1 / REE )','The front-to-random ratio in decibels equals ten times the base-ten logarithm of one divided by the random energy efficiency.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Front-to-random ratio');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b35cd2ed-b307-4bf3-b5cf-67b17f113b1f','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b35cd2ed-b307-4bf3-b5cf-67b17f113b1f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b35cd2ed-b307-4bf3-b5cf-67b17f113b1f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '27ed86eb-0b5c-43ab-83c6-bd3e457e41b0','Gold sputtering','A vacuum deposition process in which atoms of gold are ejected from a target by ion bombardment and settle as an extremely thin, electrically conductive layer on a polymer diaphragm film, typically polyester such as Mylar. In condenser microphones it makes the lightweight plastic diaphragm conductive so it can act as one plate of the capacitor.','This coats a plastic diaphragm with a very thin layer of gold. The gold is knocked off a target inside a vacuum. The coating makes the plastic film able to carry charge. This lets the film work as one capacitor plate.','It gives a condenser microphone a diaphragm that is both very light and electrically conductive, which supports wide, sensitive frequency response.','A technician handling a gold-sputtered capsule avoids touching the diaphragm, since fingerprints or scratches can break the thin conductive coating.','Manufacturing',ARRAY['Foil-electret microphone','Front-electret microphone','Half-inch measurement microphone','Loaded sensitivity','Magnitude sensitivity']::text[],ARRAY['Thinking the diaphragm is solid metal; it is thin plastic with a microscopic gold film.','Believing the gold layer adds meaningful mass; it is only nanometers thick.','Handling a capsule so the coating is scratched, degrading conductivity.']::text[],ARRAY['Servicing or cleaning a condenser capsule.','Explaining how a plastic diaphragm conducts charge.','Comparing metal versus gold-sputtered polymer diaphragms.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Gold sputtering');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '27ed86eb-0b5c-43ab-83c6-bd3e457e41b0','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='27ed86eb-0b5c-43ab-83c6-bd3e457e41b0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='27ed86eb-0b5c-43ab-83c6-bd3e457e41b0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a75e634c-bd6c-4293-a575-9d4f6fe63d26','Grating lobe','An unwanted secondary main lobe in the directional response of a microphone (or loudspeaker) array, caused by spatial aliasing when the spacing between array elements exceeds half a wavelength. Grating lobes give the array high sensitivity in directions other than the intended one.','An array of mics can form extra strong pickup directions. This happens when the mics sit too far apart for a given pitch. These extra beams are called grating lobes. They pick up sound you did not want.','The concept warns array designers to keep element spacing small enough to avoid false pickup or radiation directions at high frequencies.','With 20 mm element spacing, a grating lobe appears once the wavelength drops to about 20 mm, near 17 kHz, where sin(theta) reaches 1 at 90 degrees.','Array',ARRAY['Higher-order microphone','Interference tubes','Line-gradient microphone','Half-power angle','Legendre polynomial']::text[],ARRAY['Assuming more or wider-spaced elements always sharpen an array; wide spacing creates grating lobes.','Ignoring that grating lobes appear first at the highest frequencies.','Confusing a grating lobe with a normal side lobe; grating lobes match the main-lobe level.']::text[],ARRAY['Designing a microphone array for beamforming.','Explaining high-frequency artifacts in a line array.','Setting element spacing to keep grating lobes above the audio band.']::text[],'advanced','d*sin(theta_g) = m*lambda,  m = 1, 2, ...','A grating lobe occurs where element spacing times the sine of the lobe angle equals a whole number of wavelengths.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Grating lobe');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a75e634c-bd6c-4293-a575-9d4f6fe63d26','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a75e634c-bd6c-4293-a575-9d4f6fe63d26') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a75e634c-bd6c-4293-a575-9d4f6fe63d26');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cf346010-bcbd-491d-b360-ffa3ebddd3d8','Half-inch measurement microphone','A precision measurement condenser microphone cartridge with a nominal diameter of one half inch (about 12.7 mm), standardized under IEC 61094 as a working- or laboratory-standard type. Its size balances a useful sensitivity (commonly around 50 mV/Pa for free-field types) and low self-noise against an upper frequency limit typically in the low tens of kilohertz.','This is a lab-grade measuring mic about half an inch across. Its size is a good middle ground. It is sensitive and quiet, yet still reaches high frequencies. It follows the IEC 61094 measurement standard.','It is the general-purpose reference microphone for acoustic measurement, offering a practical trade-off among sensitivity, noise, and bandwidth.','An acoustician uses a half-inch free-field cartridge at about 50 mV/Pa for room and loudspeaker measurements, switching to a quarter-inch type only when higher frequencies are needed.','Measurement Microphone',ARRAY['Free-field microphone','Free-field response','Magnitude sensitivity','Loaded sensitivity','Gold sputtering']::text[],ARRAY['Assuming a bigger half-inch mic always beats a quarter-inch one; the smaller size reaches higher frequencies.','Ignoring the field type (free-field, pressure, random) needed for the measurement.','Treating the nominal half inch as the exact diaphragm diameter.']::text[],ARRAY['Measuring loudspeaker or room response.','Calibrating with a pistonphone or sound calibrator.','Selecting a cartridge size for a given frequency range.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Half-inch measurement microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cf346010-bcbd-491d-b360-ffa3ebddd3d8','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cf346010-bcbd-491d-b360-ffa3ebddd3d8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cf346010-bcbd-491d-b360-ffa3ebddd3d8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '475de581-7f0a-4616-a48b-f77b4c9e79b4','Half-power angle','The angle off the main axis at which a microphone''s output power falls to half its on-axis value, equal to a 3 dB drop in level. Twice the half-power angle gives the microphone''s beamwidth or coverage angle.','This is the angle where a mic''s power drops to half. Half power equals a 3 dB drop in level. Two times this angle gives the pickup width. It shows how wide the useful coverage is.','It gives a single figure for a microphone''s coverage angle, guiding how many microphones a stage or audience needs.','For a cardioid, sensitivity 0.5*(1+cos theta) falls to 0.707 at about 65.5 degrees, so its half-power angle is about 65 degrees and coverage about 131 degrees.','Directivity Specification',ARRAY['Front-to-back ratio','Front-to-random ratio','Hypercardioid pattern','Frequency-dependent polar response','Grating lobe']::text[],ARRAY['Confusing the half-power (3 dB) angle with the full null angle.','Forgetting that half power is 3 dB, not 6 dB, down.','Assuming coverage is fixed, when the half-power angle changes with frequency.']::text[],ARRAY['Estimating how many mics cover a choir or audience.','Reading a beamwidth figure from a polar plot.','Comparing coverage of cardioid and hypercardioid mics.']::text[],'intermediate','|S(theta_h)| = 0.707 * S(0)   (level -3 dB)','The half-power angle is where sensitivity drops to about 0.707 of the on-axis value, which is three decibels down.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Half-power angle');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '475de581-7f0a-4616-a48b-f77b4c9e79b4','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='475de581-7f0a-4616-a48b-f77b4c9e79b4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='475de581-7f0a-4616-a48b-f77b4c9e79b4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '45bcf6b9-fe06-4dc8-9ab9-4112077285b6','High-level microphone','A microphone designed to capture very high sound-pressure-level sources without distortion, featuring a high maximum SPL rating (often well above 140 dB SPL) and correspondingly low sensitivity. Such microphones are used close to loud sources like drums, brass, guitar amplifiers, and engines.','This mic is built for very loud sound sources. It can handle high pressure without distorting. To do this it has low sensitivity. Engineers use it close to drums, horns, or amps.','It lets a technician place a microphone right next to an extremely loud source and still get a clean, undistorted signal.','A technician chooses a high-SPL, low-sensitivity mic rated for 150 dB SPL at 1 percent distortion to close-mic a snare drum or trumpet bell.','Microphone Type',ARRAY['Inherent dynamic range','Loaded sensitivity','Magnitude sensitivity','Low-frequency microphone','Half-inch measurement microphone']::text[],ARRAY['UNSAFE: Working close to sources loud enough to need a high-level mic can exceed safe hearing exposure; wear hearing protection and limit time per OSHA and NIOSH limits.','Assuming low sensitivity means poor quality, when it is deliberate for high SPL.','Overloading a normal condenser on a loud source instead of using a high-SPL type.']::text[],ARRAY['Close-miking a snare or kick drum.','Capturing a loud brass or amplifier cabinet.','Measuring engine or machinery noise at close range.']::text[],'beginner',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='High-level microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '45bcf6b9-fe06-4dc8-9ab9-4112077285b6','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='45bcf6b9-fe06-4dc8-9ab9-4112077285b6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='45bcf6b9-fe06-4dc8-9ab9-4112077285b6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b8011bf5-2a69-4a2e-a41a-e26a716016cd','Higher-order microphone','A microphone whose directional response depends on second or higher spatial derivatives of the sound field, producing narrower and more selective patterns than a first-order microphone. Its directivity can be described by higher-order Legendre polynomials or spherical harmonics and is realized with multiple ports, capsules, or array processing.','This mic senses more than the simple pressure difference. It uses higher spatial detail of the sound field. That gives a tighter, more focused pickup. Building one needs extra ports, capsules, or signal processing.','It provides greater directivity and reach than first-order patterns, useful for pickup at distance or in noisy or reverberant spaces.','An engineer choosing a second-order gradient or beamforming array gains a higher directivity index than any first-order cardioid, at the cost of more noise or complexity.','Microphone Design',ARRAY['First-order gradient microphone','Legendre polynomial','Grating lobe','Line-gradient microphone','Interference tubes']::text[],ARRAY['Assuming higher order is always better; it often raises self-noise and low-frequency loss.','Confusing higher-order gradient designs with simple shotgun interference tubes.','Ignoring the added handling and wind sensitivity of gradient designs.']::text[],ARRAY['Selecting a highly directional mic for distant dialogue.','Designing a beamforming microphone array.','Explaining how directivity beyond cardioid is achieved.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Higher-order microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b8011bf5-2a69-4a2e-a41a-e26a716016cd','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b8011bf5-2a69-4a2e-a41a-e26a716016cd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b8011bf5-2a69-4a2e-a41a-e26a716016cd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '849e97f7-8237-4403-9d81-33e88d13e69e','Hypercardioid pattern','A first-order directional polar pattern whose sensitivity follows S(theta)=0.25+0.75 cos(theta), giving nulls near 110 and 250 degrees and a small rear lobe. It has the highest directivity index (about 6 dB) and best random rejection of the standard first-order patterns, at the cost of a stronger rear lobe than the supercardioid.','This directional pattern rejects the most scattered room sound. Its deepest nulls sit near 110 degrees off the front. It has a small pickup lobe at the back. It offers the tightest first-order reach.','It gives maximum reach and reverberant rejection among first-order patterns, favored for distant, noisy, or highly reflective pickup situations.','A boom operator aims the hypercardioid null (about 110 degrees) at a noise source and points the front lobe at the actor for maximum reach.','Polar Pattern',ARRAY['Figure-eight pattern','First-order gradient microphone','Front-to-random ratio','Front-to-back ratio','Half-power angle']::text[],ARRAY['Aiming the null at 180 degrees; the hypercardioid nulls are near 110 degrees, not the rear.','Forgetting the rear lobe, which can pick up sound directly behind.','Assuming it fully rejects the rear like a cardioid does.']::text[],ARRAY['Booming dialogue on a noisy set.','Placing a floor monitor at the null of a stage vocal mic.','Choosing a pattern for maximum reach in a reverberant hall.']::text[],'beginner','S(theta) = 0.25 + 0.75*cos(theta)','Relative sensitivity equals one quarter plus three quarters of the cosine of the angle from the front axis.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Hypercardioid pattern');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '849e97f7-8237-4403-9d81-33e88d13e69e','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='849e97f7-8237-4403-9d81-33e88d13e69e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='849e97f7-8237-4403-9d81-33e88d13e69e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a07bdc4d-d84b-4dce-9055-afb571161c25','I2S microphone','A digital microphone, usually a MEMS type, that outputs its audio as pulse-code-modulated data over the I2S (Inter-IC Sound) serial bus, a synchronous three-line interface (bit clock, word-select, and data) defined by Philips (now NXP). The microphone integrates the transducer, amplifier, and analog-to-digital conversion, so it delivers ready digital audio to a processor.','This tiny digital mic sends audio as data, not analog voltage. It uses the I2S bus, a standard chip-to-chip link. I2S needs three wires: a clock, a word select, and data. Philips, now NXP, created the I2S standard.','It lets a microphone connect directly to a microcontroller or DSP with a clean digital signal, avoiding analog noise pickup on the short run to the processor.','A developer wires a MEMS I2S mic''s bit-clock, word-select, and data lines to a microcontroller''s I2S port and reads left/right PCM samples directly.','Digital Microphone',ARRAY['Foil-electret microphone','Front-electret microphone','Magnitude sensitivity','Low-frequency microphone','Loaded sensitivity']::text[],ARRAY['Confusing I2S with PDM; PDM sends a one-bit stream that still needs a decimation filter.','Miswiring word-select so left and right channels swap or drop.','Assuming I2S is the same as the I2C control bus; they are different interfaces.']::text[],ARRAY['Adding a digital MEMS mic to an embedded audio board.','Interfacing a microphone directly with a DSP or microcontroller.','Explaining digital audio buses in small devices.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='I2S microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a07bdc4d-d84b-4dce-9055-afb571161c25','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a07bdc4d-d84b-4dce-9055-afb571161c25') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a07bdc4d-d84b-4dce-9055-afb571161c25');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b81a556a-5830-4b41-840a-79da64016833','Infrasonic microphone','A microphone or pressure sensor designed to capture infrasound, that is, sound below the roughly 20 Hz lower limit of normal human hearing, sometimes down to fractions of a hertz. It requires a sealed or specially vented pressure design with a very low high-pass corner, and is used in geophysics, meteorology, and nuclear-test monitoring.','This sensor captures sound below what people can hear. That range, under about 20 hertz, is called infrasound. It needs a design that responds to very slow pressure changes. Scientists use it to track storms, volcanoes, and explosions.','It extends measurement far below the audio band so very low-frequency pressure events can be recorded and analyzed.','A monitoring technician deploys an infrasonic sensor with wind-noise-reducing pipe arrays to detect distant explosions or severe weather below 20 Hz.','Microphone Type',ARRAY['Low-frequency microphone','Free-field microphone','Half-inch measurement microphone','Magnitude sensitivity','Loaded sensitivity']::text[],ARRAY['Expecting an ordinary studio mic to reach infrasound; its high-pass roll-off blocks it.','Ignoring huge wind-noise problems at very low frequencies.','Confusing infrasound (below hearing) with normal low bass in the audible band.']::text[],ARRAY['Monitoring for nuclear-test or explosion infrasound.','Measuring building or ventilation pressure fluctuations.','Recording volcanic or severe-weather infrasound.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Infrasonic microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b81a556a-5830-4b41-840a-79da64016833','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b81a556a-5830-4b41-840a-79da64016833') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b81a556a-5830-4b41-840a-79da64016833');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a5ceef0b-7ac5-4aa1-8b3d-09fc6006795f','Inherent dynamic range','The difference, in decibels, between a microphone''s maximum sound-pressure level (at a stated distortion limit) and its equivalent self-noise level (the A-weighted noise expressed as an SPL). It defines the span of levels the microphone itself can capture cleanly before either the noise floor or overload is reached.','This is the loudness range a mic can handle cleanly. The bottom is its own hiss, shown as a sound level. The top is the loudest sound before distortion. Subtract the two to get the range in decibels.','It tells the technician the total window of sound levels a microphone can reproduce without being masked by its noise or clipped by overload.','A mic with 134 dB SPL maximum and 14 dB(A) self-noise has an inherent dynamic range of 134 - 14 = 120 dB.','Noise Specification',ARRAY['High-level microphone','Loaded sensitivity','Magnitude sensitivity','Low-frequency microphone']::text[],ARRAY['Confusing the mic''s own dynamic range with the recording system''s range.','Comparing self-noise figures with different weightings as if equal.','Assuming a high maximum SPL alone means a wide dynamic range.']::text[],ARRAY['Choosing a mic for both quiet and loud passages.','Comparing datasheet noise and max-SPL numbers.','Explaining why very quiet sources need a low-noise mic.']::text[],'intermediate','DR = L_max - L_noise','Inherent dynamic range in decibels equals the maximum sound pressure level minus the equivalent self-noise level.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Inherent dynamic range');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a5ceef0b-7ac5-4aa1-8b3d-09fc6006795f','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a5ceef0b-7ac5-4aa1-8b3d-09fc6006795f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a5ceef0b-7ac5-4aa1-8b3d-09fc6006795f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b084c99c-8d79-46d4-9b30-8a9c1cd0db65','Integrated Circuit Piezoelectric','ICP is a trademark of PCB Piezotronics for its line of piezoelectric sensors and microphones that contain a built-in microelectronic amplifier and are powered over the same coaxial line by a constant-current source. The underlying generic method is the two-wire constant-current-powered piezoelectric sensor, known industry-wide as IEPE.','ICP is a brand name owned by PCB Piezotronics. Its sensors have a tiny amplifier built inside. One coax cable carries both power and the signal. A constant-current supply feeds the sensor. The generic version of this method is called IEPE.','It provides a low-impedance, cable-driving sensor output over a single coaxial line, simplifying wiring for vibration and high-SPL acoustic measurement.','A technician powers an ICP-brand microphone with a constant-current source, commonly around 2 to 20 mA, and reads the audio signal riding on a positive DC bias voltage.','Powering Interface',ARRAY['Integrated Electronics Piezo-Electric','Loaded sensitivity','High-level microphone','Magnitude sensitivity','Half-inch measurement microphone']::text[],ARRAY['Assuming ICP is a generic term; it is a PCB Piezotronics trademark for the IEPE method.','UNSAFE: Feeding 48 V phantom power instead of a proper constant-current source can damage an ICP or IEPE sensor''s built-in amplifier.','Forgetting the output rides on a DC bias that must be blocked before the next stage.']::text[],ARRAY['Connecting an ICP-brand measurement microphone to a data acquisition front end.','Selecting a constant-current supply for a piezo sensor.','Distinguishing brand names from the generic IEPE standard.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Integrated Circuit Piezoelectric');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b084c99c-8d79-46d4-9b30-8a9c1cd0db65','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b084c99c-8d79-46d4-9b30-8a9c1cd0db65') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b084c99c-8d79-46d4-9b30-8a9c1cd0db65');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a566e3db-0749-4f44-82cb-fb815efc0e28','Integrated Electronics Piezo-Electric','IEPE is the generic industry name for a two-wire sensor interface in which a piezoelectric transducer with a built-in impedance-converting amplifier is powered by a constant-current source (typically 2 to 20 mA at a compliance voltage up to about 24 to 30 V) and returns its signal on the same line as an AC voltage riding on a DC bias of roughly 8 to 14 V. Proprietary equivalents include ICP, CCLD, Isotron, DeltaTron, and Piezotron.','IEPE is the generic name for a common sensor powering scheme. A constant current feeds a sensor that has a small amplifier inside. The same two wires carry power and signal. The audio rides on a steady bias voltage. Brand names for it include ICP and CCLD.','It standardizes constant-current powering so sensors and signal conditioners from different makers work together over simple coaxial cable.','A technician sets a conditioner to supply about 4 mA constant current, then AC-couples the output to remove the roughly 8 to 14 V bias before the analyzer.','Powering Interface',ARRAY['Integrated Circuit Piezoelectric','Loaded sensitivity','High-level microphone','Magnitude sensitivity','Half-inch measurement microphone']::text[],ARRAY['UNSAFE: Connecting a 48 V phantom-power input to an IEPE sensor can damage its internal electronics; use a constant-current conditioner instead.','Forgetting to AC-couple the output, leaving the DC bias in the reading.','Setting the constant current outside the 2 to 20 mA range, harming performance or drive capability.']::text[],ARRAY['Configuring a signal conditioner for a piezo accelerometer or high-SPL mic.','Cabling IEPE sensors on long coaxial runs.','Matching a constant-current supply to a sensor''s rating.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Integrated Electronics Piezo-Electric');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a566e3db-0749-4f44-82cb-fb815efc0e28','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a566e3db-0749-4f44-82cb-fb815efc0e28') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a566e3db-0749-4f44-82cb-fb815efc0e28');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'be863f80-b435-47b4-b5e3-c17a32f5b40a','Interference tubes','A slotted acoustic tube mounted in front of a microphone capsule, as in a shotgun microphone, that increases high-frequency directivity by admitting off-axis sound through side slots at different path lengths so those components partly cancel at the capsule. On-axis sound reaches the capsule in phase and is unaffected.','This is a slotted tube in front of a shotgun mic capsule. Off-axis sound enters the slots at different distances. Those parts arrive out of step and cancel. Sound from straight ahead passes through cleanly. This narrows the high-frequency pickup.','It gives a compact microphone a much narrower high-frequency pickup than a bare capsule, useful for reaching a distant on-axis source amid noise.','A location sound mixer points an interference-tube (shotgun) mic at an actor so slot cancellation rejects off-axis crowd noise while keeping on-axis dialogue.','Shotgun Microphone',ARRAY['Interference-tube slot','Line-gradient microphone','Hypercardioid pattern','Higher-order microphone','Grating lobe']::text[],ARRAY['Assuming the tube tightens pickup at low frequencies; the effect works only where the tube is long relative to wavelength.','Believing a longer tube helps at all frequencies rather than mainly at highs.','Ignoring off-axis coloration the tube adds to sounds outside the front lobe.']::text[],ARRAY['Boom-miking dialogue outdoors.','Capturing on-field sports or wildlife sound at distance.','Explaining how a shotgun mic gains its narrow reach.']::text[],'beginner',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Interference tubes');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'be863f80-b435-47b4-b5e3-c17a32f5b40a','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='be863f80-b435-47b4-b5e3-c17a32f5b40a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='be863f80-b435-47b4-b5e3-c17a32f5b40a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c23fdd6d-738b-41c0-8e7e-5ea07bc27fc5','Interference-tube slot','One of the longitudinal openings (slots or ports) cut along the side of a shotgun microphone''s interference tube. Off-axis sound entering these slots travels different path lengths to the capsule and partly cancels, while on-axis sound remains in phase; slot length, spacing, and acoustic damping shape the microphone''s directivity and off-axis tone.','These are the long openings along a shotgun mic tube. Off-axis sound enters each slot at a different distance. The mismatched paths make that sound cancel. The slot pattern and damping set how tight and clean the pickup is.','The slots are the working part of an interference tube, creating the path-length differences that cancel off-axis sound and narrow the pattern.','A technician avoids covering the slots with tape or a tight cover, because blocking them destroys the cancellation and widens the pattern.','Shotgun Microphone',ARRAY['Interference tubes','Line-gradient microphone','Higher-order microphone','Hypercardioid pattern','Grating lobe']::text[],ARRAY['Blocking or taping over the slots, which ruins the interference cancellation.','Thinking the slots are vents for pressure equalization only.','Assuming all slots are identical; their length and damping are tuned along the tube.']::text[],ARRAY['Fitting a windshield without blocking the tube slots.','Cleaning or inspecting a shotgun microphone tube.','Explaining why slot design sets a shotgun''s directivity.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Interference-tube slot');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c23fdd6d-738b-41c0-8e7e-5ea07bc27fc5','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c23fdd6d-738b-41c0-8e7e-5ea07bc27fc5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c23fdd6d-738b-41c0-8e7e-5ea07bc27fc5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c7869d05-5c09-4e89-8adf-21d4cfb916b7','Legendre polynomial','A family of orthogonal polynomials, denoted P_n(cos theta), that arise as the angular solutions of the wave equation with axial symmetry and are used to describe the directivity of axisymmetric microphone patterns. First-order microphone patterns are combinations of P_0 (omni) and P_1 = cos theta (figure-eight); higher orders (for example P_2) describe more directional, higher-order microphones.','These are special math functions used to describe mic pickup shapes. The zero-order one is a constant, giving the omni shape. The first-order one is the cosine, giving the figure-eight. Combining them builds cardioid and other patterns. Higher orders give tighter shapes.','They provide the mathematical building blocks for expressing and combining microphone directivity patterns of any order.','An engineer writes a cardioid as a sum of P_0 and P_1: S(theta)=0.5*(P_0 + P_1)=0.5*(1+cos theta), giving a rear null.','Directivity Mathematics',ARRAY['First-order gradient microphone','Higher-order microphone','Figure-eight pattern','Hypercardioid pattern','Front-to-random ratio']::text[],ARRAY['Confusing Legendre polynomials with the spherical harmonics that include them plus an azimuth term.','Forgetting the argument is cos theta, not theta.','Assuming higher order automatically means better, ignoring noise and low-frequency loss.']::text[],ARRAY['Deriving microphone polar patterns mathematically.','Describing ambisonic or higher-order pickup.','Teaching the theory behind directional microphones.']::text[],'advanced','P_0=1, P_1=cos(theta), P_2=(3*cos^2(theta)-1)/2','The zero-order Legendre polynomial is one, the first-order is the cosine of the angle, and the second-order is three cosine-squared minus one over two.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Legendre polynomial');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c7869d05-5c09-4e89-8adf-21d4cfb916b7','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c7869d05-5c09-4e89-8adf-21d4cfb916b7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c7869d05-5c09-4e89-8adf-21d4cfb916b7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '548de399-fdc2-4100-bafe-37cfb430b693','Line-gradient microphone','A highly directional microphone that combines a line (interference-tube) element with a gradient (directional) capsule, so the interference tube sharpens the high-frequency pickup while the gradient capsule maintains directivity at lower frequencies. It is the classic construction of the shotgun or line-plus-gradient microphone.','This directional mic joins two tricks. An interference tube tightens the high frequencies. A gradient capsule keeps direction at lower frequencies. Together they give a shotgun mic its long, narrow reach. It is also called a line-plus-gradient mic.','It broadens the frequency range over which a shotgun microphone stays directional, combining the strengths of the tube and the gradient capsule.','A location mixer uses a line-gradient shotgun so the tube rejects off-axis highs while the hypercardioid-like capsule holds direction in the midrange and low end.','Shotgun Microphone',ARRAY['Interference tubes','Interference-tube slot','Hypercardioid pattern','Higher-order microphone','First-order gradient microphone']::text[],ARRAY['Thinking the interference tube alone provides all the directivity; the gradient capsule handles lower frequencies.','Expecting narrow pickup at low frequencies where the tube is short relative to wavelength.','Confusing a line-gradient shotgun with a simple omni-plus-tube design.']::text[],ARRAY['Choosing a shotgun mic for film dialogue.','Explaining how shotguns stay directional across the band.','Comparing interference-tube and pure gradient directional mics.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Line-gradient microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '548de399-fdc2-4100-bafe-37cfb430b693','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='548de399-fdc2-4100-bafe-37cfb430b693') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='548de399-fdc2-4100-bafe-37cfb430b693');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cdb0f596-0153-40a4-bbea-c6a535df7159','Loaded sensitivity','A microphone''s output voltage per unit sound pressure when its output is connected to a specified electrical load impedance, rather than measured open-circuit (unloaded). Because the load and the microphone''s source impedance form a voltage divider, loaded sensitivity is always lower than the open-circuit sensitivity.','This is a mic''s output level when a real load is connected. The load and the mic''s own resistance share the signal voltage. So the loaded value is lower than the open-circuit value. Datasheets usually list the open-circuit figure.','It tells the technician the actual signal a microphone delivers into a specific preamp input, which matters for gain staging and matching.','An open-circuit sensitivity of 20 mV/Pa into a load equal to the source impedance drops to about 10 mV/Pa, a 6 dB loss, by the voltage-divider rule.','Sensitivity Specification',ARRAY['Magnitude sensitivity','Free-field response','Half-inch measurement microphone','High-level microphone','Inherent dynamic range']::text[],ARRAY['Confusing loaded sensitivity with the higher open-circuit value usually quoted on datasheets.','Loading a mic with too low an input impedance and losing level and low end.','Assuming the load has no effect on delivered signal or frequency response.']::text[],ARRAY['Matching a microphone to a preamp input impedance.','Predicting signal level into a given load.','Explaining why measured level is below the datasheet figure.']::text[],'advanced','M_loaded = M_oc * ( R_L / (R_L + R_out) )','Loaded sensitivity equals the open-circuit sensitivity times the load impedance divided by the sum of the load and the microphone''s output impedance.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Loaded sensitivity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cdb0f596-0153-40a4-bbea-c6a535df7159','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cdb0f596-0153-40a4-bbea-c6a535df7159') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cdb0f596-0153-40a4-bbea-c6a535df7159');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1b532048-6f74-46bc-8bff-00a36a2f4e54','Low-frequency microphone','A microphone optimized to capture very low frequencies, extending its usable response well below the typical audio lower limit and sometimes into the infrasonic region. It uses a sealed or long-time-constant pressure design so its high-pass roll-off sits far lower than that of a general-purpose microphone.','This mic is tuned for very deep, low sounds. Its response reaches lower than a normal mic. It uses a sealed pressure design to hold low bass. Some types even reach below human hearing.','It provides accurate capture of deep bass and sub-audio pressure changes that ordinary microphones roll off and lose.','A measurement technician selects a low-frequency pressure microphone to capture HVAC or subwoofer output flat down to a few hertz.','Microphone Type',ARRAY['Infrasonic microphone','Free-field microphone','Half-inch measurement microphone','Loaded sensitivity','Magnitude sensitivity']::text[],ARRAY['Expecting an ordinary vocal mic to capture deep sub-bass; its high-pass filter blocks it.','Confusing extended low-frequency response with simply boosting bass in equalization.','Ignoring wind and handling noise, which are severe at low frequencies.']::text[],ARRAY['Measuring subwoofer or room low-frequency response.','Capturing building pressure or ventilation noise.','Recording very deep bass instruments accurately.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Low-frequency microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1b532048-6f74-46bc-8bff-00a36a2f4e54','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1b532048-6f74-46bc-8bff-00a36a2f4e54') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1b532048-6f74-46bc-8bff-00a36a2f4e54');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2d1c2c9f-e2f3-4257-a42c-fc0aee16526d','Magnetostrictive sensing','A transduction method that uses magnetostriction, the change in dimensions or magnetic state of a ferromagnetic material under mechanical stress, to convert acoustic or vibration input into an electrical signal. It was applied in some early telephone and pressure transducers but is uncommon in modern audio microphones, where moving-coil, condenser, and ribbon methods dominate.','This method uses magnetic metals that change shape under stress. That change alters a magnetic field and makes a signal. It appeared in some early telephone and pressure devices. Modern audio mics rarely use it today.','It offers a rugged way to convert mechanical stress into an electrical signal, though it is now largely historical for microphones and more common in sonar and industrial sensors.','A technician studying transducer history recognizes magnetostrictive elements in older or industrial pressure sensors rather than in standard studio microphones.','Transduction',ARRAY['Magnitude sensitivity','Loaded sensitivity','First-order gradient microphone','Low-frequency microphone','Infrasonic microphone']::text[],ARRAY['Confusing magnetostrictive sensing with the piezoelectric effect; one uses magnetism, the other uses charge.','Assuming it is common in modern audio microphones, which it is not.','Mixing it up with the moving-coil (dynamic) magnetic method.']::text[],ARRAY['Studying the history of transducer methods.','Identifying an unusual industrial or sonar sensor.','Comparing magnetic, piezoelectric, and condenser transduction.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Magnetostrictive sensing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2d1c2c9f-e2f3-4257-a42c-fc0aee16526d','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2d1c2c9f-e2f3-4257-a42c-fc0aee16526d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2d1c2c9f-e2f3-4257-a42c-fc0aee16526d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2d5a29b8-db8a-437a-bc81-b6a4c14f7902','Magnitude sensitivity','The magnitude (absolute value) of a microphone''s complex sensitivity, that is, the output voltage per unit sound pressure at a given frequency, expressed without its phase. It is commonly stated in millivolts per pascal or as a level in decibels relative to 1 V/Pa, and forms the amplitude part of the frequency-response curve.','This is how much voltage a mic gives per unit of sound pressure. It uses only the size of the response, not its timing. It is shown in millivolts per pascal or in decibels. It is the height of the response curve.','It states how strong a microphone''s output is for a given sound level, the amplitude side of sensitivity used for gain setting and comparison.','A microphone rated 12.6 mV/Pa has a sensitivity level of 20*log10(0.0126/1) = about -38 dB re 1 V/Pa.','Sensitivity Specification',ARRAY['Loaded sensitivity','Free-field response','Inherent dynamic range','Half-inch measurement microphone','Low-frequency microphone']::text[],ARRAY['Confusing magnitude sensitivity with complex sensitivity, which also carries phase.','Mixing up the millivolt-per-pascal figure with the negative decibel level.','Forgetting that sensitivity is normally specified at 1 kHz.']::text[],ARRAY['Comparing microphone output levels on datasheets.','Setting preamp gain from a sensitivity figure.','Converting between mV/Pa and dB re 1 V/Pa.']::text[],'advanced','L_M = 20*log10( M / M_ref ),  M_ref = 1 V/Pa','The sensitivity level in decibels equals twenty times the base-ten logarithm of the sensitivity divided by the reference of one volt per pascal.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Magnitude sensitivity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2d5a29b8-db8a-437a-bc81-b6a4c14f7902','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2d5a29b8-db8a-437a-bc81-b6a4c14f7902') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2d5a29b8-db8a-437a-bc81-b6a4c14f7902');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6ca24880-4970-4088-8ac4-a7f5ff4bd1fc','Main lobe','In a directional microphone or microphone-array response, the main lobe is the region of the polar or beam pattern that points toward the direction of greatest sensitivity. Its angular width, often quoted at the minus 3 dB or minus 6 dB points, sets how tightly the microphone or array focuses on wanted sound.','A directional mic hears best in one direction. The main lobe is that loudest zone on its pickup map. A narrow main lobe means the mic is very focused. A wide one picks up a broader area.','It describes where a directional mic or array is most sensitive, so engineers can aim it at the source and judge off-axis rejection.','Aiming a shotgun mic, an engineer points the main lobe at the actor''s mouth; a minus 6 dB beamwidth near 40 degrees means sources beyond about 20 degrees off-axis drop noticeably.','Directivity',ARRAY['Polar patterns','Null angle','Null depth','Polar narrowing','Minimum-variance distortionless response']::text[],ARRAY['Confusing the main lobe with the entire polar pattern, ignoring side lobes and rear pickup.','Assuming the main-lobe width stays constant with frequency; it usually narrows at high frequencies.','Thinking a narrower main lobe always sounds better, when it can also color off-axis tone.']::text[],ARRAY['Aiming a shotgun microphone at a talker on a film set.','Steering a beamforming ceiling array toward a conference table.','Reading a microphone''s polar plot to judge focus and rejection.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Main lobe');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6ca24880-4970-4088-8ac4-a7f5ff4bd1fc','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6ca24880-4970-4088-8ac4-a7f5ff4bd1fc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6ca24880-4970-4088-8ac4-a7f5ff4bd1fc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bd998c4b-3f28-4044-b717-f150e4bd6ff2','Maximum undistorted output','The highest output a microphone can deliver before its distortion, usually total harmonic distortion, exceeds a stated limit such as 0.5 percent or 1 percent. It corresponds to the maximum sound pressure level the microphone handles cleanly and, with sensitivity, sets the top of its dynamic range.','Every mic has a loudest sound it can handle cleanly. Past that point the signal starts to distort. This limit is often set where distortion reaches half a percent or one percent. Above it, the sound gets crunchy.','It tells the technician how loud a source the microphone can capture cleanly, marking the upper edge of its usable dynamic range.','Miking a snare that peaks near 150 dB SPL, an engineer checks that the mic''s rated max SPL at 1 percent THD, say 152 dB, exceeds those peaks to avoid distortion.','Specifications',ARRAY['Maximum sound pressure level','Open-circuit sensitivity','Dynamic range','Total harmonic distortion','Microphone preamplifier noise']::text[],ARRAY['Ignoring which THD percentage the max-output figure assumes, which makes specs look better or worse than they are.','Confusing the microphone''s own overload with preamp or converter clipping downstream.','Assuming a pad lowers distortion inside the capsule; it only protects the following electronics.']::text[],ARRAY['Choosing a mic for very loud drums or brass.','Comparing datasheet max-SPL numbers between condensers.','Diagnosing distortion to find whether the capsule or preamp overloaded.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Maximum undistorted output');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bd998c4b-3f28-4044-b717-f150e4bd6ff2','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bd998c4b-3f28-4044-b717-f150e4bd6ff2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bd998c4b-3f28-4044-b717-f150e4bd6ff2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ef324f3b-0cda-43e3-ba59-1ceadcb79265','Membrane','The thin, flexible diaphragm of a microphone that moves in response to sound-pressure variations, converting acoustic energy into mechanical motion for the transducer. Its mass, tension, and size strongly influence sensitivity, frequency response, and self-noise.','A membrane is the thin skin inside a mic that vibrates with sound. It is also called the diaphragm. Its size and tightness shape how the mic sounds. A light, thin membrane reacts quickly to sound.','It is the first moving part of a microphone, turning air-pressure changes into motion that the transducer converts to an electrical signal.','Choosing between large- and small-diaphragm condensers, an engineer picks the larger membrane for a warm vocal and the smaller for accurate high-frequency detail.','Components',ARRAY['Diaphragm','Membrane tension','Condenser microphone','Piezoelectric transduction','Package cavity']::text[],ARRAY['Assuming a bigger membrane is always better; it trades off high-frequency accuracy and off-axis response.','Touching or blowing directly on the diaphragm, which can stretch or damage it.','Confusing membrane diameter with the overall microphone body size.']::text[],ARRAY['Selecting a large- or small-diaphragm mic for a session.','Explaining why thin diaphragms give better high-frequency response.','Handling a capsule during cleaning or repair.']::text[],'beginner',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Membrane');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ef324f3b-0cda-43e3-ba59-1ceadcb79265','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ef324f3b-0cda-43e3-ba59-1ceadcb79265') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ef324f3b-0cda-43e3-ba59-1ceadcb79265');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e7c5503c-3beb-4d72-9130-84e404e80e53','Microelectromechanical microphone','A microphone whose pressure-sensing diaphragm and back-plate are fabricated on a silicon chip using microelectromechanical-systems (MEMS) processing, usually with an integrated amplifier in the same package. Most are capacitive (condenser) sensors, widely used in phones, laptops, and array products for their small size and unit-to-unit consistency.','A MEMS microphone is a tiny mic built on a silicon chip. MEMS stands for microelectromechanical systems. It puts the diaphragm and electronics in one small package. Phones, laptops, and mic arrays use them.','It provides a very small, stable, mass-producible microphone whose tight tolerances make it ideal for arrays and portable devices.','Designing a beamforming conference bar, an engineer uses matched MEMS mics because their tight sensitivity and phase tolerances keep the array''s nulls deep.','Microphone Types',ARRAY['Package cavity','Package leakage','Piezoresistive transduction','Phase matching','Condenser microphone']::text[],ARRAY['Assuming MEMS mics are always digital; many are analog and need an external codec.','Overlooking their limited maximum SPL compared with large studio capsules.','Damaging the diaphragm by soldering the mic outside its rated reflow profile.']::text[],ARRAY['Building a microphone array for voice pickup.','Specifying mics for a smart speaker or laptop.','Comparing analog versus digital MEMS parts for a design.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Microelectromechanical microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e7c5503c-3beb-4d72-9130-84e404e80e53','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e7c5503c-3beb-4d72-9130-84e404e80e53') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e7c5503c-3beb-4d72-9130-84e404e80e53');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1c763b0f-4b69-49e1-a22e-277e3e485dc7','Microphone preamplifier noise','The electronic noise a microphone preamplifier adds, usually specified as equivalent input noise (EIN): the input-referred noise voltage over a stated bandwidth and source impedance. Its lower bound is the thermal (Johnson) noise of the source resistance, about minus 131 dBu for a 150 ohm source across a 20 kHz bandwidth near room temperature.','A mic preamp adds its own faint hiss to the signal. This is measured as equivalent input noise, or EIN. The best it can do is set by heat noise in the source. Real preamps sit a couple of decibels above that limit.','It sets the electronic noise floor of a microphone channel and, with the mic''s own self-noise, limits how quiet a source can be recorded cleanly.','For a 150 ohm source over 20 kHz near 293 K, the thermal floor is about 0.22 microvolts, near minus 131 dBu; a preamp rated minus 129 dBu EIN adds only about 2 dB.','Noise',ARRAY['Equivalent input noise','Johnson noise','A-weighted self-noise','Dynamic range','Open-circuit sensitivity']::text[],ARRAY['Comparing EIN specs measured with different source impedances or bandwidths.','Blaming the preamp for hiss that is really the microphone''s own self-noise.','Forgetting that low gain settings can worsen the system''s effective input noise.']::text[],ARRAY['Recording a quiet source with a low-output ribbon mic.','Comparing preamp datasheets for a low-noise application.','Setting gain structure to keep the noise floor low.']::text[],'advanced','e_n = sqrt(4 k_B T R B)','The thermal noise voltage equals the square root of four times Boltzmann''s constant, absolute temperature, source resistance, and bandwidth.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Microphone preamplifier noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1c763b0f-4b69-49e1-a22e-277e3e485dc7','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1c763b0f-4b69-49e1-a22e-277e3e485dc7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1c763b0f-4b69-49e1-a22e-277e3e485dc7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8768aa78-5d8f-43f1-bf62-a3cad26cdf42','Mid/side recording','A stereo microphone technique using a forward-facing mid microphone (any pattern, often cardioid) and a sideways-facing figure-eight side microphone at the same point. The two are matrixed into left and right as L = M + S and R = M - S, letting stereo width be set after recording while summing cleanly to mono.','Mid/side, or M/S, is a stereo miking trick. One mic faces forward for the center sound. A figure-eight mic faces sideways for the width. Mixing them lets you change the stereo width later.','It captures a stereo image from one point and lets the engineer set width after the fact, while folding to mono cleanly.','Recording a soloist with M/S, the engineer raises the side mic level to widen the room, then checks mono to confirm the vocal stays solid.','Stereo Techniques',ARRAY['Near-coincident arrays','Figure-eight pattern','Coincident pair','Stereo width','Phase interaction between microphones']::text[],ARRAY['Forgetting the side channel must be split and polarity-inverted to form left and right.','Reversing the side mic, which swaps the stereo image left for right.','Assuming more side level is always better; too much harms mono compatibility.']::text[],ARRAY['Recording a soloist or ensemble with adjustable width.','Capturing broadcast sound that must fold to mono.','Reworking stereo width in the mix after tracking.']::text[],'intermediate','L = M + S ;  R = M - S','The left channel equals mid plus side; the right channel equals mid minus side.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mid/side recording');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8768aa78-5d8f-43f1-bf62-a3cad26cdf42','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8768aa78-5d8f-43f1-bf62-a3cad26cdf42') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8768aa78-5d8f-43f1-bf62-a3cad26cdf42');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '21a84ebc-7d85-4320-b31e-1b3ff6be17df','Minimum-variance distortionless response','An adaptive array beamforming method that minimizes total output power while keeping unity gain in the desired look direction, thereby suppressing interference and noise from other directions. The optimal weight vector is w = inverse(R) a divided by (a^H inverse(R) a), where R is the input covariance matrix and a the steering vector; it is also called the Capon beamformer.','MVDR is a smart way to combine many mic signals. It keeps the wanted direction at full strength. At the same time it lowers noise from other directions. Engineers also call it the Capon beamformer.','It forms a data-adaptive beam that passes the target direction untouched while placing nulls on interference, improving speech pickup in noise.','In a conference mic array, MVDR holds unity gain on the talker and drops a projector fan about 15 dB by adapting weights from the measured covariance.','Array Processing',ARRAY['Multiple signal classification','Main lobe','Null depth','Phase matching','Steering vector']::text[],ARRAY['Using a covariance matrix that contains the target signal, which can cancel the wanted source (self-nulling).','Forgetting MVDR needs enough data snapshots to estimate the covariance reliably.','Assuming it works without accurate steering-vector or array-geometry information.']::text[],ARRAY['Enhancing a talker in a noisy conference room.','Beamforming a microphone array for far-field voice.','Comparing fixed versus adaptive beamformers.']::text[],'advanced','w = R^{-1} a / (a^H R^{-1} a)','The weight vector equals the inverse covariance matrix times the steering vector, divided by the steering vector''s Hermitian product with that same result.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Minimum-variance distortionless response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '21a84ebc-7d85-4320-b31e-1b3ff6be17df','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='21a84ebc-7d85-4320-b31e-1b3ff6be17df') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='21a84ebc-7d85-4320-b31e-1b3ff6be17df');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '55824736-79b1-4f85-a3a5-e69c7d2cba3c','Multiple signal classification','A high-resolution subspace method for estimating the directions of arrival of multiple sources from an array''s covariance matrix. It splits the eigenvectors into signal and noise subspaces and forms a pseudospectrum that peaks sharply where the steering vector is orthogonal to the noise subspace, resolving sources closer than the array''s natural beamwidth.','Multiple Signal Classification (MUSIC) finds which directions sounds come from using a mic array. It sorts the array data into signal and noise parts. Where a test direction matches a real source, a sharp peak appears. It can separate sources that sit close together.','It locates several sound sources at once with resolution finer than conventional beamforming, useful for direction-of-arrival estimation.','With a small array, MUSIC resolves two talkers only 8 degrees apart by finding the two sharp peaks in its pseudospectrum.','Array Processing',ARRAY['Minimum-variance distortionless response','Phase-transform weighting','Main lobe','Null angle','Steering vector']::text[],ARRAY['Feeding it the wrong number of sources, which mislabels the signal and noise subspaces.','Expecting accuracy with coherent (correlated) sources without extra spatial smoothing.','Assuming its sharp peaks mean high SNR; the pseudospectrum is not a true power spectrum.']::text[],ARRAY['Locating multiple talkers or noise sources with an array.','Acoustic direction-of-arrival research.','Comparing resolution against conventional beamforming.']::text[],'advanced','P(theta) = 1 / (a(theta)^H E_n E_n^H a(theta))','The pseudospectrum equals one divided by the squared projection of the steering vector onto the noise subspace.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Multiple signal classification');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '55824736-79b1-4f85-a3a5-e69c7d2cba3c','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='55824736-79b1-4f85-a3a5-e69c7d2cba3c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='55824736-79b1-4f85-a3a5-e69c7d2cba3c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '32227708-6d68-47ca-ac10-851fc4e52c0a','Near-coincident arrays','Stereo microphone techniques that place two capsules a small distance apart (typically 15 to 30 cm) and angled outward, combining level and arrival-time differences to build the stereo image. Common examples are ORTF (two cardioids 17 cm apart at plus/minus 110 degrees), NOS (30 cm at 90 degrees), and DIN (20 cm at 90 degrees).','These stereo setups put two mics a short distance apart and angled out. They use both loudness and slight timing differences between the mics. ORTF, NOS, and DIN are common versions. Each has its own spacing and angle.','They give a wider, more spacious stereo image than a coincident pair while keeping reasonable mono compatibility.','Recording a choir with ORTF, the engineer spaces two cardioids 17 cm apart at plus/minus 110 degrees so the group spreads naturally across the stereo field.','Stereo Techniques',ARRAY['Mid/side recording','Coincident pair','Phase interaction between microphones','Spaced pair','Stereo width']::text[],ARRAY['Mixing up the spacing and angle values for ORTF, NOS, and DIN.','Ignoring reduced mono compatibility caused by the time differences between capsules.','Assuming any two spaced mics count as a defined near-coincident standard.']::text[],ARRAY['Recording an ensemble or room in stereo.','Choosing ORTF versus a spaced pair on location.','Teaching stereo imaging fundamentals.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Near-coincident arrays');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '32227708-6d68-47ca-ac10-851fc4e52c0a','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='32227708-6d68-47ca-ac10-851fc4e52c0a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='32227708-6d68-47ca-ac10-851fc4e52c0a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7e3c67ac-b3cc-4fe6-bc86-6d96cb160e2a','Noncontact vibration measurement','Measurement of a surface''s vibration without touching it, most commonly by laser Doppler vibrometry, which detects the Doppler frequency shift of laser light reflected from the moving surface to recover its velocity. It avoids the mass-loading and access limits of contact accelerometers and can also act as an optical microphone by sensing sound-induced surface motion.','This measures how something vibrates without touching it. A common way aims a laser at the surface. Motion shifts the laser light''s frequency, which reveals the speed. It avoids adding weight to light or delicate parts.','It captures vibration or sound from surfaces that are hot, light, rotating, or hard to reach, where a contact sensor would disturb or cannot mount.','A technician uses a laser Doppler vibrometer to map a loudspeaker cone''s breakup modes without gluing on an accelerometer that would change its mass.','Measurement',ARRAY['Optical microphone','Particle-velocity sensor','Membrane','Piezoelectric transduction','Nonreciprocal transducer']::text[],ARRAY['Assuming the laser measures displacement directly; a vibrometer senses velocity via Doppler shift.','Ignoring surface reflectivity, which can weaken the return signal.','Confusing it with an acoustic microphone, though it can serve as an optical mic.']::text[],ARRAY['Mapping loudspeaker cone or panel vibration modes.','Measuring vibration on hot or rotating machinery.','Noncontact sound capture research.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Noncontact vibration measurement');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7e3c67ac-b3cc-4fe6-bc86-6d96cb160e2a','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7e3c67ac-b3cc-4fe6-bc86-6d96cb160e2a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7e3c67ac-b3cc-4fe6-bc86-6d96cb160e2a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '01f9dc4c-ac3c-4535-9492-334f40603b53','Nonreciprocal transducer','A transducer whose forward (sound-to-electrical) and reverse (electrical-to-sound) sensitivities are not linked by the reciprocity relationship that holds for passive linear electroacoustic devices. Because reciprocity calibration relies on that relationship, nonreciprocal transducers, such as those with active amplification or nonlinear elements, cannot serve as reciprocal calibration standards.','Many transducers work both ways: as a mic and as a tiny speaker. For simple passive ones, these two roles follow a fixed rule. A nonreciprocal transducer breaks that link. This usually happens when active or nonlinear parts are inside.','The label matters for calibration, since the reciprocity method for absolute microphone calibration only works with truly reciprocal, passive transducers.','Calibrating lab microphones by reciprocity, a technician selects passive condenser capsules and avoids amplified capsules, which behave nonreciprocally.','Transducer Theory',ARRAY['Piezoelectric transduction','Open-circuit sensitivity','One-inch measurement microphone','Membrane','Optical microphone']::text[],ARRAY['Assuming every microphone can serve as a reciprocity calibration standard.','Confusing nonreciprocal with simply nonlinear; the ideas overlap but are not identical.','Overlooking that a built-in preamplifier breaks passive reciprocity.']::text[],ARRAY['Selecting standard mics for reciprocity calibration.','Understanding limits of primary microphone calibration.','Distinguishing passive from active capsule behavior.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Nonreciprocal transducer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '01f9dc4c-ac3c-4535-9492-334f40603b53','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='01f9dc4c-ac3c-4535-9492-334f40603b53') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='01f9dc4c-ac3c-4535-9492-334f40603b53');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '694486b0-509f-4a26-bf79-a5172419e3de','Null angle','The direction, relative to a microphone''s axis, at which its sensitivity falls to a minimum (ideally zero) in the polar pattern. For an ideal cardioid the null is at 180 degrees (directly to the rear); for a figure-eight the nulls are at plus/minus 90 degrees (the sides).','A directional mic has a deaf direction. The null angle is where it picks up the least sound. A cardioid''s null is directly behind it. A figure-eight mic has nulls on its two sides.','It lets an engineer aim a mic''s weakest direction at unwanted sound, such as a monitor wedge or a competing instrument.','To fight feedback, an engineer points a cardioid vocal mic''s 180-degree null at the floor monitor so the wedge is rejected.','Directivity',ARRAY['Null depth','Main lobe','Polar patterns','Omnidirectional behavior','Phase sensitivity']::text[],ARRAY['Assuming the null gives infinite rejection; real nulls are finite and change with frequency.','Forgetting a cardioid rejects the rear, not the sides.','Placing a monitor at the null angle but off the mic''s plane, which weakens the rejection.']::text[],ARRAY['Positioning monitors to avoid feedback on stage.','Aiming a figure-eight null at a leaking instrument.','Reading polar plots to plan placement.']::text[],'beginner',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Null angle');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '694486b0-509f-4a26-bf79-a5172419e3de','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='694486b0-509f-4a26-bf79-a5172419e3de') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='694486b0-509f-4a26-bf79-a5172419e3de');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4dfb3e2e-edb3-4273-b6ba-455c4130b984','Null depth','The amount by which a microphone or array''s sensitivity is reduced at its null direction relative to the on-axis (main-lobe) response, expressed in decibels. Deeper nulls give stronger rejection of unwanted directions but are limited by capsule tolerances, frequency, and array errors.','A mic''s null is its quietest direction. Null depth says how deep that quiet spot is. It compares the null level to the front level in decibels. A deeper null rejects unwanted sound more strongly.','It quantifies how well a mic or beamformer rejects sound from its null direction, which governs feedback and interference control.','A beamformer with a minus 25 dB null on a noise source cuts that noise to about one-eighteenth of its on-axis voltage level.','Directivity',ARRAY['Null angle','Main lobe','Minimum-variance distortionless response','Phase matching','Polar patterns']::text[],ARRAY['Expecting deep nulls across all frequencies; depth degrades away from the design band.','Ignoring how capsule mismatch in arrays fills in the null.','Confusing null depth with front-to-back ratio, which is a single averaged figure.']::text[],ARRAY['Specifying array performance for noise rejection.','Measuring a cardioid''s rear rejection.','Tuning a beamformer''s interference suppression.']::text[],'advanced','Null depth (dB) = 20 log10( |H(theta_null)| / |H(theta_0)| )','Null depth in decibels is twenty times the log of the null response divided by the on-axis response.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Null depth');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4dfb3e2e-edb3-4273-b6ba-455c4130b984','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4dfb3e2e-edb3-4273-b6ba-455c4130b984') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4dfb3e2e-edb3-4273-b6ba-455c4130b984');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2a469310-a2a8-47d2-9418-282089902d2f','Omnidirectional behavior','The property of a microphone that responds nearly equally to sound from all directions, giving an ideally circular (spherical) polar pattern independent of angle. True pressure microphones are omnidirectional at low and mid frequencies but narrow at high frequencies as the wavelength approaches the capsule size.','An omnidirectional mic hears all directions about equally. Its pickup map is basically a circle. This holds well at low and middle frequencies. At high frequencies even an omni gets a bit directional.','It captures a full, natural sound field and room ambience without the tonal changes that directional patterns add off-axis.','For a natural room recording, an engineer uses omni mics and moves them closer or farther to set the direct-to-reverberant balance, since there is no proximity effect.','Polar Patterns',ARRAY['Polar patterns','Pattern consistency','Polar narrowing','Proximity effect','Membrane']::text[],ARRAY['Assuming an omni stays perfectly omni at high frequencies; it narrows as wavelength nears capsule size.','Expecting proximity bass boost; true omnis have none.','Dismissing an omni as useless because it has no directional rejection, and overlooking its flat, low-coloration response.']::text[],ARRAY['Recording room ambience or a natural stereo pair.','Measuring sound level where direction should not matter.','Choosing a lavalier that resists placement changes.']::text[],'beginner',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Omnidirectional behavior');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2a469310-a2a8-47d2-9418-282089902d2f','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2a469310-a2a8-47d2-9418-282089902d2f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2a469310-a2a8-47d2-9418-282089902d2f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c631d470-c103-4183-bb17-b6ce5e2d186e','One-inch measurement microphone','A precision condenser measurement microphone with a nominal one-inch (about 23.77 mm) diaphragm diameter, standardized under IEC 61094. Its large diaphragm gives high sensitivity and low self-noise for low-level measurements, at the cost of a narrower usable high-frequency range and earlier directional narrowing than half-inch or quarter-inch types.','This is a lab-grade mic with a one-inch sensing diaphragm. Its size makes it very sensitive and quiet. That suits very soft sound measurements. The trade-off is a smaller high-frequency range.','It provides high sensitivity and low noise for measuring quiet sounds, serving as a calibrated reference in acoustics labs.','Measuring a very low background noise level, a technician chooses a one-inch capsule for its low self-noise, accepting reduced accuracy above a few kilohertz.','Measurement',ARRAY['Open-circuit sensitivity','Nonreciprocal transducer','Polar narrowing','A-weighted self-noise','Pattern consistency']::text[],ARRAY['Using a one-inch mic for high-frequency work where its response narrows and rolls off.','Ignoring that larger diaphragms are more directional at high frequencies.','Assuming bigger always means better without matching the mic to the measurement.']::text[],ARRAY['Measuring very quiet environments or self-noise.','Calibrating a reference microphone chain.','Choosing capsule size for a sound-level standard.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='One-inch measurement microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c631d470-c103-4183-bb17-b6ce5e2d186e','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c631d470-c103-4183-bb17-b6ce5e2d186e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c631d470-c103-4183-bb17-b6ce5e2d186e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a4679b34-98d3-4b60-9594-4d7b45f46d03','Open-circuit sensitivity','A microphone''s output voltage produced by a defined sound pressure when its load is effectively infinite (open circuit), so no current flows and the full electromotive voltage appears. It is stated in millivolts per pascal or in decibels relative to 1 V/Pa, usually measured at 1 kHz per IEC 60268-4.','Sensitivity says how much voltage a mic makes for a given loudness. Open-circuit means measured with almost no load current. It is quoted in millivolts per pascal or in decibels. A higher number means a hotter mic output.','It lets a technician predict a mic''s output level, set preamp gain, and compare how hot different microphones are.','A mic rated 20 mV/Pa equals 20 log10(0.02/1) = minus 34 dB re 1 V/Pa; at 94 dB SPL (1 Pa) it outputs 20 mV.','Specifications',ARRAY['Maximum undistorted output','Microphone preamplifier noise','Membrane','Nonreciprocal transducer','Dynamic range']::text[],ARRAY['Confusing open-circuit sensitivity with the loaded output into a real preamp input.','Mixing up mV/Pa and dB re 1 V/Pa when comparing mics.','Forgetting sensitivity is normally quoted at 1 kHz, not across the whole band.']::text[],ARRAY['Setting preamp gain for a new microphone.','Comparing output levels of condensers and ribbons.','Reading a datasheet''s sensitivity figure.']::text[],'intermediate','L = 20 log10(S / S0),  S0 = 1 V/Pa','Sensitivity level in decibels equals twenty times the log of the sensitivity divided by one volt per pascal.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Open-circuit sensitivity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a4679b34-98d3-4b60-9594-4d7b45f46d03','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a4679b34-98d3-4b60-9594-4d7b45f46d03') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a4679b34-98d3-4b60-9594-4d7b45f46d03');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd0b26bad-a2ea-4749-9cac-a7f04d6d7ab2','Optical microphone','A microphone that converts sound to an electrical signal by modulating a light beam rather than by capacitance or a moving coil, for example by sensing sound-induced motion of a diaphragm with light interference or intensity. Because the sensing element carries no electrical charge or field, optical microphones can be immune to electromagnetic interference and suitable for MRI or high-EMI environments.','An optical microphone uses light to sense sound. Sound moves a tiny surface, and light reads that motion. It carries no electrical signal at the sensing tip. This makes it immune to electrical interference, useful near MRI machines.','It provides sound pickup where electrical microphones fail, such as strong magnetic fields or high electromagnetic interference.','In an MRI suite, a technician uses a fiber-optic microphone for patient talkback because it is unaffected by the scanner''s strong magnetic field.','Microphone Types',ARRAY['Noncontact vibration measurement','Membrane','Particle-velocity sensor','Microelectromechanical microphone','Piezoelectric transduction']::text[],ARRAY['Assuming all optical mics are laser microphones aimed at distant windows.','Overlooking that light-source noise and drift can limit performance.','Thinking immunity to EMI means immunity to all noise sources.']::text[],ARRAY['Capturing audio inside an MRI machine.','Sound pickup in strong electromagnetic fields.','Specialized measurement where electrical mics fail.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Optical microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd0b26bad-a2ea-4749-9cac-a7f04d6d7ab2','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d0b26bad-a2ea-4749-9cac-a7f04d6d7ab2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d0b26bad-a2ea-4749-9cac-a7f04d6d7ab2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '48249ba9-b5ea-4561-9dbe-1882d9c27178','Package cavity','The enclosed air volume inside a microphone package, especially the back cavity (back volume) behind a MEMS diaphragm. Its size sets the acoustic compliance loading the diaphragm; a larger back volume raises compliance, increasing sensitivity and signal-to-noise ratio and improving low-frequency response.','Inside a mic package is a sealed pocket of air. In MEMS mics this is the back volume behind the diaphragm. A bigger air pocket lets the diaphragm move more freely. That raises sensitivity and helps the low end.','It provides the acoustic spring behind the diaphragm; designers size it to trade off sensitivity, noise, and package volume.','Choosing a MEMS mic for a slim earbud, an engineer accepts a smaller back cavity and its slightly lower sensitivity to fit the space.','MEMS Packaging',ARRAY['Package leakage','Microelectromechanical microphone','Membrane','Omnidirectional behavior','Open-circuit sensitivity']::text[],ARRAY['Assuming package cavity size does not affect sensitivity; back volume strongly does.','Ignoring Helmholtz resonances that the cavity and sound port can create.','Confusing the front sound-port volume with the rear back volume.']::text[],ARRAY['Selecting a MEMS mic for a compact product.','Understanding datasheet sensitivity and SNR trade-offs.','Designing a package for best low-frequency response.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Package cavity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '48249ba9-b5ea-4561-9dbe-1882d9c27178','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='48249ba9-b5ea-4561-9dbe-1882d9c27178') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='48249ba9-b5ea-4561-9dbe-1882d9c27178');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4d15747a-091b-407a-b2fe-5810546c3517','Package leakage','A small vent or leak path that equalizes static pressure between a microphone''s internal cavity and the outside air. This vent lets slow pressure changes pass without moving the diaphragm, which sets the microphone''s low-frequency roll-off: a smaller leak lowers the cutoff, a larger leak raises it.','A sealed mic package needs a tiny leak to balance air pressure. This vent stops the diaphragm from bowing when air pressure slowly changes. It also sets where the low end rolls off. A smaller leak keeps more deep bass.','It prevents static-pressure offset from stressing or biasing the diaphragm, while intentionally defining the microphone''s low-frequency cutoff.','A MEMS mic with a tight vent extends flat response down to about 20 Hz; widening the leak would raise the roll-off and thin the bass.','MEMS Packaging',ARRAY['Package cavity','Microelectromechanical microphone','Membrane','Omnidirectional behavior','Phase sensitivity']::text[],ARRAY['Assuming any leak is a defect; a controlled vent is required for pressure equalization.','Blocking the equalization vent during assembly, which shifts the low-frequency response.','Confusing acoustic leakage that ruins the seal with the intended pressure vent.']::text[],ARRAY['Understanding a MEMS mic''s low-frequency limit.','Diagnosing thin bass from a blocked vent.','Designing package seals and gaskets.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Package leakage');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4d15747a-091b-407a-b2fe-5810546c3517','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4d15747a-091b-407a-b2fe-5810546c3517') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4d15747a-091b-407a-b2fe-5810546c3517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0d9518fe-5030-4614-9ef0-62c583a36ffd','Particle-velocity sensor','A transducer that measures acoustic particle velocity, the oscillating motion of air molecules, rather than sound pressure. The best-known example, the Microflown (a trademark of Microflown Technologies), uses two closely spaced, electrically heated platinum wires; sound-induced airflow cools them asymmetrically, and the resulting resistance difference is proportional to particle velocity, giving an inherent figure-eight directivity.','Most mics sense sound pressure. This sensor senses air motion instead, called particle velocity. The Microflown brand uses two tiny heated wires. Passing sound cools them unevenly, and that difference reveals the air''s motion. It naturally hears in a figure-eight shape.','It captures the velocity (vector) part of a sound field, enabling sound-intensity and direction measurement when paired with a pressure microphone in a p-u probe.','For sound-intensity mapping, a technician combines a particle-velocity sensor with a pressure mic to measure both quantities at one point and find the energy-flow direction.','Microphone Types',ARRAY['Optical microphone','Noncontact vibration measurement','Piezoresistive transduction','Omnidirectional behavior','Microelectromechanical microphone']::text[],ARRAY['Assuming it measures pressure like a normal mic; it senses air velocity.','Forgetting its heated wires make it sensitive to wind and airflow.','Overlooking that intensity needs both pressure and velocity, not velocity alone.']::text[],ARRAY['Measuring sound intensity and energy flow.','Source localization with a p-u probe.','Studying acoustic fields near a surface.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Particle-velocity sensor');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0d9518fe-5030-4614-9ef0-62c583a36ffd','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0d9518fe-5030-4614-9ef0-62c583a36ffd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0d9518fe-5030-4614-9ef0-62c583a36ffd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4f763271-3927-4bad-8697-771b02e95c24','Pattern consistency','How well a microphone maintains its intended polar pattern across frequency. A mic with good pattern consistency keeps, for example, a cardioid shape at both low and high frequencies, so off-axis sound is attenuated with little tonal change; poor consistency makes off-axis sound colored and unnatural.','A mic''s pickup shape should stay the same across pitches. Pattern consistency means the shape holds from lows to highs. Then off-axis sound just gets quieter, not weird. Poor consistency makes side sounds change tone.','It predicts how natural off-axis and reverberant sound will be, which matters for live rejection and spill in multi-mic setups.','Choosing a stage vocal mic, an engineer prefers consistent cardioid response so cymbal bleed stays uncolored rather than harsh.','Polar Patterns',ARRAY['Polar patterns','Polar narrowing','Omnidirectional behavior','Polar-pattern invariance','Off-axis coloration']::text[],ARRAY['Judging a mic only by its on-axis response and ignoring off-axis behavior.','Assuming every cardioid holds its pattern at low frequencies.','Confusing pattern consistency with a flat on-axis frequency response.']::text[],ARRAY['Selecting mics for a live vocal or drum kit.','Evaluating off-axis coloration in a studio mic.','Reading multi-frequency polar plots.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pattern consistency');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4f763271-3927-4bad-8697-771b02e95c24','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4f763271-3927-4bad-8697-771b02e95c24') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4f763271-3927-4bad-8697-771b02e95c24');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5480b04e-1615-40b4-a811-82fa5b87034f','Phase interaction between microphones','The constructive and destructive interference that occurs when two or more microphones pick up the same source at slightly different arrival times and their signals are summed. The time difference creates a comb filter with cancellation notches, degrading tone; the 3-to-1 rule (mic spacing at least three times the source distance) limits it.','When two mics catch the same sound at slightly different times, mixing them causes interference. Some frequencies add and some cancel. This makes a comb-filter, hollow sound. The three-to-one spacing rule keeps it under control.','It explains hollow, phasey tone in multi-mic setups and motivates spacing rules and polarity checks.','Two mics with a 1 ms arrival difference notch at 500 Hz, 1500 Hz, and so on; the engineer respaces them using the 3-to-1 rule to reduce it.','Stereo Techniques',ARRAY['Phase matching','Near-coincident arrays','Mid/side recording','Comb filtering','Phase sensitivity']::text[],ARRAY['Blaming the room when hollow tone actually comes from mic-to-mic comb filtering.','Forgetting the 3-to-1 rule and spacing mics too close for the source distance.','Assuming a polarity flip fixes time-based comb filtering; it only shifts the notches.']::text[],ARRAY['Miking a source with close and room mics together.','Diagnosing hollow, phasey tone in a multi-mic mix.','Applying the 3-to-1 rule on stage or in the studio.']::text[],'intermediate','f_notch = (2n - 1) / (2 * dt),  n = 1, 2, 3, ...','Cancellation notches fall at odd multiples of one over twice the arrival-time difference.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Phase interaction between microphones');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5480b04e-1615-40b4-a811-82fa5b87034f','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5480b04e-1615-40b4-a811-82fa5b87034f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5480b04e-1615-40b4-a811-82fa5b87034f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '84722f05-308a-40e6-bfbd-c3bf9e13490a','Phase matching','The alignment of the phase and time responses of multiple microphones so their signals combine correctly. In arrays and stereo pairs, capsules must be phase-matched so that beamforming sums and differences behave as designed; phase mismatch fills in nulls, blurs imaging, and reduces directivity.','In a mic array, every mic''s timing must line up. Phase matching keeps their signals in step. Then the array steers and rejects sound as intended. Mismatched phase blurs the image and weakens the nulls.','It ensures that summed or differenced microphone signals produce the intended directivity, stereo image, and null depth.','Building a beamforming array, an engineer selects phase-matched MEMS mics so the design''s deep nulls survive in real hardware.','Array Processing',ARRAY['Phase sensitivity','Phase interaction between microphones','Null depth','Microelectromechanical microphone','Minimum-variance distortionless response']::text[],ARRAY['Assuming same-model mics are automatically phase-matched to tight tolerance.','Ignoring how cable, preamp, or converter differences add phase error.','Overlooking that phase mismatch, not just level mismatch, degrades array nulls.']::text[],ARRAY['Assembling a microphone array or beamformer.','Matching a stereo pair for imaging.','Troubleshooting shallow nulls in a built array.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Phase matching');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '84722f05-308a-40e6-bfbd-c3bf9e13490a','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='84722f05-308a-40e6-bfbd-c3bf9e13490a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='84722f05-308a-40e6-bfbd-c3bf9e13490a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f94f77a8-eb20-475b-baeb-6849e1cf4b5c','Phase sensitivity','The degree to which a microphone''s or array''s output depends on the phase (timing) of the incoming sound field rather than just its amplitude. Pressure-gradient (directional) microphones are inherently phase-sensitive because they respond to the pressure difference between two points, which produces both their directivity and their proximity effect.','Some mics react to sound''s timing, not just its loudness. This is phase sensitivity. Directional mics compare sound at two points. That timing difference gives them their direction and their close-up bass boost.','It explains why gradient microphones are directional and why arrays can steer beams, since directivity comes from phase differences across the capsule or array.','A technician exploits phase sensitivity by moving a cardioid closer to a source, using the proximity bass boost that the gradient design creates.','Directivity',ARRAY['Phase matching','Phase interaction between microphones','Polar patterns','Null angle','Particle-velocity sensor']::text[],ARRAY['Assuming all mics respond only to sound level, ignoring phase.','Confusing electrical polarity with acoustic phase response.','Overlooking that phase sensitivity underlies both directivity and proximity effect.']::text[],ARRAY['Explaining why gradient mics are directional.','Understanding proximity effect on directional mics.','Designing phase-based beamforming.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Phase sensitivity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f94f77a8-eb20-475b-baeb-6849e1cf4b5c','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f94f77a8-eb20-475b-baeb-6849e1cf4b5c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f94f77a8-eb20-475b-baeb-6849e1cf4b5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '476da72f-aef5-4b54-b13b-79c631a41c8b','Phase-transform weighting','A frequency weighting used in generalized cross-correlation time-delay estimation that divides each frequency component of the cross-spectrum by its magnitude, keeping only phase information. This whitening sharpens the correlation peak, making the time-difference-of-arrival estimate between two microphones more robust in reverberation; it is the PHAT weighting.','PHAT helps find the time gap between two mics hearing one source. It throws away loudness at each frequency and keeps only timing. This sharpens the match-up peak. It works better in echoey rooms.','It sharpens the cross-correlation peak for reliable time-difference-of-arrival estimation, the basis of many sound-localization systems.','A two-mic locator uses GCC-PHAT to find a 0.3 ms delay between the mics, then maps that delay to the talker''s direction.','Array Processing',ARRAY['Multiple signal classification','Minimum-variance distortionless response','Phase matching','Phase interaction between microphones','Time difference of arrival']::text[],ARRAY['Applying PHAT at very low SNR, where dividing by magnitude amplifies noise.','Assuming it needs no bandwidth limiting; empty bands can add spurious peaks.','Confusing the sharp PHAT peak with a measure of signal strength.']::text[],ARRAY['Locating a talker with a two-mic array.','Estimating time delay in reverberant rooms.','Building direction-of-arrival front ends.']::text[],'advanced','Psi_PHAT(f) = 1 / |G_12(f)|','The phase-transform weight equals one divided by the magnitude of the cross-power spectrum.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Phase-transform weighting');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '476da72f-aef5-4b54-b13b-79c631a41c8b','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='476da72f-aef5-4b54-b13b-79c631a41c8b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='476da72f-aef5-4b54-b13b-79c631a41c8b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8a1b5f94-97d8-4617-aadc-2de162be5ff9','Piezoelectric transduction','Conversion of mechanical stress into electric charge (and the reverse) by piezoelectric materials such as quartz or certain ceramics, in which straining the material produces a proportional charge. In microphones, sound bending a piezoelectric element generates a voltage; the generated charge is Q = d times F.','Some crystals make electricity when you bend or squeeze them. This is the piezoelectric effect. In a mic, sound flexes the crystal and it makes a voltage. Contact pickups and cheap buzzers use this idea.','It provides a rugged, self-generating transducer that needs no polarizing voltage, used in contact pickups, hydrophones, and inexpensive microphones.','Fitting a guitar with a piezo pickup, a technician mounts the element under the saddle so string force flexes it and generates the signal.','Transduction',ARRAY['Piezoresistive transduction','Membrane','Nonreciprocal transducer','Optical microphone','Particle-velocity sensor']::text[],ARRAY['Confusing piezoelectric (generates charge) with piezoresistive (changes resistance).','Loading a high-impedance piezo with a low-impedance input, which thins the bass.','Assuming it needs phantom power; a passive piezo generates its own charge.']::text[],ARRAY['Amplifying an acoustic instrument with a contact pickup.','Using a hydrophone or contact mic.','Explaining transducer types in training.']::text[],'intermediate','Q = d * F','The generated charge equals the piezoelectric coefficient times the applied force.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Piezoelectric transduction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8a1b5f94-97d8-4617-aadc-2de162be5ff9','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8a1b5f94-97d8-4617-aadc-2de162be5ff9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8a1b5f94-97d8-4617-aadc-2de162be5ff9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '422db737-c9b8-4774-995c-f2ff34c3f633','Piezoresistive transduction','A sensing method in which mechanical strain changes a material''s electrical resistance, so deflection is read as a resistance change rather than a generated charge. Piezoresistive MEMS microphones place strain-sensitive resistors on the diaphragm; the fractional resistance change equals the gauge factor times the strain.','Here, bending a material changes how well it conducts electricity. Sound flexes the diaphragm and its resistance shifts. Circuits read that resistance change as the signal. Some MEMS mics work this way instead of using charge.','It offers a low-impedance, robust sensing route for MEMS microphones and pressure sensors, needing a bias current to read the resistance change.','A piezoresistive MEMS mic with gauge factor 100 under a strain of 0.001 gives dR/R = 0.1, a 10 percent resistance change read by a bridge circuit.','Transduction',ARRAY['Piezoelectric transduction','Microelectromechanical microphone','Membrane','Package cavity','Nonreciprocal transducer']::text[],ARRAY['Confusing piezoresistive (resistance changes) with piezoelectric (charge generated).','Forgetting piezoresistive sensors need a supply current or bridge to work.','Ignoring their temperature sensitivity, which needs compensation.']::text[],ARRAY['Designing a MEMS microphone or pressure sensor.','Choosing a sensing method for harsh environments.','Comparing transduction types in a course.']::text[],'advanced','dR/R = GF * epsilon','The fractional change in resistance equals the gauge factor times the strain.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Piezoresistive transduction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '422db737-c9b8-4774-995c-f2ff34c3f633','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='422db737-c9b8-4774-995c-f2ff34c3f633') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='422db737-c9b8-4774-995c-f2ff34c3f633');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '29db47df-133a-4720-9483-49ddae8eca81','Polar narrowing','The tendency of a microphone''s polar pattern to become more directional (narrower) as frequency rises, because the wavelength shrinks toward the diaphragm''s size. This makes large-diaphragm and omnidirectional mics beam at high frequencies, dulling and coloring off-axis sound even when the on-axis response is flat.','A mic''s pickup gets narrower as pitch rises. This is polar narrowing. It happens because high sounds have short wavelengths near the diaphragm''s size. So off-axis highs get dull, especially on big mics.','It explains why off-axis sound loses treble and why capsule size trades sensitivity against high-frequency uniformity.','Knowing large diaphragms narrow at high frequencies, an engineer keeps a singer on-axis or picks a small-diaphragm mic for a moving source.','Polar Patterns',ARRAY['Pattern consistency','Omnidirectional behavior','Polar patterns','One-inch measurement microphone','Membrane']::text[],ARRAY['Assuming an omni stays omni at high frequencies; it narrows like other mics.','Blaming dull off-axis sound on the room instead of polar narrowing.','Ignoring diaphragm size when off-axis consistency matters.']::text[],ARRAY['Miking a moving performer.','Choosing capsule size for even coverage.','Explaining off-axis treble loss.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Polar narrowing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '29db47df-133a-4720-9483-49ddae8eca81','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='29db47df-133a-4720-9483-49ddae8eca81') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='29db47df-133a-4720-9483-49ddae8eca81');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd6683716-24cd-4356-afa6-f7dd6ad0cf48','Polar patterns','The directional response of a microphone, shown as a plot of sensitivity versus angle around the capsule. First-order patterns follow r(theta) = A + B cos(theta) with A + B = 1, giving omnidirectional (A=1), cardioid (A=B=0.5), supercardioid, hypercardioid, and figure-eight (A=0, B=1) shapes.','A polar pattern is a mic''s pickup map by direction. It shows where the mic hears well or poorly. Omni, cardioid, and figure-eight are common shapes. Mixing a round part and a figure-eight part sets the shape.','It tells the technician how a mic responds to sound from each direction, guiding placement, rejection, and stereo technique.','A cardioid follows r(theta) = 0.5(1 + cos theta), so at 90 degrees r = 0.5 (minus 6 dB) and at 180 degrees r = 0 (full rejection).','Polar Patterns',ARRAY['Omnidirectional behavior','Pattern consistency','Polar narrowing','Null angle','Polar-pattern invariance']::text[],ARRAY['Confusing supercardioid and hypercardioid, which have different rear lobes and null angles.','Assuming a cardioid rejects the sides; its deepest rejection is at the rear.','Forgetting that real patterns change with frequency.']::text[],ARRAY['Choosing a pattern for a vocal or instrument.','Planning rejection of monitors or spill.','Selecting patterns for a stereo array.']::text[],'beginner','r(theta) = A + B cos(theta),  A + B = 1','The directional response equals a fixed part plus a cosine part that varies with angle, and the two parts sum to one.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Polar patterns');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd6683716-24cd-4356-afa6-f7dd6ad0cf48','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d6683716-24cd-4356-afa6-f7dd6ad0cf48') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d6683716-24cd-4356-afa6-f7dd6ad0cf48');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b7ca27b5-5e26-4619-aeae-906ec2464c27','Polar-pattern invariance','The condition in which a microphone''s or array''s directional (polar) pattern stays essentially constant across frequency. It is the design goal behind frequency-invariant beamforming and well-behaved directional capsules, ensuring uniform directivity and off-axis tonal balance over the working band.','Ideally a mic keeps the same pickup shape at every pitch. That is polar-pattern invariance. It means the directivity does not change with frequency. Off-axis sound then stays natural across the band.','It defines the ideal of frequency-independent directivity, sought in measurement mics and in frequency-invariant array design.','Designing an array of mics, an engineer uses frequency-dependent weighting so the beamwidth stays constant, approaching polar-pattern invariance.','Polar Patterns',ARRAY['Pattern consistency','Polar narrowing','Polar patterns','Omnidirectional behavior','Phase matching']::text[],ARRAY['Assuming ordinary mics have invariant patterns; most narrow with frequency.','Confusing pattern invariance with a flat on-axis frequency response.','Expecting a simple array to be frequency-invariant without special weighting.']::text[],ARRAY['Designing frequency-invariant beamformers.','Specifying measurement mics with uniform directivity.','Evaluating off-axis consistency across the band.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Polar-pattern invariance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b7ca27b5-5e26-4619-aeae-906ec2464c27','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b7ca27b5-5e26-4619-aeae-906ec2464c27') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b7ca27b5-5e26-4619-aeae-906ec2464c27');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '96a54a6b-4661-4fa0-8b8a-d624b01aad7d','Pressure doubling at boundaries','When a sound wave strikes a large, rigid, acoustically reflective boundary, the incident and reflected waves add in phase at the surface, so the local sound pressure is twice the free-field value, a rise of about 6 dB. This effect is the operating basis of boundary (surface-mount) microphones, which place the diaphragm at or very close to the surface to exploit the coherent addition and avoid comb filtering.','A hard surface reflects sound back on itself. Right at the surface the reflected wave adds to the direct wave. The pressure there doubles, which is about 6 decibels louder. Boundary microphones sit on the surface to use this gain cleanly.','It explains why placing a microphone against a large surface raises level and avoids the comb-filter dips caused by a delayed floor or wall reflection.','A technician tapes a boundary microphone to a stage floor or table; the surface gives roughly +6 dB and a smooth response instead of a hollow, filtered sound.','Boundary Acoustics',ARRAY['Boundary microphone','Comb filtering','Pressure microphones','Half-space loading','Reflection']::text[],ARRAY['Assuming the full +6 dB applies at all frequencies rather than where the microphone is small or right at the surface.','Confusing boundary pressure doubling with the bass boost of proximity effect.','Mounting a boundary microphone on a small, thin panel and expecting large-boundary behavior.']::text[],ARRAY['Taping a boundary microphone to a stage or altar floor for theater pickup.','Explaining why a floor reflection colors an overhead microphone but not a boundary microphone.','Miking a conference table with a surface-mount microphone.']::text[],'intermediate','p_boundary = 2 * p_free  ;  L = 20*log10(2) approximately 6.02 dB','At the rigid surface the sound pressure equals twice the free-field pressure, which is about a six decibel increase.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pressure doubling at boundaries');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '96a54a6b-4661-4fa0-8b8a-d624b01aad7d','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='96a54a6b-4661-4fa0-8b8a-d624b01aad7d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='96a54a6b-4661-4fa0-8b8a-d624b01aad7d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '31a3d923-48a7-4d3b-8969-6dbd313bc999','Pressure equalization vent','A tiny capillary leak (static-pressure vent) connecting the sealed rear cavity of a pressure microphone to the outside air, allowing slow changes in barometric or ambient static pressure to equalize across the diaphragm. Because it passes only very low, sub-audio rates of pressure change, it sets the microphone''s low-frequency roll-off without responding to audio-frequency sound.','A pressure microphone has a sealed space behind its diaphragm. A very small leak links that space to outside air. It lets slow weather and altitude changes even out. It does not pass audible sound, but it sets how low the microphone reaches.','It protects the diaphragm from being pushed off center by static pressure changes while defining the microphone''s lowest usable frequency.','A technician avoids covering or contaminating the vent hole; a blocked vent shifts the low-frequency corner and can leave the diaphragm mispositioned after altitude changes.','Capsule Design',ARRAY['Rear chamber','Static pressure','Pressure microphones','Low-frequency roll-off','Diaphragm']::text[],ARRAY['Mistaking the vent for a manufacturing defect and sealing it.','Covering the vent with grime or a fingerprint and then blaming lost low end on the preamp.','Assuming the vent passes audible bass rather than only very slow static changes.']::text[],ARRAY['Cleaning a measurement microphone without blocking its static vent.','Explaining low-frequency roll-off when a mic is flown to high altitude.','Comparing sealed pressure capsules with vented ones during capsule teardown.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pressure equalization vent');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '31a3d923-48a7-4d3b-8969-6dbd313bc999','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='31a3d923-48a7-4d3b-8969-6dbd313bc999') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='31a3d923-48a7-4d3b-8969-6dbd313bc999');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '543652f2-99bc-40a6-ad53-08624d79674e','Pressure microphones','A microphone whose diaphragm is exposed to the sound field on one side only, with a sealed rear cavity, so its output follows the scalar sound pressure at the diaphragm regardless of the wave''s direction of arrival. This gives a nominally omnidirectional pattern and no inherent proximity effect.','This microphone has sound reaching only the front of its diaphragm. The back is sealed. It reacts to the pressure at that point, no matter which way the sound comes from. That makes it pick up all directions about equally.','It provides direction-independent, low-coloration pickup, which is why laboratory measurement microphones and many omnidirectional studio microphones are pressure types.','A technician chooses a pressure (omni) microphone for accurate room measurement or for a natural, full-range acoustic pickup with no bass boost when moved close.','Microphone Class',ARRAY['Omnidirectional','Pressure response','Pressure transducer','Measurement microphone','Pressure-gradient microphones']::text[],ARRAY['Assuming a pressure microphone stays perfectly omnidirectional at high frequencies, where it narrows as wavelength nears diaphragm size.','Expecting a pressure omni to reject off-axis sound like a directional microphone.','Thinking omnidirectional means it never needs a windscreen outdoors.']::text[],ARRAY['Selecting a measurement microphone for room response testing.','Choosing an omni for close vocal work without proximity bass boost.','Explaining why an omni has no rear rejection for a spill problem.']::text[],'beginner',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pressure microphones');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '543652f2-99bc-40a6-ad53-08624d79674e','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='543652f2-99bc-40a6-ad53-08624d79674e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='543652f2-99bc-40a6-ad53-08624d79674e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5b42ccac-ae6e-435d-a02c-dfeb53530f7c','Pressure response','The frequency-dependent sensitivity of a microphone when a uniform sound pressure acts on its diaphragm, as produced in a small closed coupler or cavity. It is distinct from the free-field response (plane wave, defined direction) and the diffuse-field (random-incidence) response, and it is the quantity obtained in pressure reciprocity calibration.','This is how a microphone responds when the same pressure acts evenly on its diaphragm. Engineers create this in a small sealed cavity. It differs from how the microphone behaves in open air. Lab calibration measures this pressure response.','It defines a repeatable, geometry-independent measure of sensitivity used for primary calibration and for correcting field measurements.','A calibration lab states a measurement microphone''s pressure response, then applies a free-field correction curve before the mic is used to measure sound in a room.','Frequency Response',ARRAY['Free-field response','Diffuse-field response','Pressure calibration','Coupler','Pressure microphones']::text[],ARRAY['Confusing pressure response with free-field response and skipping the correction.','Assuming the three response types are identical at high frequencies, where they diverge most.','Using a pressure-field-corrected microphone directly in a free field without adjustment.']::text[],ARRAY['Reading a calibration certificate that lists pressure and free-field curves.','Choosing the correct correction when a mic moves from coupler to open air.','Comparing capsule responses in a coupler during type testing.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pressure response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5b42ccac-ae6e-435d-a02c-dfeb53530f7c','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5b42ccac-ae6e-435d-a02c-dfeb53530f7c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5b42ccac-ae6e-435d-a02c-dfeb53530f7c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1c5e4b72-9017-4c5e-b60d-81cb6bfd5123','Pressure transducer','A transducer that converts local sound pressure into a proportional electrical signal, sensing the instantaneous pressure acting on a diaphragm open to the field on one side only. In microphone terminology it is the pressure-operated capsule underlying omnidirectional and measurement microphones.','This device turns sound pressure into an electrical signal. It senses pressure on one side of a diaphragm. The back is sealed off. It reacts to how hard the air pushes, not to which way the sound flows.','It is the sensing element that makes direction-independent, pressure-following microphones possible.','A technician recognizes a pressure transducer capsule by its sealed back and omni pattern, and expects flat, direction-stable output for measurement work.','Transducer Type',ARRAY['Pressure microphones','Diaphragm','Pressure-gradient transducer','Sensitivity','Omnidirectional']::text[],ARRAY['Confusing a pressure transducer with a pressure-gradient transducer, which senses a difference not absolute pressure.','Assuming every microphone capsule is a pressure transducer.','Expecting proximity bass boost from a pure pressure transducer.']::text[],ARRAY['Identifying capsule type during microphone servicing.','Explaining why a measurement capsule is a pressure transducer.','Contrasting pressure and gradient operation in a training class.']::text[],'beginner',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pressure transducer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1c5e4b72-9017-4c5e-b60d-81cb6bfd5123','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1c5e4b72-9017-4c5e-b60d-81cb6bfd5123') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1c5e4b72-9017-4c5e-b60d-81cb6bfd5123');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e3974dde-58d9-4675-b335-511c2fbab5c1','Pressure-event robustness','The ability of a microphone''s transducing element to withstand sudden, large transient overpressure events, such as plosives, wind gusts, close percussion, or connector or cabling transients, without mechanical damage or lasting change in performance. It depends on diaphragm or ribbon strength, suspension, protective grille, and any overload venting, and is closely tied to the rated maximum sound pressure level.','This is how well a microphone survives sudden, strong bursts of pressure. Examples are hard plosives, wind gusts, or being blown into. Sturdy condensers usually cope well. Thin ribbon elements are fragile and can be stretched or torn.','It guides safe handling and placement so a microphone is not physically harmed by transient overpressure in real-world use.','A technician fits a windscreen and pop filter and keeps fragile ribbons away from strong air blasts, matching microphone choice to expected transient conditions.','Reliability and Handling',ARRAY['Maximum SPL','Windscreen','Ribbon-microphone operation','Plosive','Overload']::text[],ARRAY['UNSAFE: Blowing into or ''popping'' a ribbon microphone to test it can permanently stretch or tear the ribbon.','UNSAFE: Leaving a fragile ribbon microphone unprotected in front of strong wind or a kick-drum blast.','Assuming a high maximum-SPL rating also guarantees survival of physical air blasts and handling shocks.']::text[],ARRAY['Deciding whether a ribbon microphone is safe close to a loud brass bell.','Protecting microphones outdoors on a windy location shoot.','Explaining why blowing into a microphone is a poor way to check it.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pressure-event robustness');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e3974dde-58d9-4675-b335-511c2fbab5c1','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e3974dde-58d9-4675-b335-511c2fbab5c1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e3974dde-58d9-4675-b335-511c2fbab5c1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '29c5cc7a-8e28-47be-8921-3c2f5f360ee7','Pressure-gradient microphones','A microphone whose diaphragm is open to the sound field on both faces, so the net driving force is the difference in pressure (the pressure gradient) between front and rear. In pure form this yields a figure-eight (bidirectional) polar pattern proportional to particle velocity, and it produces proximity effect, a low-frequency rise when the source is close.','Sound reaches both sides of this diaphragm. The diaphragm moves with the difference between the two pressures. That difference relates to how the air moves. The result picks up front and back but rejects the sides. Close sources also gain extra bass.','It provides directional pickup and side rejection using a single diaphragm, and it is the basis of ribbon and directional condenser microphones.','A technician exploits the side nulls of a figure-eight to reject a nearby instrument, while remembering that close placement boosts bass through proximity effect.','Microphone Class',ARRAY['Figure-8','Proximity effect','Ribbon velocity microphone','Bidirectional','Pressure microphones']::text[],ARRAY['Thinking only ribbon microphones are pressure-gradient types when many directional condensers are too.','Forgetting the bass boost from proximity effect during close-miking.','Assuming a figure-eight rejects the rear; it is fully sensitive front and back.']::text[],ARRAY['Using figure-eight side nulls to separate two facing singers.','Explaining proximity bass buildup on a close vocal.','Setting up a mid-side pair with a bidirectional side microphone.']::text[],'intermediate','F ~ (p_front - p_rear) ~ d * (dp/dx)','The force on the diaphragm is proportional to the front-minus-rear pressure difference, which equals the path spacing times the pressure gradient.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pressure-gradient microphones');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '29c5cc7a-8e28-47be-8921-3c2f5f360ee7','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='29c5cc7a-8e28-47be-8921-3c2f5f360ee7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='29c5cc7a-8e28-47be-8921-3c2f5f360ee7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cfd7168c-953d-47da-a77b-81ced644eec8','Pressure-gradient receiver','A receiving electroacoustic transducer that responds to the pressure difference across its diaphragm rather than to absolute pressure, the general acoustics term for a bidirectional, velocity-type pickup. The term (from Olson''s work) emphasizes the receiving element''s operating principle underlying figure-eight microphones.','This is a receiver that reacts to a pressure difference, not to total pressure. Sound reaches both sides of its diaphragm. The difference drives it. This is the working idea behind figure-eight microphones.','It names, in formal acoustics terms, the receiving principle that gives directional, velocity-proportional response.','A technician reading acoustics literature treats ''pressure-gradient receiver'' as the engineering description of a bidirectional microphone element.','Transducer Type',ARRAY['Pressure-gradient microphones','Figure-8','Velocity microphone','Bidirectional','Particle velocity']::text[],ARRAY['Treating it as a different device from a pressure-gradient microphone rather than a formal synonym for the element.','Confusing gradient (difference) operation with pressure (absolute) operation.','Assuming ''receiver'' implies a loudspeaker rather than a pickup element.']::text[],ARRAY['Reading classic acoustics texts that use ''receiver'' for a pickup.','Explaining the physics of a figure-eight capsule.','Distinguishing pressure and gradient receiving principles in study.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pressure-gradient receiver');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cfd7168c-953d-47da-a77b-81ced644eec8','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cfd7168c-953d-47da-a77b-81ced644eec8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cfd7168c-953d-47da-a77b-81ced644eec8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '45d080a8-0a21-46ac-8d5e-090aa67c5b9a','Pressure-gradient transducer','The transducing element that converts the pressure difference across a doubly exposed diaphragm into an electrical signal, producing a velocity-proportional, figure-eight response. It is the generic element in ribbon microphones and in directional (open-back) condenser and dynamic capsules.','This element turns a pressure difference into an electrical signal. Its diaphragm feels sound on both sides. It reacts to the gap between the two pressures. Ribbon and directional capsules are built this way.','It is the sensing element that produces directional, velocity-type microphone behavior.','A technician identifies an open-back, both-sides-exposed capsule as a pressure-gradient transducer and expects figure-eight tendencies and proximity effect.','Transducer Type',ARRAY['Pressure-gradient microphones','Pressure transducer','Ribbon velocity microphone','Figure-8','Proximity effect']::text[],ARRAY['Confusing it with a pressure transducer, which senses absolute not differential pressure.','Assuming gradient transducers cannot be condensers.','Overlooking that gradient operation inherently brings proximity effect.']::text[],ARRAY['Classifying a capsule during microphone repair.','Teaching the difference between pressure and gradient sensing.','Predicting proximity behavior from capsule construction.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pressure-gradient transducer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '45d080a8-0a21-46ac-8d5e-090aa67c5b9a','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='45d080a8-0a21-46ac-8d5e-090aa67c5b9a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='45d080a8-0a21-46ac-8d5e-090aa67c5b9a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0328138f-bc90-4062-acc7-f658a79315f2','Pressure–velocity probe','A measurement probe that captures both acoustic pressure and acoustic particle velocity at essentially one point, using a pressure microphone together with a particle-velocity sensor (a p-u probe). The two signals let an instrument compute sound intensity, the magnitude and direction of acoustic energy flow.','This probe measures two things at one spot. One is sound pressure. The other is how fast the air particles move. Together they give sound intensity. That tells both how strong the sound is and which way it flows.','It enables direct measurement of sound intensity and energy direction for source location and sound-power testing.','A technician sweeps a p-u probe over a machine surface; the instrument multiplies pressure and velocity to map how much sound power each area radiates.','Acoustic Measurement',ARRAY['Sound-intensity probe','Particle velocity','Sound intensity','Pressure microphones','Sound-power measurement']::text[],ARRAY['Assuming pressure alone gives energy direction; velocity is needed too.','Using the probe outside its valid frequency and phase-matched range.','Confusing the p-u probe with a two-microphone p-p intensity probe.']::text[],ARRAY['Mapping noise sources on an engine or appliance.','Measuring sound power in a non-ideal field.','Locating a leak or radiating panel by intensity direction.']::text[],'advanced','I = <p * u>  (time-averaged)','Instantaneous sound intensity equals sound pressure times particle velocity; the useful value is its time average.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pressure–velocity probe');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0328138f-bc90-4062-acc7-f658a79315f2','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0328138f-bc90-4062-acc7-f658a79315f2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0328138f-bc90-4062-acc7-f658a79315f2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fe06b242-6536-4e8f-b685-00f86c1b84f4','Quarter-inch measurement microphone','A laboratory measurement condenser microphone with a nominal quarter-inch (about 6.35 mm) diaphragm diameter, as standardized under the IEC 61094 series. Its small diaphragm extends the usable high-frequency range and raises the maximum sound pressure level, at the cost of lower sensitivity and higher self-noise than a half-inch type.','This is a lab microphone with a small diaphragm about a quarter inch across. The small size lets it reach very high frequencies and very loud levels. In trade, it is less sensitive and a bit noisier than a bigger half-inch microphone.','It is used where wide high-frequency bandwidth and high maximum level matter more than the lowest possible self-noise.','A technician picks a quarter-inch microphone to measure a loud, high-frequency source such as ultrasonic or high-level noise, then applies the datasheet''s free-field correction.','Measurement Microphone',ARRAY['Half-inch measurement microphone','Free-field response','Self-noise','Maximum SPL','Sound-level-meter microphone']::text[],ARRAY['Expecting a quarter-inch microphone to be as quiet or as sensitive as a half-inch type.','Skipping the free-field or random-incidence correction for the diaphragm.','Assuming smaller always means better for every measurement.']::text[],ARRAY['Measuring very high sound levels near machinery.','Capturing extended high-frequency or near-ultrasonic content.','Choosing a capsule size for a specific dynamic-range need.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Quarter-inch measurement microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fe06b242-6536-4e8f-b685-00f86c1b84f4','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fe06b242-6536-4e8f-b685-00f86c1b84f4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fe06b242-6536-4e8f-b685-00f86c1b84f4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1ce18639-f50f-40e9-b21f-96fabd4363d9','Radio-frequency immunity','A microphone''s or its associated electronics'' ability to reject radiated radio-frequency electromagnetic fields, from mobile phones, transmitters, and wireless networks, so those signals do not demodulate into audible buzz or interference in the audio output. It is verified with radiated RF immunity testing per IEC 61000-4-3, with equipment-level requirements for professional audio set by EN 55103-2.','This is how well a microphone shrugs off radio waves. Phones and transmitters send out strong radio signals. A poorly shielded microphone can turn them into buzzing in the audio. Good design and shielding stop that noise.','It ensures clean audio in real venues full of wireless devices, phones, and transmitters.','A technician troubleshooting a rhythmic phone buzz checks microphone and cable shielding and grounding rather than assuming the console is faulty.','EMC and Interference',ARRAY['Balanced line','Shielding','Wireless microphone','Phantom power','Self-noise']::text[],ARRAY['Blaming the cable when the noise is really radio-frequency demodulation inside the microphone.','Assuming a balanced connection alone removes all radio interference.','Coiling microphone cable near transmitters and expecting no pickup.']::text[],ARRAY['Diagnosing a mobile-phone buzz on a lectern microphone.','Selecting microphones for a venue crowded with wireless systems.','Testing gear for electromagnetic compatibility compliance.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Radio-frequency immunity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1ce18639-f50f-40e9-b21f-96fabd4363d9','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1ce18639-f50f-40e9-b21f-96fabd4363d9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1ce18639-f50f-40e9-b21f-96fabd4363d9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6c2c836e-0784-455f-8f1a-fc89e41e62f0','Rear chamber','The enclosed air cavity behind a microphone diaphragm whose acoustic compliance and damping help shape the capsule''s low-frequency response and resonance. In a pressure (omni) capsule the chamber is sealed except for a static vent; in a directional capsule it is coupled to the rear sound field through ports and acoustic resistances.','This is the pocket of air right behind the diaphragm. Its size and damping affect how the microphone responds, especially at low frequencies. In an omni it is sealed. In a directional microphone, small openings let rear sound in.','It is a key tuning element that sets capsule resonance, damping, and, in directional designs, the polar pattern.','A technician servicing a capsule keeps the rear chamber and its ports clean and unobstructed, since debris there alters response and pattern.','Capsule Design',ARRAY['Pressure equalization vent','Diaphragm','Acoustic compliance','Rear-port delay networks','Single diaphragm']::text[],ARRAY['Confusing a sealed pressure rear chamber with a ported directional one.','Assuming the chamber has no effect on frequency response.','Blocking rear ports and changing the polar pattern unintentionally.']::text[],ARRAY['Cleaning or reassembling a condenser capsule.','Explaining why a directional capsule needs rear openings.','Diagnosing a changed pattern after contamination.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Rear chamber');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6c2c836e-0784-455f-8f1a-fc89e41e62f0','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6c2c836e-0784-455f-8f1a-fc89e41e62f0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6c2c836e-0784-455f-8f1a-fc89e41e62f0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e539aa1d-4f58-4274-94d8-368d670db284','Rear lobe','A region of significant sensitivity behind a directional microphone in its polar pattern. Supercardioid and hypercardioid patterns have a pronounced rear lobe, whereas a cardioid nominally has a null and minimal rear pickup.','This is an area of pickup behind a directional microphone. Some patterns, like supercardioid and hypercardioid, still hear well from behind. A cardioid is nearly deaf directly behind. Knowing this helps place monitors and control spill.','It describes where behind-the-microphone sound leaks in, guiding placement for feedback and spill control.','A technician aims a floor monitor at a supercardioid''s rear null, not straight behind it, because the rear lobe would otherwise cause feedback.','Polar Pattern',ARRAY['Supercardioid','Hypercardioid','Cardioid','Null','Side lobe']::text[],ARRAY['Assuming a supercardioid rejects everything behind it, ignoring its rear lobe.','Placing a monitor directly behind a directional microphone instead of at the null angle.','Confusing the rear lobe with a high-frequency side lobe.']::text[],ARRAY['Positioning stage monitors to avoid feedback.','Choosing a pattern to reject a specific rear noise source.','Explaining spill differences between cardioid and hypercardioid.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Rear lobe');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e539aa1d-4f58-4274-94d8-368d670db284','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e539aa1d-4f58-4274-94d8-368d670db284') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e539aa1d-4f58-4274-94d8-368d670db284');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'eb95af82-7574-4483-ad8e-5320ce25b2f1','Rear-port delay networks','The system of rear entry ports, cavities, and acoustic resistances built into a single-diaphragm directional capsule that delays sound reaching the diaphragm''s rear face. This acoustic phase-shift network combines rear-arriving sound with front-arriving sound in the correct time relationship to create cardioid-family polar patterns.','These are openings and passages behind a single diaphragm. They slow the sound reaching the back of the diaphragm. The delayed rear sound combines with the front sound. That timing is what makes a cardioid pattern from one diaphragm.','It lets a single diaphragm form a directional pattern by acoustic timing rather than needing two diaphragms.','A technician understands that clogged or damaged rear ports ruin the delay timing, turning a clean cardioid into an erratic or omni-like pattern.','Capsule Design',ARRAY['Rear chamber','Cardioid','Acoustic resistance','Single diaphragm','Pressure-gradient microphones']::text[],ARRAY['Believing a cardioid pattern requires two capsules.','Blocking rear ports during cleaning and losing directionality.','Assuming the pattern is set purely electrically rather than acoustically.']::text[],ARRAY['Explaining how a single-diaphragm cardioid works.','Diagnosing a pattern change from blocked ports.','Comparing single- and dual-diaphragm directional designs.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Rear-port delay networks');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'eb95af82-7574-4483-ad8e-5320ce25b2f1','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='eb95af82-7574-4483-ad8e-5320ce25b2f1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='eb95af82-7574-4483-ad8e-5320ce25b2f1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6e020980-391a-46b2-801f-3357dd9a96a6','Reciprocal microphone','A microphone that behaves as a linear, passive, reversible electroacoustic transducer, so it obeys the reciprocity principle and can act as both a sound receiver and a sound source. This reversibility is the basis of the primary reciprocity calibration method, which determines a laboratory standard microphone''s absolute sensitivity without needing a previously calibrated reference.','This microphone can work in both directions. It can receive sound, and it can also make sound. That two-way behavior follows a physics rule called reciprocity. Labs use it to measure a microphone''s exact sensitivity. They do this without any reference microphone.','It enables absolute, self-contained primary calibration of measurement microphones traceable to physical units.','A standards lab couples reciprocal microphones in a defined cavity and, using electrical measurements, computes each microphone''s sensitivity from first principles.','Calibration',ARRAY['Pressure response','Laboratory standard microphone','Coupler','Sensitivity','Reference environmental conditions']::text[],ARRAY['Thinking calibration always needs a known reference microphone.','Confusing reciprocity (primary) calibration with comparison calibration.','Assuming any microphone qualifies, when it must be linear, passive, and reversible.']::text[],ARRAY['Performing primary calibration of standard microphones.','Explaining metrological traceability of a sound measurement.','Distinguishing primary and secondary calibration methods.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reciprocal microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6e020980-391a-46b2-801f-3357dd9a96a6','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6e020980-391a-46b2-801f-3357dd9a96a6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6e020980-391a-46b2-801f-3357dd9a96a6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '80bae28f-00b2-4052-8116-8caab2dd9671','Reference environmental conditions','The standardized ambient conditions at which a microphone''s or sound level meter''s specified sensitivity and performance are defined. In IEC 61672-1 the reference conditions are an air temperature of 23 degrees Celsius, a static (barometric) pressure of 101.325 kilopascals, and a relative humidity of 50 percent; deviations are corrected using published environmental coefficients.','These are the agreed ''normal'' conditions for rating a microphone. The set values are 23 degrees Celsius. Air pressure is normal sea-level pressure. Humidity is 50 percent. Real rooms differ from these. Engineers must adjust for that. So they correct readings for temperature, pressure, and humidity.','It gives a common baseline so ratings from different labs and dates are comparable and correctable.','A technician measuring at high altitude applies a static-pressure correction because the microphone''s sensitivity differs from its rated value at 101.325 kilopascals.','Calibration',ARRAY['Sensitivity tolerance','Static pressure','Reciprocal microphone','Sound-calibrator verification','Pressure equalization vent']::text[],ARRAY['Ignoring the effect of altitude or barometric pressure on sensitivity.','Assuming the lab-stated sensitivity holds unchanged outdoors.','Forgetting temperature and humidity corrections for precise work.']::text[],ARRAY['Correcting measurements taken at altitude or in heat.','Reading environmental coefficients on a calibration certificate.','Comparing ratings measured under different conditions.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reference environmental conditions');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '80bae28f-00b2-4052-8116-8caab2dd9671','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='80bae28f-00b2-4052-8116-8caab2dd9671') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='80bae28f-00b2-4052-8116-8caab2dd9671');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd2e8f93d-9be4-4f62-9dfc-ab2835929a5d','Ribbon loading','The acoustic and mechanical loading applied to a ribbon element, that is, how the surrounding baffle, magnet structure, air, and transformer control the corrugated ribbon''s motion. In a classic velocity ribbon the ribbon is mass-controlled with its fundamental resonance tuned well below the audio band, so it moves in proportion to particle velocity across the range.','This is how the parts around a ribbon control its movement. The magnet gap, baffle, and air all load the thin ribbon. In a velocity ribbon, the ribbon is tuned to resonate below hearing. Then it tracks air motion smoothly.','It sets the ribbon''s frequency response, damping, and directional behavior.','A technician understands that changing a ribbon''s tension or baffle alters its loading and thus its low-end and resonance, so repairs must restore original geometry.','Ribbon Design',ARRAY['Ribbon velocity microphone','Ribbon-microphone operation','Figure-8','Resonance','Corrugated ribbon']::text[],ARRAY['Assuming ribbon tension does not affect response.','Ignoring how the baffle and magnet gap load the ribbon.','Confusing a mass-controlled velocity ribbon with a stiffness-controlled design.']::text[],ARRAY['Re-ribboning a vintage microphone to original spec.','Explaining why ribbon tension sets resonance and response.','Comparing velocity and other ribbon loading schemes.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ribbon loading');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd2e8f93d-9be4-4f62-9dfc-ab2835929a5d','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d2e8f93d-9be4-4f62-9dfc-ab2835929a5d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d2e8f93d-9be4-4f62-9dfc-ab2835929a5d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '01cffc17-461a-44d5-b444-b6a6357a7025','Ribbon velocity microphone','A pressure-gradient microphone that uses a thin corrugated aluminum ribbon suspended in a strong magnetic field and open to sound on both sides, so it responds to particle velocity and yields a figure-eight pattern. The classic example is the RCA 44; the low-impedance ribbon feeds a step-up transformer to raise its very small output.','This microphone uses a thin metal ribbon hung between magnets. Sound reaches both sides, so the ribbon reacts to moving air. That gives a figure-eight pattern. The tiny signal passes through a transformer to boost it.','It provides a smooth, natural bidirectional pickup prized for its warm, detailed high-frequency character.','A technician uses a ribbon''s figure-eight nulls to reject spill and applies proximity bass boost tastefully on close sources, while handling the fragile ribbon with care.','Ribbon Microphone',ARRAY['Figure-8','Pressure-gradient microphones','Proximity effect','Ribbon-microphone operation','Velocity microphone']::text[],ARRAY['UNSAFE: Applying phantom power to a classic ribbon, through a miswired cable or patch, can burn out the ribbon or transformer.','UNSAFE: Blowing on or exposing the ribbon to strong wind or blasts can permanently stretch or tear it.','Expecting a high output level from a passive ribbon without adequate clean preamp gain.']::text[],ARRAY['Miking brass or strings for a natural tone.','Using figure-eight nulls to isolate two facing sources.','Explaining safe handling and storage of a ribbon microphone.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ribbon velocity microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '01cffc17-461a-44d5-b444-b6a6357a7025','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='01cffc17-461a-44d5-b444-b6a6357a7025') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='01cffc17-461a-44d5-b444-b6a6357a7025');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f1ac8635-fea3-41bc-a14e-f222f74c4b7d','Ribbon-microphone operation','The working principle of a ribbon microphone: sound-induced motion of a conductive ribbon within a magnetic gap induces a voltage by electromagnetic induction, proportional to the ribbon''s velocity. Because the ribbon impedance and output are very low, a step-up transformer raises the signal to a usable level; the doubly exposed ribbon is inherently bidirectional.','A ribbon microphone makes signal by moving a metal strip in a magnetic field. The motion creates a small voltage, following how fast the ribbon moves. A transformer steps that weak signal up. Because sound hits both sides, it hears front and back.','It explains how the fragile, low-output ribbon converts sound to electricity and why it needs a transformer and careful gain.','A technician provides ample clean preamp gain for a passive ribbon and never hot-patches phantom power into it during setup.','Ribbon Microphone',ARRAY['Ribbon velocity microphone','Ribbon loading','Step-up transformer','Electromagnetic induction','Figure-8']::text[],ARRAY['UNSAFE: Hot-patching a ribbon microphone into a live phantom-powered input can destroy the ribbon.','UNSAFE: Storing or transporting a ribbon microphone horizontally can let the ribbon sag over time; store it upright.','Expecting strong output and using too little clean gain, raising preamp noise.']::text[],ARRAY['Gain-staging a passive ribbon on a quiet preamp.','Explaining why ribbons need transformers.','Training staff on phantom-power precautions for ribbons.']::text[],'intermediate','e = B * l * v','The induced voltage equals the magnetic flux density times the ribbon''s length in the field times its velocity.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ribbon-microphone operation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f1ac8635-fea3-41bc-a14e-f222f74c4b7d','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f1ac8635-fea3-41bc-a14e-f222f74c4b7d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f1ac8635-fea3-41bc-a14e-f222f74c4b7d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8de2555b-d4d0-4aab-b1c0-5ea8c990a5bf','Second-order gradient microphone','A directional microphone whose output is proportional to the second spatial derivative of sound pressure, effectively the difference of two first-order gradients. This yields higher directivity (a narrower effective pattern and greater directivity index) than a first-order microphone, but with lower sensitivity, a steeper low-frequency roll-off, and stronger proximity effect. It is used in close-talking noise-canceling and some highly directional designs.','This microphone reacts to the change in the pressure gradient, one step beyond a normal directional microphone. That makes it much more focused on sound from one direction. In trade, it is quieter in output and rolls off bass fast. Close-talking noise-canceling microphones often use it.','It provides very high directivity and strong rejection of distant or ambient noise for a first-order microphone''s size.','A technician chooses a second-order noise-canceling microphone for a headset in loud surroundings, keeping it very close to the mouth to overcome its steep low-frequency roll-off.','Directional Design',ARRAY['Pressure-gradient microphones','Directivity','Proximity effect','Noise-canceling microphone','Directivity index']::text[],ARRAY['Expecting a flat far-field low-frequency response; second-order response rises faster and needs close use or strong equalization.','Assuming higher order brings no penalty in sensitivity or self-noise.','Using it far from the source, where its bass rejection starves the signal.']::text[],ARRAY['Selecting a headset boom microphone for a loud factory or aircraft.','Explaining why a noise-canceling microphone must sit right at the lips.','Comparing directivity of first- and second-order designs.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Second-order gradient microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8de2555b-d4d0-4aab-b1c0-5ea8c990a5bf','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8de2555b-d4d0-4aab-b1c0-5ea8c990a5bf') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8de2555b-d4d0-4aab-b1c0-5ea8c990a5bf');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4801a198-4319-4659-9611-50e45eee6f37','Sensitivity tolerance','The permitted deviation of a microphone''s actual sensitivity from its rated nominal value, stated in decibels (for example plus or minus 1 dB or plus or minus 2 dB) on datasheets. Tight tolerance matters for measurement microphones and for matched stereo or array pairs, where channel-to-channel consistency is essential.','This is how far a microphone''s real sensitivity may stray from its stated value. It is given in decibels, such as plus or minus one decibel. Two microphones of the same model can differ within this range. For matched pairs, tighter tolerance is better.','It quantifies unit-to-unit consistency so users know how closely microphones will match.','A technician buying a stereo pair orders factory-matched microphones with tight sensitivity tolerance, so the two channels balance without extra gain trimming.','Specification',ARRAY['Sensitivity','Matched pair','Free-field response','Measurement microphone','Sound-calibrator verification']::text[],ARRAY['Assuming two same-model microphones are identical when they may differ within tolerance.','Ignoring tolerance when building a stereo or surround array.','Confusing sensitivity tolerance with frequency-response tolerance.']::text[],ARRAY['Selecting matched pairs for coincident or spaced stereo.','Reading a datasheet''s tolerance before array calibration.','Trimming channel gains to compensate for sensitivity spread.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sensitivity tolerance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4801a198-4319-4659-9611-50e45eee6f37','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4801a198-4319-4659-9611-50e45eee6f37') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4801a198-4319-4659-9611-50e45eee6f37');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '97b799e0-8546-44f3-a436-a5b9364c5205','Side lobe','A secondary region of sensitivity in a microphone''s directivity pattern that lies off the main axis. Side lobes are most significant in highly directional line (shotgun) microphones at high frequencies, where the pattern breaks up into multiple lobes and off-axis sound is picked up unevenly.','This is an extra area of pickup off to the side of a directional microphone. It shows up most in shotgun microphones at high frequencies. There the tight pattern splits into several lobes. Off-axis sound then leaks in and can sound colored.','It describes off-axis leakage that limits how cleanly a directional microphone rejects sound outside its aim.','A technician aiming a shotgun microphone accepts that off-axis high frequencies from side lobes may color the sound and positions the microphone to keep noise sources out of those lobes.','Polar Pattern',ARRAY['Main lobe','Rear lobe','Directivity','Line microphone','Shotgun microphone']::text[],ARRAY['Assuming a shotgun microphone is uniformly narrow at all frequencies.','Ignoring side-lobe pickup that colors off-axis sound.','Treating the directivity as constant across the spectrum.']::text[],ARRAY['Boom-operating a shotgun microphone for dialogue.','Explaining off-axis coloration in a highly directional microphone.','Positioning a line microphone to keep noise out of side lobes.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Side lobe');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '97b799e0-8546-44f3-a436-a5b9364c5205','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='97b799e0-8546-44f3-a436-a5b9364c5205') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='97b799e0-8546-44f3-a436-a5b9364c5205');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1f05b4a2-0a6a-4f17-bd77-2508aeba66dd','Simultaneous comparison','An evaluation or calibration method in which two microphones are exposed to the same acoustic input at the same time so their outputs can be directly compared. In comparison calibration a microphone under test and a reference standard sit in the same field, and in critical listening it underlies careful level-matched A/B judgments.','This means comparing two microphones at the same moment in the same sound. Both hear the identical input. You then compare their outputs. Labs use it to calibrate against a reference, and listeners use it for fair A/B tests.','It removes changes over time and source variation from the comparison, isolating the difference between the two microphones.','A technician calibrating by comparison places the test and reference microphones together in a uniform field and reads the sensitivity difference directly.','Evaluation Method',ARRAY['Comparison calibration','Reference microphone','Sensitivity tolerance','Sound-calibrator verification','A/B testing']::text[],ARRAY['Not level-matching the two channels before judging, so the louder one seems ''better''.','Placing the two microphones where the sound field actually differs.','Comparing at different times and blaming the microphone for source changes.']::text[],ARRAY['Comparison-calibrating a microphone against a lab standard.','Running a level-matched A/B microphone shootout.','Verifying two array microphones truly match.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Simultaneous comparison');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1f05b4a2-0a6a-4f17-bd77-2508aeba66dd','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1f05b4a2-0a6a-4f17-bd77-2508aeba66dd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1f05b4a2-0a6a-4f17-bd77-2508aeba66dd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9256595f-d279-4c34-a8b3-fe021caa3e0a','Single diaphragm','A capsule construction using one diaphragm, in contrast to dual-diaphragm multipattern designs. A single-diaphragm microphone has a fixed polar pattern set by its acoustic rear-port network, and it is common in omni and cardioid condensers and in most dynamics.','This capsule uses just one diaphragm. Its pattern is built in and does not switch. Rear openings and passages set that pattern acoustically. Many cardioid and omni microphones, and most dynamics, work this way.','It offers a simpler, often more consistent capsule with a single, well-defined polar pattern.','A technician expecting one fixed pattern chooses a single-diaphragm cardioid and does not look for a pattern switch on it.','Capsule Design',ARRAY['Dual diaphragm','Rear-port delay networks','Cardioid','Multipattern','Diaphragm']::text[],ARRAY['Thinking a single-diaphragm microphone cannot be directional; it uses acoustic delay.','Expecting a switchable pattern from a single-diaphragm design.','Assuming single-diaphragm always means lower quality.']::text[],ARRAY['Choosing a fixed-pattern microphone for a specific job.','Explaining why a dynamic cardioid has one diaphragm.','Contrasting single- and dual-diaphragm condensers.']::text[],'beginner',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Single diaphragm');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9256595f-d279-4c34-a8b3-fe021caa3e0a','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9256595f-d279-4c34-a8b3-fe021caa3e0a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9256595f-d279-4c34-a8b3-fe021caa3e0a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e27dadc2-93b5-4423-938a-757938868262','Sound-calibrator verification','The routine field check of a measurement microphone and its measuring chain by fitting an acoustic calibrator that produces a known sound pressure level, then confirming or adjusting the instrument''s reading. Sound calibrators conforming to IEC 60942 typically deliver 94 dB (1 Pa) or 114 dB (10 Pa) at 1 kHz, and pistonphones commonly deliver 124 dB at 250 Hz.','This is a quick check of a measurement microphone before and after use. You clip on a calibrator that makes a known, steady tone. Then you confirm the meter reads the right level. Common levels are 94 or 114 decibels at 1000 hertz.','It confirms the whole measuring chain is accurate at the moment of use and provides a traceable check.','Before a noise survey a technician fits the 94 dB calibrator, sees the meter read 94.0 dB, and logs the check; a pistonphone reading also needs a static-pressure correction at altitude.','Calibration',ARRAY['Sound calibrator','Pistonphone','Reference environmental conditions','Sensitivity','Sound-level-meter microphone']::text[],ARRAY['Not seating the calibrator squarely, so a leak lowers the reading.','Forgetting the pistonphone static-pressure correction at altitude.','Skipping the after-measurement check that validates the whole session.']::text[],ARRAY['Field-checking a sound level meter before a survey.','Documenting calibration for a noise-exposure report.','Correcting a pistonphone reading for barometric pressure.']::text[],'intermediate','L_p = 20*log10(p / p_0),  p_0 = 20 uPa  ->  1 Pa = 94.0 dB','Sound pressure level equals twenty times the base-ten logarithm of pressure divided by the reference of twenty micropascals, so one pascal is about ninety-four decibels.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound-calibrator verification');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e27dadc2-93b5-4423-938a-757938868262','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e27dadc2-93b5-4423-938a-757938868262') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e27dadc2-93b5-4423-938a-757938868262');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6ecd9dbd-2b46-4a57-b3b9-9f3cd1c4dbea','Sound-intensity probe','A measurement device for sound intensity, the magnitude and direction of acoustic energy flow. The common form uses two closely spaced, phase-matched pressure microphones (the p-p, finite-difference method) to derive pressure and pressure gradient; a p-u form uses a pressure microphone with a particle-velocity sensor. A spacer sets the valid frequency range.','This probe measures how much sound energy flows and which way. One common type uses two matched microphones set a small distance apart. From their signals it works out pressure and its change. A spacer between them sets the usable frequency range.','It lets engineers locate noise sources and measure sound power even in imperfect, noisy environments.','A technician swaps to a shorter spacer for high-frequency work and keeps the two microphones tightly phase-matched, since phase error corrupts the intensity result.','Acoustic Measurement',ARRAY['Pressure–velocity probe','Sound intensity','Particle velocity','Phase matching','Sound-power measurement']::text[],ARRAY['Using the wrong spacer length for the frequency range of interest.','Ignoring microphone phase mismatch, which causes large intensity errors.','Applying the probe outside its valid measurement band.']::text[],ARRAY['Locating dominant noise sources on a machine.','Measuring sound power on a factory floor.','Ranking radiating panels by their energy flow.']::text[],'advanced','I_r ~ -(1/(rho*dr)) * p_avg * integral( (p2 - p1) dt )','With two spaced microphones, the intensity along the probe axis is proportional to the average pressure times the time integral of the pressure difference, divided by air density and spacing.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound-intensity probe');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6ecd9dbd-2b46-4a57-b3b9-9f3cd1c4dbea','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6ecd9dbd-2b46-4a57-b3b9-9f3cd1c4dbea') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6ecd9dbd-2b46-4a57-b3b9-9f3cd1c4dbea');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'eb5502ff-412b-496f-8ebe-a378cb3b0579','Sound-level-meter microphone','The measurement condenser microphone that forms the acoustic input of a sound level meter, meeting the tolerances of the IEC 61094 and IEC 61672 series. It is typically a half-inch capsule, of free-field or random-incidence type, with defined sensitivity and frequency response so the meter can achieve Class 1 or Class 2 accuracy.','This is the microphone built into a sound level meter. It is a precise measurement capsule, usually half an inch across. It comes in free-field or random-incidence types. Its accuracy sets whether the meter is Class 1 or Class 2.','It provides the accurate, standardized acoustic front end that gives a sound level meter its rated accuracy class.','A technician picks a free-field sound-level-meter microphone and points it at the source, or a random-incidence type for diffuse fields, matching the microphone to the measurement geometry.','Measurement Microphone',ARRAY['Sound-level meter','Free-field response','Random-incidence','Half-inch measurement microphone','Sensitivity tolerance']::text[],ARRAY['Using a free-field microphone in a diffuse field without correction, or vice versa.','Adding a windscreen or accessory that alters the calibrated response uncorrected.','Assuming any condenser microphone meets sound-level-meter tolerances.']::text[],ARRAY['Selecting the correct microphone type for an outdoor versus reverberant survey.','Verifying a meter''s accuracy class from its microphone.','Fitting the right calibrator adapter to the capsule.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound-level-meter microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'eb5502ff-412b-496f-8ebe-a378cb3b0579','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='eb5502ff-412b-496f-8ebe-a378cb3b0579') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='eb5502ff-412b-496f-8ebe-a378cb3b0579');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '44e58b13-bea2-4395-81af-2473f2320431','Source localization','Determining the direction or position of a sound source. Human listeners localize using binaural cues, chiefly interaural time differences at low frequencies and interaural level differences at high frequencies, while microphone arrays localize by comparing time-of-arrival differences or by beamforming across multiple capsules.','This means finding where a sound comes from. People use two ears to judge direction. Small timing and loudness differences between the ears give the clue. Microphone arrays do the same by comparing when sound reaches each microphone.','It underlies stereo and surround imaging and array-based direction finding and beamforming.','A technician spaces or angles microphones to encode arrival-time and level differences that let listeners place instruments across the stereo image.','Spatial Audio',ARRAY['Interaural time difference','Microphone array','Beamforming','Spaced arrays','Stereo imaging']::text[],ARRAY['Assuming level differences alone carry all direction cues; timing matters, especially at low frequencies.','Ignoring how spacing and angle set the stereo image.','Confusing perceptual localization with array direction-finding methods.']::text[],ARRAY['Designing a stereo pair for a stable image.','Steering a microphone-array beam toward a talker.','Explaining why a mono source seems to come from one direction.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Source localization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '44e58b13-bea2-4395-81af-2473f2320431','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='44e58b13-bea2-4395-81af-2473f2320431') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='44e58b13-bea2-4395-81af-2473f2320431');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8d719e3b-8206-47ed-937a-8a4f908a2ec1','Spaced arrays','Stereo or multichannel microphone techniques using two or more microphones separated by a distance, so the channels capture time-of-arrival (phase) differences as well as any level differences. Wide spacing, as in A-B pairs and spaced omnis, yields a strong sense of spaciousness but risks a weak center image and poorer mono compatibility.','This technique places microphones some distance apart. Sound reaches each one at a slightly different time. Those timing differences create a wide, spacious stereo image. Very wide spacing can leave a weak center and cause problems when summed to mono.','It captures a sense of space and width by encoding arrival-time differences between channels.','A technician spaces a pair of omnis a few feet apart for an orchestra to get width, checking mono compatibility and adding a center microphone to fill a ''hole in the middle''.','Stereo Technique',ARRAY['A-B stereo','Coincident pair','Decca tree','Mono compatibility','Source localization']::text[],ARRAY['Spacing microphones so wide that the center image collapses, leaving a ''hole in the middle''.','Ignoring mono compatibility, since arrival-time differences cause comb filtering when summed.','Assuming spaced omnis image like a coincident pair.']::text[],ARRAY['Recording an orchestra with a spaced omni pair or Decca tree.','Choosing spacing to balance width and center focus.','Checking mono compatibility before broadcast.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spaced arrays');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8d719e3b-8206-47ed-937a-8a4f908a2ec1','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8d719e3b-8206-47ed-937a-8a4f908a2ec1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8d719e3b-8206-47ed-937a-8a4f908a2ec1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '24660268-2829-4a69-a3f4-df9568157297','Spatial aliasing','Spatial aliasing is the ambiguity that arises when a microphone array samples a sound field with sensor spacing too large relative to the wavelength, so waves from different directions produce identical inter-sensor phase differences. It appears above the spatial Nyquist frequency f = c/(2d), where d is the sensor spacing, causing false lobes or errors in beamforming and direction finding.','An array of mics samples sound at set spacings. If the mics sit too far apart, high notes confuse it. Two different directions can then look the same. This creates false beams and location errors.','Understanding spatial aliasing sets the upper frequency and the maximum sensor spacing an array can use before its directional output becomes ambiguous.','A technician keeps spacing at or below half the shortest wavelength; for d = 0.02 m and c = 343 m/s, aliasing starts at f = 343/(2*0.02) = 8575 Hz.','Array signal processing',ARRAY['Spherical harmonic order','Three-dimensional directivity','Steering vector','Superdirectivity']::text[],ARRAY['Assuming closer mic spacing always helps, when it also limits low-frequency directivity.','Confusing spatial aliasing with time-domain sampling aliasing.','Ignoring that aliasing worsens for sources arriving off the array axis.']::text[],ARRAY['Choosing capsule spacing for a broadside line array of microphones.','Explaining false beamformer lobes above a few kilohertz.','Setting the usable frequency band of a sound-intensity probe.']::text[],'advanced','f_alias = c / (2 d)','The spatial aliasing frequency equals the speed of sound divided by twice the sensor spacing.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spatial aliasing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '24660268-2829-4a69-a3f4-df9568157297','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='24660268-2829-4a69-a3f4-df9568157297') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='24660268-2829-4a69-a3f4-df9568157297');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0f813626-776b-4f27-916e-ac54e5c73cb5','Spherical harmonic order','Spherical harmonic order N is the truncation degree of the spherical-harmonic expansion used to describe a sound field or a spherical microphone array''s directivity, requiring (N+1)^2 coefficients. The highest order a rigid sphere of radius r can capture at frequency f is set roughly by N >= kr, where k = 2*pi*f/c is the acoustic wavenumber.','A round mic array describes sound using math patterns of rising detail. The order is how many detail levels it keeps. Higher order means finer direction detail. Small arrays lose high orders at low frequencies.','The order fixes how finely a spherical array or Ambisonic system can resolve or reproduce direction, trading detail against the number of channels needed.','For order N you need (N+1)^2 channels; a radius r = 0.042 m array at f = 1 kHz has kr = 2*pi*1000*0.042/343 = 0.77, so only order 0-1 is reliable there.','Array signal processing',ARRAY['Spatial aliasing','Three-dimensional directivity','Zero-order microphone','Superdirectivity']::text[],ARRAY['Thinking a higher-order array works at all frequencies equally.','Forgetting that order N needs (N+1)^2 microphones, not N.','Confusing spherical harmonic order with the number of capsules alone.']::text[],ARRAY['Choosing an Ambisonic recording format (first-order vs higher-order).','Specifying a spherical microphone array for room acoustics.','Explaining why a small array loses spatial detail at low frequency.']::text[],'advanced','channels = (N + 1)^2 ; N ~ k r , k = 2*pi*f/c','The number of spherical-harmonic coefficients equals order plus one, squared; the usable order rises with wavenumber times sphere radius.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spherical harmonic order');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0f813626-776b-4f27-916e-ac54e5c73cb5','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0f813626-776b-4f27-916e-ac54e5c73cb5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0f813626-776b-4f27-916e-ac54e5c73cb5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e35f0d0d-b7fa-44fc-adfb-6c347754cb17','Supercardioid pattern','The supercardioid is a first-order directional polar pattern described by r(theta) = 0.37 + 0.63*cos(theta), giving the maximum ratio of front-hemisphere to rear-hemisphere sensitivity of any first-order pattern. It has two rear nulls near 126 degrees and a directivity index of about 5.7 dB, with slightly more rear pickup than the hypercardioid.','A supercardioid mic hears best from the front. It rejects sound from the back very well. Its two deepest dead spots sit at about 126 degrees off-front. It has a small rear lobe you must watch.','It maximizes rejection of the whole rear half-space, so it suits noisy stages and film work where sources sit in front and unwanted sound comes from behind.','A technician aims the rear nulls (about 126 degrees) at a stage monitor to reduce feedback; the small rear lobe still needs care when placing musicians behind the mic.','Polar patterns',ARRAY['Cardioid pattern','Hypercardioid pattern','Three-dimensional directivity','Zero-order microphone']::text[],ARRAY['Assuming the deepest null is at 180 degrees; it is near 126 degrees.','Confusing supercardioid with hypercardioid, which has a higher directivity index.','Forgetting the rear lobe when placing foldback speakers behind the mic.']::text[],ARRAY['Reducing monitor feedback by aiming the null at a wedge.','Booming dialogue on a noisy film set.','Miking a single vocalist in a loud band on stage.']::text[],'intermediate','r(theta) = 0.37 + 0.63*cos(theta)','Sensitivity equals 0.37 plus 0.63 times the cosine of the angle off the main axis.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Supercardioid pattern');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e35f0d0d-b7fa-44fc-adfb-6c347754cb17','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e35f0d0d-b7fa-44fc-adfb-6c347754cb17') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e35f0d0d-b7fa-44fc-adfb-6c347754cb17');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ffd9d7b8-86b9-4438-b814-68f687155890','Surface potential','Surface potential is the electrostatic potential, in volts, at a charged surface relative to a reference, and in an electret microphone it is the quasi-permanent voltage the charged electret film maintains across the capsule gap. This stored surface potential replaces the external polarizing supply of a conventional condenser capsule, and for a stored charge Q on capacitance C it equals V = Q/C.','An electret film holds a trapped electric charge for years. That charge sets a steady voltage at its surface. This built-in voltage does the job of a battery bias. It lets the capsule work without an outside polarizing supply.','The stored surface potential polarizes an electret capsule internally, so the microphone needs no separate high-voltage bias supply to convert sound into a signal.','A technician can gauge the effective bias from V = Q/C; a stored charge of 1 nC on a 10 pF capsule gives V = 1e-9/10e-12 = 100 V of equivalent polarizing potential.','Transducer physics',ARRAY['Transduction','Transducer sensitivity','Zero-order microphone','Transformer effects']::text[],ARRAY['Thinking electret charge is permanent; it slowly decays over decades, especially with heat and humidity.','Confusing the electret''s surface potential with the phantom or plug-in supply voltage.','Assuming a higher surface potential always means higher output regardless of gap and area.']::text[],ARRAY['Explaining why an electret lavalier needs only low-voltage plug-in power.','Diagnosing lost sensitivity in an old, heat-aged electret capsule.','Comparing electret bias to externally polarized condenser capsules.']::text[],'advanced','V = Q / C','Surface potential equals the stored charge divided by the capacitance.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Surface potential');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ffd9d7b8-86b9-4438-b814-68f687155890','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ffd9d7b8-86b9-4438-b814-68f687155890') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ffd9d7b8-86b9-4438-b814-68f687155890');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2d933c60-bec2-453b-b265-12cda44131d4','Surface-velocity measurement','Surface-velocity measurement determines the instantaneous velocity of a vibrating surface, most often by laser Doppler vibrometry, where the Doppler shift f_D of light reflected from the surface gives velocity v = (lambda/2)*f_D. It provides non-contact calibration and diagnosis of diaphragms, panels, and transducer parts without adding mass.','This measures how fast a surface moves as it vibrates. A laser beam bounces off the surface. The returning light shifts in frequency with the motion. That shift is turned into a velocity, with no sensor touching the part.','It gives an accurate, non-contact measure of vibration velocity, used to calibrate references and study how diaphragms and panels move.','With a helium-neon laser (lambda = 633 nm) and a Doppler shift f_D = 1 kHz, velocity v = (633e-9/2)*1000 = 3.16e-4 m/s, about 0.32 mm/s.','Vibration metrology',ARRAY['Transduction','Transducer sensitivity','Traceability chain','Thermoacoustic sensing']::text[],ARRAY['Confusing measured velocity with displacement or acceleration without integrating or differentiating.','Ignoring speckle noise and beam alignment on rough or moving surfaces.','Adding a heavy contact sensor that changes the very motion being measured.']::text[],ARRAY['Calibrating a vibration reference traceable to national standards.','Mapping diaphragm break-up modes on a loudspeaker or microphone.','Checking panel vibration without mass-loading the structure.']::text[],'advanced','v = (lambda / 2) * f_D','Surface velocity equals half the laser wavelength times the measured Doppler shift frequency.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Surface-velocity measurement');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2d933c60-bec2-453b-b265-12cda44131d4','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2d933c60-bec2-453b-b265-12cda44131d4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2d933c60-bec2-453b-b265-12cda44131d4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fe297bff-130e-4039-a53b-1a7da85dbf81','Thermoacoustic sensing','Thermoacoustic sensing detects sound through thermal effects rather than diaphragm motion, typically by measuring how acoustic air movement cools a heated wire or element. The Microflown particle-velocity sensor, for example, uses two closely spaced heated wires and reads the temperature difference caused by acoustic particle velocity.','Most mics use a moving diaphragm. Thermal sensors instead use tiny heated wires. Moving air from sound cools the wires unevenly. The sensor reads that temperature change to hear the sound.','It measures acoustic particle velocity directly and works at very small size, filling roles where a moving diaphragm is impractical, such as tiny probes and intensity sensors.','A technician pairs a thermal particle-velocity sensor with a pressure microphone to measure sound intensity and to find sources in a small probe.','Transduction principle',ARRAY['Velocity-sensitive microphones','Surface-velocity measurement','Transduction','Velocity microphone']::text[],ARRAY['Assuming all microphones sense pressure; thermal sensors respond to particle velocity.','Expecting a flat, high-level output; thermal sensors are sensitive but need careful signal conditioning.','Confusing thermoacoustic sensing (hearing sound) with thermophones (making sound).']::text[],ARRAY['Building a compact sound-intensity probe from velocity and pressure sensors.','Locating noise sources in a tight engine bay.','Measuring particle velocity near a vibrating surface.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Thermoacoustic sensing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fe297bff-130e-4039-a53b-1a7da85dbf81','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fe297bff-130e-4039-a53b-1a7da85dbf81') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fe297bff-130e-4039-a53b-1a7da85dbf81');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7a833829-53e2-49f0-a648-e81d350f5771','Three-dimensional directivity','Three-dimensional directivity describes how a microphone''s sensitivity varies over the full sphere of incidence angles, not just one plane. It is summarized by the directivity factor Q and the directivity index DI = 10*log10(Q), which compare on-axis response to the average over all directions.','A polar plot shows pickup in one flat slice. Real mics respond in all directions at once. Three-dimensional directivity maps that full sphere. One number, the directivity index, sums up how focused the mic is.','It gives a complete picture of a microphone''s directional response, letting technicians predict reach, off-axis coloration, and rejection of reverberant sound.','A technician reads the directivity index to compare reach; a hypercardioid with Q about 4 has DI = 10*log10(4) = 6.0 dB over an omni.','Directional response',ARRAY['Supercardioid pattern','Spherical harmonic order','Zero-order microphone','Velocity microphone']::text[],ARRAY['Judging a mic from a single-plane polar plot and missing vertical off-axis behaviour.','Treating directivity index as frequency independent, when it usually varies with frequency.','Confusing the directivity factor Q with the electrical quality factor Q.']::text[],ARRAY['Comparing reach of two shotgun microphones for field recording.','Predicting reverberant pickup in a large hall.','Explaining why off-axis instruments sound colored.']::text[],'intermediate','DI = 10 * log10(Q)','Directivity index in decibels equals ten times the base-ten logarithm of the directivity factor.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Three-dimensional directivity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7a833829-53e2-49f0-a648-e81d350f5771','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7a833829-53e2-49f0-a648-e81d350f5771') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7a833829-53e2-49f0-a648-e81d350f5771');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5234c276-bc12-47c5-a24a-f897737e9074','Top-port microphone','A top-port microphone is a surface-mount MEMS microphone whose sound inlet is in the top of the package lid, opposite the solder pads, so sound reaches the diaphragm from above the circuit board. It contrasts with a bottom-port design, whose inlet is on the pad side and couples to a hole in the board.','A MEMS mic is a tiny chip mic on a circuit board. A top-port model has its sound hole on top of the case. Sound comes in from above, away from the board. This shapes how it is mounted in a device.','The top-port layout lets designers admit sound from above the board, simplifying the acoustic path in devices where a board hole for a bottom port is impractical.','A technician places a top-port MEMS mic under a case opening and seals it to the lid port, keeping the board free of a through-hole and its own gasket.','MEMS microphones',ARRAY['Transducer sensitivity','Total dynamic range','Transduction','Ultrasonic microphone']::text[],ARRAY['Blocking the tiny top port with adhesive, mesh, or a misaligned gasket.','Assuming top-port and bottom-port parts are drop-in interchangeable on the same board.','Reflowing the part with the port open, letting flux or debris enter.']::text[],ARRAY['Laying out the microphone acoustic path in a smartphone or laptop.','Choosing between top-port and bottom-port MEMS parts for an enclosure.','Diagnosing muffled capture from a clogged top port.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Top-port microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5234c276-bc12-47c5-a24a-f897737e9074','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5234c276-bc12-47c5-a24a-f897737e9074') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5234c276-bc12-47c5-a24a-f897737e9074');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1584296c-491d-4c72-9bc8-e2981828ee54','Total dynamic range','A microphone''s total dynamic range is the span in decibels between the maximum sound pressure level it handles at a stated distortion limit and its equivalent self-noise level. It equals DR = L_max - L_noise, where L_noise is the A-weighted equivalent noise level per IEC 60268-4.','Every mic has a loudest sound it can take cleanly. It also has a soft hiss of its own noise. The dynamic range is the gap between those two. A wide range handles both quiet and very loud sources.','It tells a technician the total loudness window a microphone captures cleanly, from its noise floor up to the onset of heavy distortion.','A technician subtracts the two datasheet figures; a mic with 130 dB max SPL and 15 dB-A self-noise has a total dynamic range of 130 - 15 = 115 dB.','Microphone specification',ARRAY['Transducer sensitivity','Ultrasonic microphone','Top-port microphone','Three-dimensional directivity']::text[],ARRAY['Comparing max SPL figures quoted at different distortion percentages.','Ignoring that self-noise is usually A-weighted, changing the number.','Confusing the microphone''s dynamic range with the recorder''s or preamp''s.']::text[],ARRAY['Choosing a mic that survives a loud drum kit yet stays quiet on soft passages.','Reading a datasheet to compare two studio condensers.','Explaining why a quiet room needs a low self-noise mic.']::text[],'intermediate','DR = L_max - L_noise','Total dynamic range equals maximum sound pressure level minus the equivalent self-noise level.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Total dynamic range');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1584296c-491d-4c72-9bc8-e2981828ee54','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1584296c-491d-4c72-9bc8-e2981828ee54') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1584296c-491d-4c72-9bc8-e2981828ee54');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3029d810-18a5-4d85-b32a-f7a045b86fd9','Traceability chain','A traceability chain is the unbroken sequence of calibrations, each with stated uncertainty, that links a working microphone''s calibration to the SI units through national metrology institutes. For microphones it typically runs from a field mic to a laboratory-standard mic calibrated by reciprocity per IEC 61094, up to primary standards at bodies such as NIST or PTB.','A calibration is only trusted if you can trace it upward. Each step compares one instrument to a better one. The chain ends at a national standards lab. This links your mic to the official unit of measure.','It gives measurements documented, defensible accuracy by tying every calibration back to recognized primary standards with known uncertainty at each link.','A technician keeps calibration certificates that name each reference and its uncertainty, so a sound-level measurement can be traced from the field mic to national standards.','Metrology',ARRAY['Transducer sensitivity','Surface-velocity measurement','Total dynamic range','Transduction']::text[],ARRAY['Treating a calibration sticker as valid without a documented uncertainty and reference.','Assuming any lab calibration is automatically traceable to SI.','Breaking the chain by using an uncalibrated intermediate reference.']::text[],ARRAY['Preparing microphones for accredited noise or product compliance testing.','Auditing a calibration lab against ISO/IEC 17025.','Explaining why a field calibrator itself needs periodic calibration.']::text[],'advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Traceability chain');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3029d810-18a5-4d85-b32a-f7a045b86fd9','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3029d810-18a5-4d85-b32a-f7a045b86fd9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3029d810-18a5-4d85-b32a-f7a045b86fd9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9b0bbda9-7530-4134-a471-ffc3b26a8b4c','Transducer sensitivity','Transducer sensitivity is the ratio of a microphone''s electrical output to the acoustic input that produces it, usually stated in millivolts per pascal or in decibels re 1 V/Pa. In level form it is L = 20*log10(S/S_ref), with S in volts per pascal and S_ref = 1 V/Pa, measured per IEC 60268-4.','Sensitivity says how much signal a mic makes for a given sound. A high figure means a strong output for the same loudness. It is often given in millivolts per pascal. It sets how much preamp gain you need.','It lets a technician predict output level and required preamp gain, and compare how strongly different microphones respond to the same sound pressure.','A mic rated 10 mV/Pa converts to level as L = 20*log10(0.010/1) = -40 dBV re 1 V/Pa, so a soft source needs plenty of clean preamp gain.','Microphone specification',ARRAY['Transduction','Total dynamic range','Surface potential','Transformer effects']::text[],ARRAY['Mixing dBV and dBu references when comparing sensitivity figures.','Assuming higher sensitivity means lower noise; they are separate specs.','Forgetting sensitivity is stated at 1 kHz and varies across frequency.']::text[],ARRAY['Setting preamp gain for a quiet dynamic versus a hot condenser.','Comparing two mics from their datasheet sensitivity figures.','Predicting output level before a session to avoid clipping or hiss.']::text[],'intermediate','L = 20 * log10(S / S_ref)','Sensitivity level equals twenty times the base-ten log of the sensitivity divided by the one-volt-per-pascal reference.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Transducer sensitivity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9b0bbda9-7530-4134-a471-ffc3b26a8b4c','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9b0bbda9-7530-4134-a471-ffc3b26a8b4c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9b0bbda9-7530-4134-a471-ffc3b26a8b4c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '195a3afb-edaa-496c-8fb3-2ea3d59a7768','Transduction','Transduction is the conversion of energy from one physical form to another; in a microphone it is the conversion of acoustic energy in air into an electrical signal. The conversion mechanism, such as electrodynamic, capacitive, or piezoelectric, defines the microphone type and many of its properties.','Transduction means changing one kind of energy into another. A microphone turns sound in the air into an electrical signal. The way it does this sets the mic type. Common methods use coils, charged plates, or crystals.','It is the core job of any microphone, turning acoustic pressure or velocity into a usable voltage that the rest of the audio chain can amplify and record.','A technician chooses a microphone by its transduction method; a moving-coil dynamic survives high levels, while a capacitive condenser gives finer detail.','Transduction principle',ARRAY['Transducer sensitivity','Surface potential','Velocity microphone','Zero-order microphone']::text[],ARRAY['Using ''transduction'' loosely for amplification, which is a different process.','Assuming all microphones use the same conversion method.','Forgetting that the transduction type shapes noise, level handling, and response.']::text[],ARRAY['Explaining why dynamic and condenser mics behave differently.','Introducing how microphones and loudspeakers reverse the same idea.','Choosing a rugged transduction type for high-SPL sources.']::text[],'beginner',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Transduction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '195a3afb-edaa-496c-8fb3-2ea3d59a7768','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='195a3afb-edaa-496c-8fb3-2ea3d59a7768') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='195a3afb-edaa-496c-8fb3-2ea3d59a7768');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e36fc37d-bbc0-43e0-8f9c-d5109331dc6d','Transformer effects','Transformer effects are the ways an audio transformer in a microphone''s output stage shapes its behaviour, including voltage step-up, impedance conversion, galvanic isolation, and common-mode rejection. The turns ratio n = N2/N1 sets the voltage ratio, while the impedance ratio scales as n squared, per Z2/Z1 = (N2/N1)^2.','Many mics have a small output transformer. It can raise the signal voltage. It also changes impedance and blocks unwanted DC. The turns ratio decides how much the voltage and impedance change.','The transformer matches the capsule to the line, boosts weak signals such as a ribbon''s, isolates the capsule electrically, and helps reject hum picked up on the cable.','A 1:10 ribbon step-up transformer multiplies output voltage by 10 and impedance by 10^2 = 100, lifting a very low ribbon output to a usable level.','Microphone electronics',ARRAY['Transducer sensitivity','Velocity microphone','Transduction','Surface potential']::text[],ARRAY['Assuming a transformer adds power; it trades voltage against current.','Ignoring core saturation and bandwidth limits at high level or low frequency.','UNSAFE: Hot-patching a transformer-coupled ribbon mic or using a faulty cable while phantom power is on can push DC through the ribbon and destroy it.']::text[],ARRAY['Choosing a step-up transformer for a low-output ribbon microphone.','Explaining why a transformer-coupled mic rejects cable hum well.','Diagnosing low-frequency distortion from a saturating output transformer.']::text[],'advanced','V2/V1 = N2/N1 ; Z2/Z1 = (N2/N1)^2','The voltage ratio equals the turns ratio, and the impedance ratio equals the turns ratio squared.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Transformer effects');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e36fc37d-bbc0-43e0-8f9c-d5109331dc6d','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e36fc37d-bbc0-43e0-8f9c-d5109331dc6d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e36fc37d-bbc0-43e0-8f9c-d5109331dc6d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e88164b4-4438-496e-bd13-a9f5f1d9dfc5','Ultrasonic microphone','An ultrasonic microphone is a transducer designed to respond to sound above the roughly 20 kHz upper limit of human hearing, often extending to tens or hundreds of kilohertz. Small measurement condensers (for example 1/8-inch capsules per IEC 61094), capacitive MEMS, and CMUT devices are common, since a small diaphragm raises the usable upper frequency.','Human ears stop around 20 kHz. An ultrasonic mic hears higher than that. It uses a very small diaphragm to catch fast vibrations. Bats, leak testing, and lab work all use these mics.','It captures sound above the audible band for tasks such as ultrasonic leak detection, bat and animal study, and high-frequency acoustic measurement.','A technician picks a small-diaphragm measurement mic to catch a 40 kHz ultrasonic leak signal that a normal studio mic would roll off long before.','Specialized microphones',ARRAY['Ultrasonic-band response','Transducer sensitivity','Top-port microphone','Total dynamic range']::text[],ARRAY['Assuming any measurement mic reaches ultrasonic frequencies; capsule size sets the limit.','Sampling too slowly, so ultrasonic content aliases into the audible band.','Ignoring that sensitivity usually drops as frequency rises into ultrasound.']::text[],ARRAY['Detecting compressed-air or vacuum leaks by their ultrasonic hiss.','Recording bat echolocation in the field.','Measuring transducer response above 20 kHz in a lab.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ultrasonic microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e88164b4-4438-496e-bd13-a9f5f1d9dfc5','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e88164b4-4438-496e-bd13-a9f5f1d9dfc5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e88164b4-4438-496e-bd13-a9f5f1d9dfc5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4181c7c6-6a89-4b0d-b037-ccd01f780a71','Ultrasonic-band response','Ultrasonic-band response is a microphone''s sensitivity as a function of frequency above about 20 kHz, the top of the audible range. It is limited mainly by diaphragm size and the capsule''s mechanical resonance, so smaller diaphragms generally extend the usable ultrasonic response.','This is how well a mic works above human hearing. Above 20 kHz, most mics lose output fast. A smaller diaphragm keeps working to higher notes. The capsule''s resonance sets the top limit.','It defines how far above the audible band a microphone stays useful, which matters for ultrasonic measurement and for capturing airy high-frequency detail.','A technician checks the datasheet''s high-frequency curve; a 1/4-inch measurement mic may stay usable to 80 kHz, while a large-diaphragm studio mic rolls off well below 40 kHz.','Frequency response',ARRAY['Ultrasonic microphone','Transducer sensitivity','Total dynamic range','Three-dimensional directivity']::text[],ARRAY['Assuming a wide audible response guarantees good ultrasonic response.','Overlooking that diaphragm resonance can create a peak before the roll-off.','Recording ultrasonic content without a high enough sample rate.']::text[],ARRAY['Selecting a capsule size for high-frequency acoustic measurement.','Comparing measurement mics by their upper frequency limit.','Explaining why large-diaphragm mics roll off sooner up top.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ultrasonic-band response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4181c7c6-6a89-4b0d-b037-ccd01f780a71','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4181c7c6-6a89-4b0d-b037-ccd01f780a71') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4181c7c6-6a89-4b0d-b037-ccd01f780a71');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fa8575ca-5b8a-4331-81f5-400d39bfbb65','Velocity microphone','A velocity microphone is a pressure-gradient transducer whose diaphragm, classically a thin ribbon, responds to the acoustic particle velocity created by the pressure difference across its two open faces. Because both faces are exposed, it naturally has a bidirectional figure-of-eight pattern, r(theta) = cos(theta), with nulls at the sides.','A velocity mic senses air motion, not just pressure. Sound reaches both sides of its thin ribbon. The difference in pressure moves the ribbon. This gives a figure-eight pickup that is deaf at the sides.','It provides a naturally bidirectional response and smooth, open sound, useful for blumlein stereo, mid-side work, and rejecting sound arriving from the sides.','A technician aims a ribbon velocity mic''s side nulls at an unwanted source; its figure-eight also strongly boosts bass up close through proximity effect.','Transducer principle',ARRAY['Velocity-sensitive microphones','Transformer effects','Zero-order microphone','Three-dimensional directivity']::text[],ARRAY['Forgetting the strong rear lobe is fully live and equal to the front.','Ignoring the heavy proximity bass boost at close range.','UNSAFE: Applying or hot-patching phantom power with faulty or unbalanced wiring can burn out a vintage ribbon.']::text[],ARRAY['Setting up a Blumlein pair with two figure-eight microphones.','Using side nulls to reject a nearby instrument.','Recording brass or vocals for a warm, smooth ribbon tone.']::text[],'intermediate','r(theta) = cos(theta)','Sensitivity equals the cosine of the angle from the front axis, giving a figure-of-eight pattern.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Velocity microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fa8575ca-5b8a-4331-81f5-400d39bfbb65','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fa8575ca-5b8a-4331-81f5-400d39bfbb65') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fa8575ca-5b8a-4331-81f5-400d39bfbb65');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '873cea65-f3ea-47a1-945b-e93b23576688','Velocity-sensitive microphones','Velocity-sensitive microphones are the class of transducers that respond to acoustic particle velocity, sensed as a pressure gradient across the diaphragm, rather than to absolute pressure. This class includes ribbon and other pressure-gradient designs and thermal particle-velocity sensors, and it underlies all first-order directional patterns.','Some mics react to how fast air moves, not just its pressure. They sense the pressure difference across the diaphragm. Ribbon mics are the classic example. This response is what makes a mic directional.','This response type gives microphones their directionality and their proximity effect, and it is the basis for figure-eight, cardioid, and related patterns.','A technician exploits the class''s proximity bass boost for a fuller close vocal, and its directionality to reject off-axis sound.','Transducer principle',ARRAY['Velocity microphone','Thermoacoustic sensing','Zero-order microphone','Supercardioid pattern']::text[],ARRAY['Confusing velocity (gradient) response with pressure (omnidirectional) response.','Overlooking that these mics show proximity effect while pure pressure mics do not.','Assuming velocity response means the mic is fragile; only some designs, like ribbons, are.']::text[],ARRAY['Explaining why directional mics boost bass up close.','Grouping ribbon and gradient condenser mics by response type.','Teaching how first-order polar patterns arise from velocity response.']::text[],'intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Velocity-sensitive microphones');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '873cea65-f3ea-47a1-945b-e93b23576688','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='873cea65-f3ea-47a1-945b-e93b23576688') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='873cea65-f3ea-47a1-945b-e93b23576688');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '49cd7d65-ae34-4106-81cd-69683d9fb188','Zero-order microphone','A zero-order microphone is a pressure transducer whose output depends only on scalar sound pressure, giving an omnidirectional response that is the order-zero (monopole) term in the spherical-harmonic or gradient hierarchy. Its sensitivity is ideally equal in every direction, r(theta) = 1, in contrast to the order-one gradient microphones that add direction.','A zero-order mic hears equally from every direction. It reacts only to sound pressure at one point. This makes it omnidirectional. It is the simplest, base level in the family of directional mics.','It captures sound pressure without directional coloration, serving as the omnidirectional building block for measurement mics and for higher-order directional arrays.','A technician uses a zero-order omni measurement mic for flat, uncolored room and level measurements, and combines it with gradient mics to build directional patterns.','Transducer principle',ARRAY['Velocity microphone','Spherical harmonic order','Three-dimensional directivity','Transduction']::text[],ARRAY['Assuming an omni mic has no directionality at all frequencies; it narrows at high frequency as the body shadows sound.','Confusing zero-order (pressure, omni) with first-order (gradient, directional) mics.','Expecting proximity bass boost from a pressure mic; it has none.']::text[],ARRAY['Choosing an omni measurement mic for flat room analysis.','Building a first-order array from pressure and gradient capsules.','Explaining the base term of a spherical-harmonic microphone system.']::text[],'intermediate','r(theta) = 1','Normalized sensitivity equals one for all angles, giving an omnidirectional response.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Zero-order microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '49cd7d65-ae34-4106-81cd-69683d9fb188','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='49cd7d65-ae34-4106-81cd-69683d9fb188') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='49cd7d65-ae34-4106-81cd-69683d9fb188');
